    "farmer_carry": ExerciseGuide(["Встань между двумя гантелями или двумя нагруженными сумками.", "Согни колени, держи спину прямой и подними их.", "Иди мелкими шагами, плечи назад, взгляд вперёд.", "Иди 20 секунд, поставь вес и отдохни, всего 3 подхода."], ["Наклоняться в сторону или позволять плечам округляться вперёд.", "Округлять спину, когда поднимаешь или ставишь вес."], "Выбери вес, с которым сможешь закончить каждый подход с хорошей техникой, и держи нагрузку на обе стороны одинаковой."),
    "glute_bridge": ExerciseGuide(["Ляг на спину, колени согнуты, стопы на полу на ширине бёдер.", "Надави пятками в пол и подними таз к потолку.", "Сожми ягодицы вверху на 2 секунды.", "Медленно опустись, 12 повторений за подход, всего 3 подхода."], ["Отталкиваться носками, а не пятками.", "Слишком прогибать поясницу вверху."], "Если чувствуешь работу в ягодицах, а не в пояснице, ты делаешь всё правильно."),
    "goblet_squat": ExerciseGuide(["Прижми к груди одну гантель или нагруженный рюкзак обеими руками.", "Встань, ноги на ширине плеч, носки чуть развернуты наружу.", "Сядь между пяток, грудь вверх, затем встань обратно.", "Сделай 8 повторений и отдохни, всего 3 подхода."], ["Заваливать колени внутрь.", "Округлять спину и опускать грудь."], "Выбери вес, с которым сможешь закончить каждое повторение с хорошей техникой."),
    "hanging_knee_raise": ExerciseGuide(["Возьмись за турник хватом сверху и повисни на прямых руках.", "Опусти плечи вниз, подальше от ушей.", "Подними оба колена до уровня таза без раскачивания, затем медленно опусти.", "Сделай 5 повторений, спустись и отдохни, всего 3 подхода."], ["Раскачивать тело, чтобы забросить колени вверх.", "Висеть с плечами у ушей."], "Перед тем как повиснуть, проверь, что турник надёжный, и спускайся, а не спрыгивай."),
    "high_knees": ExerciseGuide(["Встань прямо, ноги на ширине бёдер.", "Беги на месте, поднимая каждое колено до уровня таза.", "Активно работай руками и оставайся лёгким на подушечках стоп.", "Продолжай 20 секунд, всего 3 подхода."], ["Отклоняться назад, когда колени идут вверх.", "Топать по полу всей стопой."], "Замедлись до марша с высоким подъёмом колен, если сбилось дыхание."),
    "hiit_workout": ExerciseGuide(["Разомнись 3 минуты: марш на месте и круги руками.", "Делай берпи, скалолаза и приседания с прыжком, по 45 секунд каждое.", "Отдыхай 15 секунд между движениями и дыши глубоко.", "Сделай 4 круга, затем медленно ходи, пока дыхание не восстановится."], ["Позволять технике страдать ради скорости.", "Задерживать дыхание на тяжёлых интервалах."], "Двигайся в своём темпе; закончить все 4 круга важнее, чем быстро начать."),
    "hip_flexor_stretch": ExerciseGuide(["Встань на одно колено, другая стопа стоит на полу перед тобой.", "Слегка подверни таз под себя и сожми ягодицу задней ноги.", "Мягко сдвигайся вперёд, пока не почувствуешь растяжение в передней части тазобедренного сустава.", "Задержись на 30 секунд, медленно дыша, затем смени сторону."], ["Прогибать поясницу вместо того, чтобы подвернуть таз.", "Позволять переднему колену выходить за носок."], "Подложи под колено сложенное полотенце, чтобы было удобнее."),
    "inversion_hang": ExerciseGuide(["Переворачивайся только под присмотром взрослого и на устойчивом, проверенном оборудовании.", "Надёжно зафиксируй лодыжки и начни с небольшого наклона, а не полностью вниз головой.", "Расслабь руки и медленно дыши до 1 минуты.", "Медленно вернись в вертикальное положение и посиди немного, прежде чем встать.", "Сразу прекрати, если почувствуешь головокружение, давление в голове или любую боль."], ["Висеть полностью вниз головой в первые занятия.", "Резко вставать сразу после виса."], "Достаточно коротких и мягких занятий; висеть дольше не нужно."),
    "jump_squats": ExerciseGuide(["Встань, ноги на ширине плеч, грудь вверх.", "Сядь назад в присед, пока бёдра не окажутся примерно параллельно полу.", "Сильно оттолкнись стопами, выпрыгни вверх и мягко приземлись обратно в присед.", "Сделай 8 прыжков, отдохни и повтори, всего 3 подхода."], ["Заваливать колени внутрь при приземлении.", "Приземляться на жёсткие, прямые ноги."], "Приземляйся как можно тише и заканчивай подход, когда приземления становятся громкими."),
    "jumping": ExerciseGuide(["Встань, ноги на ширине бёдер, руки расслаблены вдоль тела.", "Согни колени, махни руками и выпрыгни прямо вверх.", "Мягко приземлись на подушечки стоп с чуть согнутыми коленями.", "Сделай 20 прыжков, отдохни 30 секунд и повтори, всего 3 подхода."], ["Приземляться на пятки с прямыми ногами.", "Заваливать колени внутрь при приземлении."], "Тихое приземление означает хороший контроль, так что старайся приземляться как кошка."),
    "knee_circles": ExerciseGuide(["Встань, стопы вместе, колени слегка согнуты.", "Положи ладони на колени.", "Делай маленькие медленные круги коленями 15 секунд в одну сторону.", "Смени направление и делай 15 секунд в другую сторону."], ["Делать большие круги, которые скручивают колени.", "Делать все круги в одну сторону."], "Используй как разминку перед прыжками или бегом."),
    "legs_up_wall": ExerciseGuide(["Сядь боком к стене, одно бедро касается стены.", "Закинь ноги на стену, откидываясь на спину на пол.", "Положи руки вдоль тела и расслабь ноги на стене.", "Побудь так 3 минуты, медленно дыша."], ["Отрывать поясницу от пола.", "Сильно блокировать колени и напрягать ноги."], "Отодвинь таз немного от стены, если задняя поверхность ног кажется зажатой."),
    "low_lunge_arch": ExerciseGuide(["Сделай шаг одной ногой вперёд и опусти заднее колено на пол.", "Сдвигай таз вперёд, пока не почувствуешь растяжение в передней части тазобедренного сустава задней ноги.", "Подними обе руки вверх и подними грудь в лёгком прогибе.", "Задержись на 20 секунд, смени ногу, всего 2 подхода на каждую сторону."], ["Позволять переднему колену уходить далеко за носок.", "Прогибаться только в пояснице."], "Подложи сложенное полотенце под заднее колено и делай прогиб небольшим."),
    "lunges": ExerciseGuide(["Встань прямо, ноги на ширине бёдер.", "Сделай большой шаг вперёд и опустись, пока оба колена не согнутся примерно на 90 градусов.", "Оттолкнись передней пяткой и вернись в исходное положение.", "Сделай 8 повторений на каждую ногу и отдохни, всего 3 подхода."], ["Заваливать переднее колено внутрь.", "Сильно наклонять грудь вперёд над передней ногой."], "Делай шаг короче или держись за стул для равновесия, пока движение не станет устойчивым."),
    "masai_jumps": ExerciseGuide(["Встань прямо, руки вдоль тела или подняты вверх.", "Делай маленькие пружинистые прыжки, всё время держа корпус прямо.", "Мягко приземляйся на подушечки стоп, колени слегка согнуты.", "Продолжай 20 секунд, всего 3 подхода."], ["Тяжело приземляться на пятки.", "Сутулиться вперёд, когда устаёшь."], "Остановись, если болят колени или голени, и отдохни, прежде чем попробовать снова."),
    "morning_stretch": ExerciseGuide(["Встань прямо и медленно покрути шеей, по 5 кругов в каждую сторону.", "Подними обе руки над головой, сцепи пальцы и тянись вверх 30 секунд.", "Наклонись вперёд от бёдер и дай рукам свисать к носкам.", "Шагни в выпад, задержись на 30 секунд, затем смени ногу.", "Дыши медленно через нос и никогда не пружинь в растяжке."], ["Пружинить, чтобы уйти глубже, вместо того чтобы замереть.", "Задерживать дыхание во время удержания."], "Растягивайся до того, как возьмёшься за телефон, и привычка закрепится быстрее."),
    "mountain_pose": ExerciseGuide(["Встань, стопы вместе, вес распределён равномерно на обе ноги.", "Вытяни обе руки прямо над головой, ладони смотрят друг на друга.", "Поднимись на носки и тянись вверх через кончики пальцев.", "Задержись на 20 секунд и медленно опустись, всего 2 подхода."], ["Выпячивать рёбра и прогибать поясницу.", "Поднимать плечи к ушам."], "Смотри в одну точку перед собой или оставь пятки на полу, если шатает."),
    "neck_stretches": ExerciseGuide(["Сядь или встань прямо, плечи расслаблены и опущены.", "Медленно наклони ухо к плечу и задержись на 30 секунд на каждую сторону.", "Опусти подбородок к груди и задержись на 30 секунд.", "Мягко подними взгляд на 30 секунд, не запрокидывая голову назад."], ["Сильно тянуть голову рукой.", "Поднимать плечо навстречу уху."], "Делай это после долгих занятий, чтобы снять напряжение."),
    "overhead_press": ExerciseGuide(["Встань прямо, держа лёгкие гантели или бутылки с водой на уровне плеч.", "Напряги кор и выжми обе руки прямо над головой.", "Закончи с руками рядом с ушами, затем медленно опусти к плечам.", "Выдыхай при жиме, вдыхай при опускании, 10 повторений за подход."], ["Прогибать поясницу при жиме.", "Брать слишком тяжёлый вес, который не удаётся контролировать."], "Начни с собственного веса и добавляй лёгкие гантели, когда техника станет лёгкой."),
    "pelvic_shift": ExerciseGuide(["Ляг на спину, колени согнуты, стопы на полу.", "Подверни копчик и отрывай позвоночник от пола снизу вверх.", "Задержись вверху, затем медленно опускайся по одному позвонку.", "Сделай 10 медленных повторений и отдохни, всего 2 подхода."], ["Резко поднимать таз вверх одним блоком.", "Прогибать поясницу вверху."], "Двигайся достаточно медленно, чтобы почувствовать, как каждая часть спины касается пола."),
    "pilates_core": ExerciseGuide(["Удерживай планку на предплечьях 1 минуту, тело в одной прямой линии.", "Ляг на спину для мёртвого жука, медленно опуская противоположные руку и ногу.", "Перейди к птице-собаке на четвереньках, вытягивая противоположные руку и ногу.", "Закончи 1 минутой ягодичных мостиков и 1 минутой подъёмов ног.", "Выдыхай каждый раз, когда напрягаешь кор."], ["Позволять тазу прогибаться вниз в планке.", "Отрывать поясницу от пола в прогибе при выполнении мёртвого жука."], "Медленно и под контролем лучше, чем быстро; каждое чистое повторение развивает настоящую силу."),
    "pilates_roll_over": ExerciseGuide(["Ляг на спину, руки вдоль тела, ноги подняты прямо вверх.", "Прижми руки к полу и подними таз, перекатывая ноги за голову.", "Остановись, когда ноги окажутся параллельно полу за головой.", "Медленно перекатись обратно, сделай 5 повторений и отдохни, всего 2 подхода."], ["Забрасывать ноги за голову по инерции.", "Перекатываться на шею, а не на плечи."], "Держи вес на плечах, а не на шее, и согни колени, чтобы было легче."),
    "plank": ExerciseGuide(["Поставь предплечья на пол, локти под плечами.", "Отведи ноги назад, чтобы тело образовало одну прямую линию.", "Сожми ягодицы, втяни пупок и задержись на 30 секунд.", "Отдохни 30 секунд и повтори, всего 3 подхода."], ["Позволять тазу провисать к полу.", "Поднимать таз слишком высоко."], "Добавляй по 5 секунд каждую неделю, когда становится легче."),
    "pogo_jumps": ExerciseGuide(["Встань прямо, ноги на ширине бёдер, руки на поясе.", "Подпрыгивай на подушечках стоп, колени почти прямые.", "Делай каждый контакт с полом коротким и быстрым, как на пого-стике.", "Продолжай 20 секунд, всего 3 подхода."], ["Глубоко сгибать колени при каждом подскоке.", "Бить пятками об пол."], "Прыгай на твёрдой ровной поверхности и остановись, если болят голени или голеностопы."),
    "posture_check": ExerciseGuide(["Поставь ежечасное напоминание проверять, как ты сидишь или стоишь.", "Расположи уши над плечами, а плечи над бёдрами.", "Отведи плечи назад и вниз, грудь мягко раскрыта.", "Представь нить, тянущую макушку вверх, и подыши."], ["Перестараться с исправлением и держать жёсткую, прогнутую спину.", "Смотреть вниз на телефон с выдвинутой вперёд головой."], "Подними экран на уровень глаз, и хорошая осанка станет автоматической."),
    "pre_sleep_routine": ExerciseGuide(["Начни за 30 минут до сна: приглуши свет и убери экраны.", "Почитай книгу или послушай спокойную музыку 15 минут.", "Сделай 5 минут мягкой растяжки на кровати или на полу.", "Вдыхай 4 секунды и выдыхай 6 секунд, 10 циклов."], ["Листать телефон ещё одну минуту.", "Сильно менять время отхода ко сну от ночи к ночи."], "Одно и то же время и одни и те же шаги каждую ночь облегчают засыпание."),
    "pull_ups": ExerciseGuide(["Возьмись за турник хватом сверху, руки чуть шире плеч.", "Начни из виса на прямых руках и опусти лопатки вниз.", "Подтягивайся, пока подбородок не окажется над перекладиной, затем медленно опустись.", "Сделай 2 повторения, спустись и отдохни, всего 3 подхода."], ["Дрыгать ногами и раскачиваться, чтобы перебраться через перекладину.", "Быстро падать вниз вместо контролируемого опускания."], "Пропусти резинку под стопы или запрыгни наверх и медленно опускайся, и проверь, что турник надёжный."),
    "puppy_pose": ExerciseGuide(["Встань на четвереньки, таз прямо над коленями.", "Пройди руками вперёд, не двигая таз с места.", "Дай груди и лбу опуститься к полу.", "Задержись на 20 секунд и вернись, всего 2 подхода."], ["Позволять тазу уезжать назад к пяткам.", "Сгибать локти и класть их на пол."], "Положи лоб на подушку, если растяжение в плечах кажется слишком сильным."),
    "push_ups": ExerciseGuide(["Поставь ладони на пол чуть шире плеч.", "Отведи ноги назад, чтобы тело образовало одну прямую линию.", "Согни локти, опустив грудь к полу, затем выжмись обратно.", "Сделай 5 повторений и отдохни, всего 3 подхода."], ["Позволять тазу провисать к полу.", "Разводить локти прямо в стороны."], "Встань на колени или поставь руки на скамью, чтобы было легче."),
    "scapular_pull": ExerciseGuide(["Возьмись за турник хватом сверху, руки чуть шире плеч.", "Повисни на прямых руках и дай плечам подняться к ушам.", "Опусти лопатки вниз, чтобы тело немного поднялось, локти прямые.", "Задержись на секунду и расслабься, сделай 5 повторений, всего 3 подхода."], ["Сгибать локти, чтобы подтянуться выше.", "Раскачивать ноги для помощи."], "Проверь, что турник надёжный, и держи ноги на подставке, если полный вис слишком тяжёл."),
    "scapular_retraction": ExerciseGuide(["Сядь или встань прямо, руки расслаблены вдоль тела.", "Отведи лопатки назад и вниз, как будто убираешь их в задние карманы.", "Удержи сведение на один медленный вдох, затем расслабься.", "Сделай 10 повторений и отдохни, всего 2 подхода."], ["Поднимать плечи вверх при сведении.", "Выпячивать рёбра вперёд и прогибать спину."], "Держи подбородок ровно, а шею расслабленной всё время."),
    "seated_forward_fold": ExerciseGuide(["Сядь на пол, ноги прямые, носки смотрят вверх.", "Сядь прямо и вытяни обе руки над головой.", "Наклонись вперёд от тазобедренных суставов и потянись к голеням или стопам.", "Задержись на 20 секунд и сядь обратно, всего 2 подхода."], ["Округлять верх спины, чтобы дотянуться до носков.", "Пружинить, чтобы уйти глубже в растяжку."], "Слегка согни колени или сядь на сложенное полотенце, если поясница округляется."),
    "shoulder_rolls": ExerciseGuide(["Встань прямо, руки свободно свисают вдоль тела.", "Вращай плечами вперёд большими кругами 15 раз.", "Вращай ими назад 15 раз, сводя лопатки вместе.", "Сцепи руки за спиной и раскрой грудь на 20 секунд."], ["Делать крошечные торопливые круги.", "Поднимать плечи, задерживая дыхание."], "Короткий подход между уроками или блоками учёбы держит плечи раскрытыми."),
    "side_plank": ExerciseGuide(["Ляг на бок, предплечье на полу, локоть под плечом.", "Поставь стопы друг на друга и подними таз от пола.", "Держи тело в одной прямой линии от головы до пяток.", "Задержись на 15 секунд, смени сторону, всего 2 подхода на каждую сторону."], ["Позволять тазу опускаться к полу.", "Заваливать грудь вперёд к полу."], "Оставь нижнее колено на полу, чтобы было легче."),
    "single_leg_calf_raise": ExerciseGuide(["Встань на край ступеньки на подушечку одной стопы и держись за стену или перила.", "Медленно опусти пятку ниже уровня ступеньки.", "Поднимись на носок как можно выше и задержись на секунду.", "Сделай 8 повторений на каждую ногу и отдохни, всего 3 подхода."], ["Отскакивать из нижней точки вместо медленного движения.", "Сгибать колено, помогая икре."], "Начни с собственного веса, а если берёшь гантель или рюкзак, выбери вес, с которым сможешь закончить каждое повторение с хорошей техникой."),
    "single_leg_hops": ExerciseGuide(["Встань на одну ногу, другую стопу подними назад.", "Делай маленькие прыжки на месте, приземляясь на подушечку стопы.", "Держи таз ровно, а опорное колено слегка согнутым.", "Сделай 8 прыжков, смени ногу, всего 2 подхода на каждую сторону."], ["Позволять колену прыгающей ноги заваливаться внутрь.", "Прыгать так высоко, что теряешь равновесие."], "Стой рядом со стеной, до которой можно дотронуться, и прыгай невысоко, пока равновесие не станет устойчивым."),
    "skipping_rope": ExerciseGuide(["Держи ручки на уровне бёдер, локти прижаты к бокам.", "Крути верёвку кистями, а не всей рукой.", "Прыгай ровно настолько, чтобы перепрыгнуть верёвку, приземляясь на подушечки стоп.", "Прыгай 5 минут, отдохни 1 минуту и повтори, всего 3 подхода."], ["Прыгать слишком высоко и быстро уставать.", "Приземляться на плоскую стопу, на пятки."], "Запинаться на скакалке нормально; просто начни заново и сохраняй ритм."),
    "spinal_twist": ExerciseGuide(["Ляг на спину, руки разведены в стороны.", "Согни одно колено и опусти его через тело к полу.", "Держи оба плеча на полу и смотри в противоположную сторону.", "Задержись на 20 секунд, смени сторону, всего 2 подхода на каждую сторону."], ["Позволять противоположному плечу отрываться от пола.", "Давить на колено рукой, чтобы опустить его силой."], "Положи колено на подушку, если оно не достаёт до пола."),
    "sprint_intervals": ExerciseGuide(["Разомнись 5 минут лёгкого бега и махов ногами.", "Беги спринт изо всех сил 30 секунд, активно работая руками.", "Иди или медленно беги 90 секунд для восстановления.", "Повтори, всего 3 спринта, затем заверши 5 минутами ходьбы."], ["Бежать спринт без разминки.", "Откидываться назад и делать слишком длинные шаги вместо толчка вперёд."], "Выбери ровное безопасное покрытие и выкладывайся полностью, только когда чувствуешь себя свежим."),
    "squats": ExerciseGuide(["Встань, ноги на ширине плеч, носки слегка развернуты наружу.", "Отведи таз назад и опускайся, пока бёдра не станут параллельны полу.", "Держи грудь вверх, а колени в одной линии с носками.", "Выпрямляйся, давя пятками в пол, и выдыхай на подъёме."], ["Отрывать пятки от пола.", "Округлять спину внизу."], "Первые подходы делай перед зеркалом, чтобы проверить технику."),
    "standing_side_stretch": ExerciseGuide(["Встань прямо, ноги на ширине бёдер.", "Подними обе руки над головой и возьмись одной рукой за запястье другой.", "Медленно наклонись в одну сторону, прижимая обе стопы к полу.", "Задержись на 15 секунд, смени сторону, всего 2 подхода на каждую сторону."], ["Наклоняться вперёд или скручиваться вместо наклона строго в сторону.", "Сильно выдвигать таз в сторону."], "Представь, что стоишь между двумя стенами и можешь двигаться только вбок."),
    "step_ups": ExerciseGuide(["Встань перед ступенью или устойчивой низкой скамьёй.", "Поставь всю стопу одной ноги на ступень и вставай, пока не выпрямишься.", "Медленно опусти другую ногу обратно на пол.", "Сделай 8 повторений на каждую ногу и отдохни, всего 3 подхода."], ["Сильно отталкиваться ногой, стоящей на полу.", "Быстро падать вниз вместо контролируемого опускания."], "Используй ступень, которая не скользит и не опрокидывается, и начни с низкой, прежде чем переходить к более высокой."),
    "superman": ExerciseGuide(["Ляг на живот, руки вытянуты вперёд.", "Слегка подними руки и ноги от пола.", "Держи шею длинной, смотри в пол и задержись на 2 секунды.", "Медленно опустись, 8 повторений за подход, всего 2 подхода."], ["Силой поднимать грудь и ноги как можно выше.", "Запрокидывать голову и зажимать шею."], "Небольшого подъёма достаточно. Если поясницу защемляет, поднимайся ниже."),
    "swimming_basketball": ExerciseGuide(["Разомнись 5 минут: лёгкие заплывы или ведение мяча.", "Плавай или играй не менее 30 минут в ровном темпе.", "Вкладывайся полностью в каждый гребок, бросок или подбор.", "Заверши 5 минутами лёгких движений и растяжки."], ["Пропускать разминку и начинать на полной скорости.", "Забывать пить воду во время игры."], "Позови друга: заниматься спортом проще в компании."),
    "table_top": ExerciseGuide(["Сядь, колени согнуты, стопы на полу, ладони на полу за тазом.", "Направь пальцы рук к стопам и надави на ладони и стопы.", "Подними таз так, чтобы тело стало ровным от колен до плеч.", "Задержись на 15 секунд и опустись, всего 2 подхода."], ["Позволять тазу провисать посередине.", "Запрокидывать голову назад, напрягая шею."], "Поверни пальцы наружу в стороны, если запястья побаливают."),
    "thoracic_extension": ExerciseGuide(["Сядь на крепкий стул так, чтобы верх спинки был чуть ниже лопаток.", "Положи ладони за голову, локти разведены широко.", "Медленно прогнись верхом спины через спинку стула и посмотри вверх.", "Вернись, сделай 8 повторений и отдохни, всего 2 подхода."], ["Прогибаться в пояснице, а не в верхней части спины.", "Тянуть голову вперёд руками."], "Используй стул, который не катится и не опрокидывается, и держи стопы на полу."),
    "toe_touch": ExerciseGuide(["Встань, ноги на ширине бёдер, колени мягкие.", "Наклонись вперёд от тазобедренных суставов и тянись руками к носкам.", "Замри на 20 секунд и дыши медленно.", "Медленно поднимись, отдохни и повтори ещё раз."], ["Пружинить, чтобы дотянуться дальше.", "Выпрямлять колени до упора."], "Если не достаёшь до носков, остановись на голенях. Это всё равно работает."),
    "tuck_jumps": ExerciseGuide(["Встань прямо, ноги на ширине бёдер.", "Быстро присядь на четверть и выпрыгни как можно выше.", "Подтяни оба колена к груди в верхней точке, затем мягко приземлись на согнутые колени.", "Сделай 6 прыжков, отдохни и повтори, всего 3 подхода."], ["Наклонять грудь к коленям вместо подъёма коленей.", "Тяжело приземляться на прямые ноги."], "Восстанавливай равновесие между прыжками и убедись, что вокруг есть свободное место, а пол не скользит."),
    "upward_salute": ExerciseGuide(["Встань, стопы вместе, руки вдоль тела.", "Вдохни и подними обе руки над головой.", "Держи рёбра опущенными, а плечи подальше от ушей.", "Задержись на 15 секунд, дыша медленно, затем опусти руки. Всего 2 подхода."], ["Откидываться назад и прогибать поясницу.", "Выпячивать рёбра вперёд."], "Тянись вверх, а не назад. Держи тело стоящим ровно над стопами."),
    "wall_angels": ExerciseGuide(["Встань спиной к стене, стопы чуть впереди.", "Положи руки на стену, локти согнуты, как стойки ворот.", "Держи рёбра опущенными и медленно скользи руками вверх, затем обратно вниз.", "Делай 8 медленных повторений за подход, всего 2 подхода."], ["Выпячивать рёбра и прогибать поясницу.", "Отрывать руки от стены."], "Поднимайся только настолько, насколько руки могут оставаться на стене. С практикой станет легче."),
    "wall_dog": ExerciseGuide(["Встань лицом к стене на расстоянии примерно длины ноги.", "Положи ладони на стену на уровне бёдер.", "Отведи таз назад, пока руки не выпрямятся, а позвоночник не станет длинным.", "Задержись на 20 секунд, дыша медленно, всего 2 подхода."], ["Округлять верх спины.", "Сгибать локти и наваливаться на стену."], "Отличная пауза за столом, когда нельзя лечь на пол."),
    "wall_sit": ExerciseGuide(["Встань спиной к стене, стопы на шаг впереди.", "Скользи вниз, пока бёдра не окажутся параллельно полу.", "Держи колени над лодыжками, а всю спину прижатой к стене.", "Задержись на 20 секунд и встань, всего 3 подхода."], ["Класть руки на бёдра.", "Позволять коленям уезжать вперёд за носки."], "Сядь чуть выше, если колени протестуют, и опускайся ниже, когда станешь сильнее."),
    "wall_stand": ExerciseGuide(["Встань пятками к стене, стопы на ширине бёдер.", "Коснись стены ягодицами, лопатками и затылком.", "Слегка втяни подбородок и держи руки расслабленными вдоль тела.", "Стой так 5 минут, спокойно дыша носом."], ["Сильно прогибать поясницу от стены.", "Задирать подбородок вместо того, чтобы держать его ровно."], "Запомни это ощущение, а потом попробуй сохранить его в течение дня."),
  },
  "ar": {
    "band_pull_apart": ExerciseGuide(["قف باستقامة وأمسك الباند أمامك بذراعين مستقيمتين على ارتفاع الكتفين.", "اسحب الباند للخارج بضم لوحَي الكتف معًا.", "المس صدرك بالباند ثم عُد ببطء.", "نفّذ 12 تكرارًا ثم استرح، بمجموع مجموعتين."], ["رفع الكتفين نحو الأذنين.", "ترك الباند يرتد بسرعة بدل العودة ببطء."], "اختر باندًا خفيفًا بما يكفي لإنهاء كل تكرار بشكل سليم، وافحصه أولًا للتأكد من خلوّه من التمزق."),
    "bar_hanging": ExerciseGuide(["أمسك العقلة بقبضة من الأعلى ويداك بعرض الكتفين.", "ارفع قدميك واترك جسمك معلقًا مستقيمًا ومسترخيًا.", "أبقِ كتفيك مشدودتين قليلًا وتنفّس ببطء لمدة 30 ثانية.", "انزل بلطف، واسترح من 30 إلى 60 ثانية، وكرّر لـ 3 مجموعات."], ["التأرجح أو رفس الساقين أثناء التعلق.", "القفز من العقلة بدل النزول بهدوء."], "ابدأ بمدد أقصر وأضف بضع ثوانٍ كل أسبوع."),
    "bird_dog": ExerciseGuide(["ابدأ على أربع، اليدان تحت الكتفين والركبتان تحت الوركين.", "مدّ ذراعًا للأمام والساق المعاكسة للخلف باستقامة.", "اثبت ثانيتين مع إبقاء الوركين مستويين ثم عُد.", "نفّذ 8 تكرارات، بدّل الجانب، وكرّر لمجموعتين على كل جانب."], ["ترك أسفل الظهر يتقوس للأسفل عند رفع الساق.", "تدوير الوركين للخارج لرفع الساق أعلى."], "تخيّل كوب ماء على أسفل ظهرك يجب ألا ينسكب."),
    "bow_pose": ExerciseGuide(["استلقِ على بطنك واثنِ ركبتيك ليقترب كعباك من وركيك.", "مدّ يديك للخلف وأمسك الكاحلين معًا.", "ادفع قدميك نحو يديك لرفع صدرك وفخذيك.", "اثبت 10 ثوانٍ وانزل ببطء، بمجموع مجموعتين."], ["ترك الركبتين تتباعدان أكثر من عرض الوركين.", "رمي الرأس للخلف وإجهاد الرقبة."], "ارتفع بقدر ما تشعر بالراحة فقط، وتجاوز هذا التمرين إذا كان أسفل ظهرك يؤلمك."),
    "broad_jumps": ExerciseGuide(["قف وقدماك بعرض الوركين وأصابع قدميك خلف خط.", "حرّك ذراعيك للخلف واثنِ ركبتيك وادفع وركيك للخلف.", "حرّك ذراعيك للأمام واقفز أبعد ما تستطيع واهبط على قدميك معًا.", "اثبت لحظة عند الهبوط، وعُد للخلف مشيًا ونفّذ 5 قفزات، بمجموع 3 مجموعات."], ["السقوط للأمام أو للخلف عند الهبوط.", "الهبوط وركبتاك مشدودتان تمامًا."], "اقفز على سطح غير زلق، واقفز مسافة أقصر حتى تتمكن من الثبات عند كل هبوط."),
    "burpees": ExerciseGuide(["قف باستقامة ثم اجلس القرفصاء وضع يديك على الأرض.", "اقفز بقدميك للخلف إلى وضع البلانك المستقيم.", "اقفز بقدميك للأمام نحو يديك.", "اقفز للأعلى باستقامة، ونفّذ 5 تكرارات ثم استرح، بمجموع 3 مجموعات."], ["ترك الوركين يهبطان في وضع البلانك.", "الهبوط بقوة على ساقين مستقيمتين بعد القفزة."], "اخطُ بقدميك للخلف وللأمام بدل القفز لتسهيل التمرين، وأبطئ إن اختل شكل حركتك."),
    "calf_pulses": ExerciseGuide(["قف باستقامة وارتفع على أصابع قدميك، وأطراف أصابعك على الحائط إن احتجت التوازن.", "اهتز للأعلى وللأسفل بنبضات صغيرة، بضعة سنتيمترات فقط.", "أبقِ كعبيك مرفوعين عن الأرض طوال المجموعة.", "واصل لمدة 20 ثانية، بمجموع 3 مجموعات."], ["ترك الكعبين يلمسان الأرض بين النبضات.", "جعل الحركة كبيرة لدرجة أنها لم تعد نبضة."], "الإحساس بالحرقان في السمانتين طبيعي. أما الألم الحاد فيعني التوقف."),
    "calf_raise": ExerciseGuide(["قف باستقامة بجانب حائط، وأطراف أصابعك تلمسه للتوازن.", "ارتفع ببطء على مقدمة قدميك لأعلى ما تستطيع.", "اثبت ثانية واحدة في الأعلى ثم أنزل كعبيك ببطء.", "نفّذ 15 تكرارًا في كل مجموعة، بمجموع 3 مجموعات."], ["الارتداد بسرعة بدل الحركة البطيئة.", "ترك الكاحلين يميلان للخارج في الأعلى."], "نفّذه أثناء تفريش أسنانك ليصبح عادة يومية سهلة."),
    "cat_cow": ExerciseGuide(["ابدأ على اليدين والركبتين، المعصمان تحت الكتفين والركبتان تحت الوركين.", "خذ شهيقًا، وأنزل بطنك وارفع صدرك ونظرك (البقرة).", "أخرج الزفير، ودوّر ظهرك وقرّب ذقنك من صدرك (القطة).", "تحرك ببطء مع أنفاسك لمدة 10 جولات، مجموعتين."], ["التحرك أسرع من أنفاسك.", "تحريك الرقبة فقط بدل العمود الفقري كله."], "ممتاز كأول حركة في الصباح أو لإعادة ضبط جسمك بعد الجلوس."),
    "chest_stretch": ExerciseGuide(["قف عند الباب وضع ساعدًا واحدًا على إطاره والمرفق بمستوى الكتف.", "تقدّم بالقدم في الجهة نفسها إلى الأمام عبر الباب.", "أمِل صدرك للأمام حتى تشعر بتمدد في مقدمة كتفك.", "اثبت 20 ثانية، بدّل الجانب، وكرّر لمجموعتين على كل جانب."], ["تقويس أسفل الظهر للميل أكثر.", "رفع الكتف نحو الأذن."], "اجعل التمدد لطيفًا، وتراجع إن شعرت بوخز في كتفك."),
    "childs_pose": ExerciseGuide(["اجثُ على الأرض وإبهاما قدميك متلامسان وركبتاك متباعدتان.", "أرجع وركيك للخلف حتى يجلسا على كعبيك.", "مرّر يديك للأمام وأسند جبهتك على الأرض.", "تنفّس ببطء لمدة 30 ثانية ثم انهض، بمجموع مجموعتين."], ["رفع الوركين بعيدًا عن الكعبين للوصول أبعد.", "حبس النفس وشدّ الكتفين."], "ضع وسادة بين وركيك وكعبيك إن شعرت بشدّ في ركبتيك."),
    "chin_tucks": ExerciseGuide(["اجلس أو قف باستقامة وانظر للأمام.", "اسحب ذقنك للخلف باستقامة، كأنك تصنع ذقنًا مزدوجًا.", "اثبت 3 ثوانٍ ثم استرخِ.", "نفّذ 8 تكرارات في كل مجموعة، بمجموع مجموعتين."], ["إنزال الرأس للأسفل بدل سحبه للخلف.", "الضغط بقوة حتى تؤلمك رقبتك."], "نفّذ بضع تكرارات كلما وضعت هاتفك جانبًا."),
    "cobra_stretch": ExerciseGuide(["استلقِ على بطنك ويداك مسطحتان تحت كتفيك.", "ادفع الأرض بعيدًا وارفع صدرك ببطء مع بقاء الوركين على الأرض.", "أبقِ مرفقيك مثنيين قليلًا وكتفيك بعيدين عن أذنيك.", "اثبت 15 ثانية مع التنفس ببطء، ثم انزل بتحكم."], ["الارتفاع كثيرًا حتى يؤلمك أسفل الظهر.", "رفع الكتفين نحو الأذنين."], "ارتفع بقدر ما تشعر بالراحة فقط، فالمرونة تزداد مع التمرين."),
    "dead_bug": ExerciseGuide(["استلقِ على ظهرك وذراعاك للأعلى باستقامة وركبتاك مثنيتان فوق وركيك.", "اضغط أسفل ظهرك بلطف على الأرض.", "أنزل ذراعًا فوق رأسك والساق المعاكسة نحو الأرض ثم عُد.", "نفّذ 8 تكرارات على كل جانب ثم استرح، بمجموع مجموعتين."], ["ترك أسفل الظهر يتقوس بعيدًا عن الأرض.", "التسرع في التكرارات."], "أنزل ذراعك وساقك بقدر ما يبقى ظهرك مسطحًا على الأرض."),
    "dead_hang_active": ExerciseGuide(["أمسك العقلة بقبضة من الأعلى ويداك أوسع قليلًا من كتفيك.", "تعلّق بذراعين مستقيمتين ثم اسحب لوحَي الكتف للأسفل وللخلف.", "ضم ساقيك وشدّ جذعك، واثبت 20 ثانية.", "انزل بلطف واسترح 40 ثانية بين المجموعات."], ["ثني المرفقين كما في تمرين العقلة.", "رفع الكتفين نحو الأذنين."], "تخيّل أنك تدفع العقلة بعيدًا عنك لتشعر بعمل كتفيك."),
    "deadlift_stretch": ExerciseGuide(["قف وقدماك بعرض الوركين وركبتاك مثنيتان قليلًا.", "انحنِ من الوركين ومرّر يديك على فخذيك للأسفل.", "أبقِ ظهرك مستويًا ومدّ يديك نحو أصابع قدميك حتى تتمدد عضلات الفخذ الخلفية.", "اشدد أردافك للوقوف من جديد، 12 تكرارًا بطيئًا في كل مجموعة."], ["تدوير الظهر للوصول لمسافة أدنى.", "شد الركبتين تمامًا."], "تحرك ببطء، فالتحكم أهم من مدى الوصول."),
    "downward_dog": ExerciseGuide(["ابدأ على اليدين والركبتين واليدان تحت الكتفين.", "ارفع وركيك عاليًا ليشكل جسمك حرف V مقلوبًا.", "أبقِ عمودك الفقري طويلًا ودع كعبيك ينزلان نحو الأرض.", "اثبت 20 ثانية ثم استرح، بمجموع مجموعتين."], ["تدوير الظهر لإجبار الكعبين على النزول.", "رفع الكتفين نحو الأذنين."], "اثنِ ركبتيك قليلًا إن استدار ظهرك. لا يلزم أن يلمس كعباك الأرض."),
    "dumbbell_deadlift": ExerciseGuide(["قف باستقامة وفي كل يد دامبل أمام فخذيك.", "لينّ ركبتيك وادفع وركيك للخلف بظهر مستوٍ.", "مرّر الأوزان على فخذيك حتى أسفل ركبتيك بقليل.", "اشدد أردافك للوقوف، ونفّذ 8 تكرارات، بمجموع 3 مجموعات."], ["تدوير الظهر أثناء نزول الأوزان.", "تحويله إلى قرفصاء بثني الركبتين كثيرًا."], "اختر وزنًا خفيفًا بما يكفي لإنهاء كل تكرار بشكل سليم."),
    "dumbbell_row": ExerciseGuide(["ضع يدًا واحدة على مقعد أو كرسي وتراجع بقدميك للخلف.", "أمسك الدامبل باليد الأخرى وظهرك مستوٍ وذراعك متدلية للأسفل.", "اسحب الوزن نحو وركك والمرفق قريب من جسمك، ثم أنزله ببطء.", "نفّذ 8 تكرارات على كل جانب ثم استرح، بمجموع 3 مجموعات."], ["لف الجسم لرفع الوزن بالقوة.", "رفع الكتف نحو الأذن."], "اختر وزنًا خفيفًا بما يكفي لإنهاء كل تكرار بشكل سليم."),
    "evening_yoga": ExerciseGuide(["ابدأ على اليدين والركبتين وانتقل بين القطة والبقرة لمدة 60 ثانية.", "ارجع للجلوس في وضعية الطفل وذراعاك ممدودتان، وتنفّس لمدة 60 ثانية.", "ادفع للأعلى إلى وضعية الكلب المتجه للأسفل وكعباك يمتدان نحو الأرض.", "قف وانحنِ للأمام تاركًا رأسك يتدلى بثقل.", "شهيق لمدة 4 عدّات وزفير لمدة 6 عدّات في كل وضعية."], ["التسرع بين الوضعيات بدل الثبات فيها.", "إجبار وضعية ما حتى تؤلمك."], "خفّض الإضاءة أثناء الحركة ليهدأ جسمك."),
    "farmer_carry": ExerciseGuide(["قف بين دامبلين أو حقيبتين محمّلتين.", "اثنِ ركبتيك وأبقِ ظهرك مستويًا وارفعهما.", "امشِ بخطوات صغيرة وكتفاك للخلف ونظرك للأمام.", "امشِ لمدة 20 ثانية، ثم ضعهما واسترح، بمجموع 3 مجموعات."], ["الميل إلى جهة واحدة أو ترك الكتفين تستديران للأمام.", "تدوير الظهر عند رفع الأوزان أو وضعها."], "اختر وزنًا خفيفًا بما يكفي لإنهاء كل مجموعة بشكل سليم، وحافظ على تساوي الجهتين."),
    "glute_bridge": ExerciseGuide(["استلقِ على ظهرك وركبتاك مثنيتان وقدماك مسطحتان بعرض الوركين.", "ادفع بكعبيك وارفع وركيك نحو السقف.", "اشدد أردافك في الأعلى لمدة ثانيتين.", "انزل ببطء، 12 تكرارًا في كل مجموعة، بمجموع 3 مجموعات."], ["الدفع بأصابع القدم بدل الكعبين.", "تقويس أسفل الظهر كثيرًا في الأعلى."], "إذا شعرت به في أردافك لا في أسفل ظهرك فأنت تؤدي التمرين بشكل صحيح."),
    "goblet_squat": ExerciseGuide(["أمسك دامبل أو حقيبة ظهر محمّلة عند صدرك بيديك معًا.", "قف وقدماك بعرض الكتفين وأصابع قدميك متجهة للخارج قليلًا.", "انزل بين كعبيك وصدرك مرفوع، ثم قف من جديد.", "نفّذ 8 تكرارات ثم استرح، بمجموع 3 مجموعات."], ["ترك الركبتين تنثنيان للداخل.", "تدوير الظهر وترك الصدر ينخفض."], "اختر وزنًا خفيفًا بما يكفي لإنهاء كل تكرار بشكل سليم."),
    "hanging_knee_raise": ExerciseGuide(["أمسك العقلة بقبضة من الأعلى وتعلّق بذراعين مستقيمتين.", "اسحب كتفيك للأسفل بعيدًا عن أذنيك.", "ارفع ركبتيك معًا حتى مستوى الوركين دون تأرجح، ثم أنزلهما ببطء.", "نفّذ 5 تكرارات، وانزل واسترح، بمجموع 3 مجموعات."], ["التأرجح بالجسم لقذف الركبتين للأعلى.", "التعلق والكتفان مرفوعتان نحو الأذنين."], "تأكد من متانة العقلة قبل التعلق، وانزل بهدوء بدل القفز منها."),
    "high_knees": ExerciseGuide(["قف باستقامة وقدماك بعرض الوركين.", "اركض في المكان وارفع كل ركبة حتى مستوى الوركين.", "حرّك ذراعيك وأبقِ خفيفًا على مقدمة قدميك.", "واصل لمدة 20 ثانية، بمجموع 3 مجموعات."], ["الميل للخلف عند رفع الركبتين.", "الدوس على الأرض بقدمين مسطحتين."], "أبطئ إلى مشي برفع الركبتين عاليًا إذا انقطع نفسك."),
    "hiit_workout": ExerciseGuide(["سخّن 3 دقائق بالمشي في المكان وتدوير الذراعين.", "نفّذ البيربي ومتسلق الجبل وقفز القرفصاء، 45 ثانية لكل تمرين.", "استرح 15 ثانية بين التمارين وتنفّس بعمق.", "أكمل 4 جولات ثم امشِ ببطء حتى يهدأ تنفسك."], ["ترك شكل الحركة يختل من أجل السرعة.", "حبس النفس أثناء الفترات الشاقة."], "سر بوتيرتك الخاصة، فإنهاء الجولات الأربع أفضل من بداية سريعة."),
    "hip_flexor_stretch": ExerciseGuide(["اجثُ على ركبة واحدة والقدم الأخرى مسطحة أمامك.", "أدخل وركيك قليلًا للأسفل واشدد أرداف الساق الخلفية.", "تحرّك للأمام بلطف حتى تشعر بتمدد في مقدمة وركك.", "اثبت 30 ثانية مع التنفس ببطء، ثم بدّل الجانب."], ["تقويس أسفل الظهر بدل إدخال الوركين.", "ترك الركبة الأمامية تتجاوز أصابع القدم."], "ضع منشفة مطوية تحت ركبتك لتكون أكثر راحة."),
    "inversion_hang": ExerciseGuide(["اقلب جسمك فقط بوجود شخص بالغ يشرف عليك وعلى معدات ثابتة تم فحصها.", "أحكم تثبيت كاحليك وابدأ بميل خفيف، لا بالانقلاب الكامل.", "أرخِ ذراعيك وتنفّس ببطء لمدة تصل إلى دقيقة واحدة.", "عُد إلى الوضع المستقيم ببطء واجلس لحظة قبل أن تقف.", "توقف فورًا إذا شعرت بدوار أو ضغط في رأسك أو أي ألم."], ["الانقلاب الكامل في أول جلساتك.", "الوقوف بسرعة بعد الانقلاب مباشرة."], "تكفي الجلسات القصيرة اللطيفة، ولا داعي للتعلق مدة أطول."),
    "jump_squats": ExerciseGuide(["قف وقدماك بعرض الكتفين وصدرك مرفوع.", "اجلس للخلف في وضع القرفصاء حتى يصبح فخذاك بمستوى الأرض تقريبًا.", "ادفع بقوة بقدميك، واقفز للأعلى باستقامة واهبط بلطف في وضع القرفصاء.", "نفّذ 8 قفزات واسترح، وكرّر لـ 3 مجموعات."], ["ترك الركبتين تنثنيان للداخل عند الهبوط.", "الهبوط بساقين متصلبتين مستقيمتين."], "اهبط بأهدأ ما تستطيع، وأنهِ المجموعة عندما يعلو صوت هبوطك."),
    "jumping": ExerciseGuide(["قف وقدماك بعرض الوركين وذراعاك مسترخيتان على جانبيك.", "اثنِ ركبتيك وحرّك ذراعيك واقفز للأعلى باستقامة.", "اهبط بلطف على مقدمة قدميك وركبتاك مثنيتان قليلًا.", "نفّذ 20 قفزة، واسترح 30 ثانية، وكرّر لـ 3 مجموعات."], ["الهبوط بساقين متصلبتين على الكعبين.", "ترك الركبتين تنثنيان للداخل عند الهبوط."], "الهبوط الهادئ يعني تحكمًا جيدًا، فحاول أن تهبط كالقطة."),
    "knee_circles": ExerciseGuide(["قف وقدماك متلاصقتان واثنِ ركبتيك قليلًا.", "ضع يديك على ركبتيك.", "ارسم بركبتيك دوائر صغيرة وبطيئة لمدة 15 ثانية في اتجاه واحد.", "بدّل الاتجاه وكرّر 15 ثانية في الاتجاه الآخر."], ["رسم دوائر كبيرة تلوي الركبتين.", "تنفيذ كل الدوائر في اتجاه واحد."], "استخدمه كإحماء قبل القفز أو الركض."),
    "legs_up_wall": ExerciseGuide(["اجلس بشكل جانبي بجانب الحائط بحيث يلمسه أحد وركيك.", "ارفع ساقيك على الحائط وأنت تستلقي على الأرض.", "دع ذراعيك مسترخيتين بجانبك وأرخِ ساقيك على الحائط.", "ابقَ 3 دقائق وأنت تتنفس ببطء."], ["رفع أسفل الظهر عن الأرض.", "شد الركبتين بقوة وتوتير الساقين."], "أبعد وركيك قليلًا عن الحائط إذا شعرت بشدّ في الجزء الخلفي من ساقيك."),
    "low_lunge_arch": ExerciseGuide(["اخطُ بقدم واحدة للأمام وأنزل ركبتك الخلفية إلى الأرض.", "حرّك وركيك للأمام حتى تشعر بتمدد في مقدمة الورك الخلفي.", "ارفع ذراعيك معًا للأعلى وارفع صدرك في تقوس خفيف.", "اثبت 20 ثانية، بدّل الساق، وكرّر لمجموعتين على كل جانب."], ["ترك الركبة الأمامية تتجاوز أصابع القدم كثيرًا.", "الانحناء من أسفل الظهر فقط."], "ضع منشفة مطوية تحت ركبتك الخلفية، وأبقِ التقوس صغيرًا."),
    "lunges": ExerciseGuide(["قف باستقامة وقدماك بعرض الوركين.", "اخطُ خطوة كبيرة للأمام وانزل حتى تنثني الركبتان بزاوية 90 درجة تقريبًا.", "ادفع بكعبك الأمامي لتعود خطوة للخلف إلى وضع البداية.", "نفّذ 8 تكرارات على كل ساق ثم استرح، بمجموع 3 مجموعات."], ["ترك الركبة الأمامية تنثني للداخل.", "ميل الصدر كثيرًا للأمام فوق الساق الأمامية."], "اخطُ خطوة أقصر أو أمسك كرسيًا للتوازن حتى تصبح الحركة ثابتة."),
    "masai_jumps": ExerciseGuide(["قف باستقامة وذراعاك بجانبك أو مرفوعتان للأعلى.", "نفّذ قفزات صغيرة نابضة وأبقِ جسمك مستقيمًا طوال الوقت.", "اهبط بلطف على مقدمة قدميك وركبتاك مثنيتان قليلًا.", "واصل لمدة 20 ثانية، بمجموع 3 مجموعات."], ["الهبوط بقوة على الكعبين.", "الانحناء للأمام عند التعب."], "توقف إذا آلمتك ركبتاك أو ساقاك، واسترح قبل أن تحاول من جديد."),
    "morning_stretch": ExerciseGuide(["قف باستقامة ودوّر رقبتك ببطء، 5 دوائر في كل اتجاه.", "مدّ ذراعيك فوق رأسك وشبّك أصابعك وتمدد للأعلى لمدة 30 ثانية.", "انحنِ للأمام من وركيك ودع يديك تتدليان نحو أصابع قدميك.", "اخطُ إلى وضع اللانجز، واثبت 30 ثانية ثم بدّل الساق.", "تنفّس ببطء من أنفك ولا ترتد أبدًا داخل التمدد."], ["الارتداد للتعمق بدل الثبات.", "حبس النفس أثناء الثبات."], "تمدد قبل أن تتفقد هاتفك وستثبت العادة أسرع."),
    "mountain_pose": ExerciseGuide(["قف وقدماك متلاصقتان ووزنك موزع بالتساوي على القدمين.", "مدّ ذراعيك معًا فوق رأسك باستقامة وراحتاك متقابلتان.", "ارتفع على أصابع قدميك وتمدد للأعلى عبر أطراف أصابعك.", "اثبت 20 ثانية وانزل ببطء، بمجموع مجموعتين."], ["إخراج الأضلاع للأمام وتقوس أسفل الظهر.", "رفع الكتفين نحو الأذنين."], "ثبّت نظرك على نقطة أمامك، أو أبقِ كعبيك على الأرض إذا تمايلت."),
    "neck_stretches": ExerciseGuide(["اجلس أو قف باستقامة وكتفاك مسترخيتان ومنخفضتان.", "أمِل أذنك ببطء نحو كتفك واثبت 30 ثانية لكل جانب.", "أنزل ذقنك نحو صدرك واثبت 30 ثانية.", "ارفع نظرك بلطف لمدة 30 ثانية دون رمي رأسك للخلف."], ["سحب رأسك بقوة بيدك.", "رفع كتفك لملاقاة أذنك."], "نفّذها بعد جلسات الدراسة الطويلة لتخفيف التوتر."),
    "overhead_press": ExerciseGuide(["قف باستقامة وأمسك أوزانًا خفيفة أو زجاجات ماء بمستوى الكتفين.", "شدّ جذعك وادفع ذراعيك معًا للأعلى باستقامة.", "أنهِ الحركة وذراعاك بجانب أذنيك، ثم أنزلهما ببطء إلى كتفيك.", "أخرج الزفير أثناء الدفع وخذ الشهيق أثناء النزول، 10 تكرارات في كل مجموعة."], ["تقويس أسفل الظهر أثناء الدفع.", "استخدام أوزان ثقيلة لا تستطيع التحكم بها."], "ابدأ بوزن الجسم وأضف أوزانًا خفيفة عندما تصبح حركتك سهلة."),
    "pelvic_shift": ExerciseGuide(["استلقِ على ظهرك وركبتاك مثنيتان وقدماك مسطحتان على الأرض.", "أدخل عظمة الذيل وارفع عمودك الفقري عن الأرض من الأسفل للأعلى.", "توقف في الأعلى ثم انزل ببطء، فقرة بعد فقرة.", "نفّذ 10 تكرارات بطيئة ثم استرح، بمجموع مجموعتين."], ["دفع الوركين للأعلى بسرعة وفي كتلة واحدة.", "تقويس أسفل الظهر في الأعلى."], "تحرك ببطء كافٍ لتشعر بكل جزء من ظهرك وهو يلمس الأرض."),
    "pilates_core": ExerciseGuide(["اثبت في بلانك على الساعدين لمدة دقيقة واحدة وجسمك في خط مستقيم.", "استلقِ على ظهرك لتمرين الحشرة الميتة، وأنزل الذراع والساق المعاكستين ببطء.", "انتقل إلى تمرين الطائر والكلب على اليدين والركبتين، ومدّ الذراع والساق المعاكستين.", "اختم بدقيقة من جسر الأرداف ودقيقة من رفع الساقين.", "أخرج الزفير في كل مرة تشد فيها جذعك."], ["ترك الوركين يهبطان أثناء البلانك.", "تقويس أسفل الظهر بعيدًا عن الأرض أثناء تمرين الحشرة الميتة."], "البطء والتحكم أفضل من السرعة، فكل تكرار سليم يبني قوة حقيقية."),
    "pilates_roll_over": ExerciseGuide(["استلقِ على ظهرك وذراعاك بجانبك وساقاك للأعلى باستقامة.", "اضغط بذراعيك على الأرض وارفع وركيك لتقلب ساقيك فوق رأسك.", "توقف عندما تصبح ساقاك بمستوى الأرض خلف رأسك.", "انزل للخلف ببطء، ونفّذ 5 تكرارات ثم استرح، بمجموع مجموعتين."], ["تمرير الساقين بالاندفاع.", "الاستناد على الرقبة بدل الكتفين."], "ركّز وزنك على كتفيك ولا تضعه على رقبتك أبدًا، واثنِ ركبتيك لتسهيل التمرين."),
    "plank": ExerciseGuide(["ضع ساعديك على الأرض والمرفقان تحت الكتفين.", "ارجع بقدميك للخلف ليشكل جسمك خطًا مستقيمًا.", "اشدد أردافك وشدّ سرّتك للداخل واثبت 30 ثانية.", "استرح 30 ثانية وكرّر لـ 3 مجموعات."], ["ترك الوركين يهبطان نحو الأرض.", "رفع الوركين عاليًا جدًا."], "أضف 5 ثوانٍ كل أسبوع كلما أصبح أسهل."),
    "pogo_jumps": ExerciseGuide(["قف باستقامة وقدماك بعرض الوركين ويداك على وركيك.", "اقفز على مقدمة قدميك وركبتاك شبه مستقيمتين.", "اجعل كل ملامسة للأرض قصيرة وسريعة، كعصا البوغو.", "واصل لمدة 20 ثانية، بمجموع 3 مجموعات."], ["ثني الركبتين بعمق عند كل ارتداد.", "ترك الكعبين يرتطمان بالأرض."], "اقفز على سطح صلب ومستوٍ وتوقف إذا آلمتك ساقاك أو كاحلاك."),
    "posture_check": ExerciseGuide(["اضبط تذكيرًا كل ساعة لتفحص طريقة جلوسك أو وقوفك.", "ضع أذنيك فوق كتفيك وكتفيك فوق وركيك.", "دوّر كتفيك للخلف وللأسفل وصدرك مفتوح بلطف.", "تخيّل خيطًا يسحب قمة رأسك للأعلى ثم تنفّس."], ["المبالغة في التصحيح بظهر متصلب ومقوس.", "النظر إلى هاتفك والرأس مدفوع للأمام."], "ارفع شاشتك إلى مستوى عينيك وستصبح الوقفة الجيدة تلقائية."),
    "pre_sleep_routine": ExerciseGuide(["ابدأ قبل النوم بـ 30 دقيقة: خفّض الإضاءة وأبعد الشاشات.", "اقرأ كتابًا أو استمع إلى موسيقى هادئة لمدة 15 دقيقة.", "نفّذ 5 دقائق من التمدد اللطيف على سريرك أو على الأرض.", "خذ شهيقًا لمدة 4 ثوانٍ وزفيرًا لمدة 6 ثوانٍ، 10 جولات."], ["تصفح هاتفك لدقيقة إضافية واحدة فقط.", "تغيير موعد نومك كثيرًا من ليلة لأخرى."], "الوقت نفسه والخطوات نفسها كل ليلة يجعلان النوم أسهل."),
    "pull_ups": ExerciseGuide(["أمسك العقلة بقبضة من الأعلى ويداك أوسع قليلًا من كتفيك.", "ابدأ من تعلق بذراعين مستقيمتين واسحب لوحَي الكتف للأسفل.", "اسحب حتى يتجاوز ذقنك العقلة، ثم أنزل نفسك ببطء.", "نفّذ تكرارين، وانزل واسترح، بمجموع 3 مجموعات."], ["الرفس والتأرجح للوصول فوق العقلة.", "النزول بسرعة بدل النزول بتحكم."], "ثبّت باندًا تحت قدميك أو اقفز إلى الأعلى وانزل ببطء، وتأكد من متانة العقلة."),
    "puppy_pose": ExerciseGuide(["ابدأ على أربع ووركاك فوق ركبتيك مباشرة.", "مرّر يديك للأمام وأبقِ وركيك في مكانهما.", "دع صدرك وجبهتك ينزلان نحو الأرض.", "اثبت 20 ثانية ثم عُد للأعلى، بمجموع مجموعتين."], ["ترك الوركين ينزلقان للخلف نحو الكعبين.", "ثني المرفقين وإسنادهما على الأرض."], "أسند جبهتك على وسادة إذا كان تمدد كتفيك قويًا جدًا."),
    "push_ups": ExerciseGuide(["ضع يديك على الأرض أوسع قليلًا من كتفيك.", "ارجع بقدميك للخلف ليشكل جسمك خطًا مستقيمًا.", "اثنِ مرفقيك لإنزال صدرك نحو الأرض ثم ادفع للأعلى.", "نفّذ 5 تكرارات ثم استرح، بمجموع 3 مجموعات."], ["ترك الوركين يهبطان نحو الأرض.", "فتح المرفقين مباشرة إلى الجانبين."], "انزل على ركبتيك أو ضع يديك على مقعد لتسهيل التمرين."),
    "scapular_pull": ExerciseGuide(["أمسك العقلة بقبضة من الأعلى ويداك أوسع قليلًا من كتفيك.", "تعلّق بذراعين مستقيمتين ودع كتفيك ترتفعان نحو أذنيك.", "اسحب لوحَي الكتف للأسفل ليرتفع جسمك قليلًا ومرفقاك مستقيمان.", "اثبت لحظة ثم أرخِ، ونفّذ 5 تكرارات، بمجموع 3 مجموعات."], ["ثني المرفقين للسحب أعلى.", "تأرجح الساقين للمساعدة."], "تأكد من متانة العقلة، وأبقِ قدميك على صندوق إذا كان التعلق الكامل صعبًا."),
    "scapular_retraction": ExerciseGuide(["اجلس أو قف باستقامة وذراعاك مسترخيتان على جانبيك.", "اسحب لوحَي الكتف للخلف وللأسفل، كأنك تدسّهما في جيبيك الخلفيين.", "اثبت على الضغط خلال نفس بطيء واحد ثم أرخِ.", "نفّذ 10 تكرارات ثم استرح، بمجموع مجموعتين."], ["رفع الكتفين للأعلى أثناء الضغط.", "دفع الأضلاع للأمام وتقوس الظهر."], "أبقِ ذقنك مستويًا ورقبتك مسترخية طوال الوقت."),
    "seated_forward_fold": ExerciseGuide(["اجلس على الأرض وساقاك مستقيمتان وأصابع قدميك متجهة للأعلى.", "اجلس باستقامة ومدّ ذراعيك فوق رأسك.", "انحنِ للأمام من وركيك وامدد يديك نحو ساقيك أو قدميك.", "اثبت 20 ثانية ثم اجلس باستقامة، بمجموع مجموعتين."], ["تدوير أعلى الظهر للوصول إلى أصابع القدم.", "الارتداد للتعمق في التمدد."], "اثنِ ركبتيك قليلًا أو اجلس على منشفة مطوية إذا استدار أسفل ظهرك."),
    "shoulder_rolls": ExerciseGuide(["قف باستقامة وذراعاك متدليتان بارتخاء على جانبيك.", "دوّر كتفيك للأمام في دوائر كبيرة 15 مرة.", "دوّرهما للخلف 15 مرة مع ضم لوحَي الكتف معًا.", "شبّك يديك خلف ظهرك وافتح صدرك لمدة 20 ثانية."], ["رسم دوائر صغيرة ومتسرعة.", "رفع الكتفين مع حبس النفس."], "مجموعة سريعة بين الحصص أو فترات الدراسة تُبقي كتفيك مفتوحين."),
    "side_plank": ExerciseGuide(["استلقِ على جانبك وساعدك على الأرض والمرفق تحت الكتف.", "ضع قدميك فوق بعضهما وارفع وركيك عن الأرض.", "أبقِ جسمك في خط مستقيم من الرأس إلى الكعبين.", "اثبت 15 ثانية، بدّل الجانب، وكرّر لمجموعتين على كل جانب."], ["ترك الوركين يهبطان نحو الأرض.", "ميل الصدر للأمام نحو الأرض."], "أبقِ ركبتك السفلية على الأرض لتسهيل التمرين."),
    "single_leg_calf_raise": ExerciseGuide(["قف على حافة درجة على مقدمة قدم واحدة وأمسك حائطًا أو درابزينًا.", "أنزل كعبك ببطء إلى ما دون مستوى الدرجة.", "ارتفع على أصابع قدمك لأعلى ما تستطيع واثبت ثانية.", "نفّذ 8 تكرارات على كل ساق ثم استرح، بمجموع 3 مجموعات."], ["الارتداد من أسفل الحركة بدل التحرك ببطء.", "ثني الركبة لمساعدة السمانة."], "ابدأ بوزن جسمك، وإذا أضفت دامبل أو حقيبة فاختر وزنًا خفيفًا بما يكفي لإنهاء كل تكرار بشكل سليم."),
    "single_leg_hops": ExerciseGuide(["قف على ساق واحدة والقدم الأخرى مرفوعة خلفك.", "نفّذ قفزات صغيرة في المكان واهبط على مقدمة قدمك.", "أبقِ وركيك مستويين وركبتك الثابتة مثنية قليلًا.", "نفّذ 8 قفزات، بدّل الساق، وكرّر لمجموعتين على كل جانب."], ["ترك ركبة الساق القافزة تنثني للداخل.", "القفز عاليًا لدرجة فقدان توازنك."], "ابقَ قرب حائط يمكنك لمسه، وأبقِ القفزات منخفضة حتى يصبح توازنك ثابتًا."),
    "skipping_rope": ExerciseGuide(["أمسك المقبضين بمستوى الوركين والمرفقان قريبان من جانبيك.", "أدر الحبل بمعصميك لا بذراعيك كاملتين.", "اقفز بقدر ما يكفي لتمرير الحبل، واهبط على مقدمة قدميك.", "انطّ الحبل لمدة 5 دقائق، واسترح دقيقة واحدة، وكرّر لـ 3 مجموعات."], ["القفز عاليًا جدًا والتعب بسرعة.", "الهبوط بقدمين مسطحتين على الكعبين."], "التعثر أمر طبيعي، فقط ابدأ من جديد وحافظ على الإيقاع."),
    "spinal_twist": ExerciseGuide(["استلقِ على ظهرك وذراعاك ممدودتان إلى الجانبين.", "اثنِ ركبة واحدة وأنزلها عبر جسمك نحو الأرض.", "أبقِ كتفيك كلتيهما على الأرض وانظر إلى الجهة المعاكسة.", "اثبت 20 ثانية، بدّل الجانب، وكرّر لمجموعتين على كل جانب."], ["ترك الكتف المقابل يرتفع عن الأرض.", "إجبار الركبة على النزول بيدك."], "أسند ركبتك على وسادة إذا لم تصل إلى الأرض."),
    "sprint_intervals": ExerciseGuide(["سخّن بـ 5 دقائق من الهرولة الخفيفة وتأرجح الساقين.", "اركض بأقصى جهد لمدة 30 ثانية وحرّك ذراعيك بقوة.", "امشِ أو هرول ببطء لمدة 90 ثانية للتعافي.", "كرّر لـ 3 عدوات، ثم هدّئ جسمك بـ 5 دقائق من المشي."], ["العدو دون إحماء مسبق.", "الميل للخلف وفرد الخطوة بدل الدفع للأمام."], "اختر سطحًا مستويًا وآمنًا وانطلق بأقصى جهدك فقط عندما تشعر بالنشاط."),
    "squats": ExerciseGuide(["قف وقدماك بعرض الكتفين وأصابعك متجهة للخارج قليلًا.", "ادفع وركيك للخلف وانزل حتى يصبح فخذاك موازيين للأرض.", "أبقِ صدرك مرفوعًا وركبتيك في اتجاه أصابع قدميك.", "ادفع بكعبيك للوقوف، وأخرج الزفير أثناء الصعود."], ["رفع الكعبين عن الأرض.", "تدوير الظهر في أسفل الحركة."], "نفّذ مجموعاتك الأولى أمام مرآة لتتحقق من شكل حركتك."),
    "standing_side_stretch": ExerciseGuide(["قف باستقامة وقدماك بعرض الوركين.", "مدّ ذراعيك فوق رأسك وأمسك معصمًا بيدك الأخرى.", "أمِل ببطء إلى جانب واحد وأبقِ قدميك مضغوطتين على الأرض.", "اثبت 15 ثانية، بدّل الجانب، وكرّر لمجموعتين على كل جانب."], ["الميل للأمام أو الالتفاف بدل الانحناء مباشرة إلى الجانب.", "دفع الوركين بعيدًا إلى الجانب."], "تخيّل أنك تقف بين حائطين فلا تستطيع التحرك إلا جانبيًا."),
    "step_ups": ExerciseGuide(["قف أمام درجة أو مقعد منخفض متين.", "ضع قدمًا واحدة كاملة على الدرجة وادفع حتى تقف باستقامة.", "أنزل القدم الأخرى إلى الأرض ببطء.", "نفّذ 8 تكرارات على كل ساق ثم استرح، بمجموع 3 مجموعات."], ["الدفع بقوة بالقدم التي على الأرض.", "النزول بسرعة بدل النزول بتحكم."], "استخدم درجة لا تنزلق ولا تنقلب، وابدأ منخفضًا قبل أن ترتفع."),
    "superman": ExerciseGuide(["استلقِ على بطنك وذراعاك ممدودتان للأمام.", "ارفع ذراعيك وساقيك قليلًا عن الأرض.", "أبقِ رقبتك طويلة وانظر إلى الأرض واثبت ثانيتين.", "انزل ببطء، 8 تكرارات في كل مجموعة، بمجموع مجموعتين."], ["إجبار صدرك وساقيك على الارتفاع لأعلى ما تستطيع.", "رفع الرأس للأعلى وانقباض الرقبة."], "يكفي رفع بسيط. إذا شعرت بوخز في أسفل ظهرك فارتفع أقل."),
    "swimming_basketball": ExerciseGuide(["سخّن 5 دقائق بجولات سهلة أو بتنطيط خفيف للكرة.", "اسبح أو العب 30 دقيقة على الأقل بوتيرة ثابتة.", "امدد جسمك بالكامل في كل ضربة سباحة أو تسديدة أو كرة مرتدة.", "هدّئ جسمك بـ 5 دقائق من الحركة السهلة والتمدد."], ["تخطي الإحماء والبدء بأقصى سرعة.", "نسيان شرب الماء أثناء اللعب."], "أحضر صديقًا، فمن الأسهل الاستمرار في الرياضة عندما تكون اجتماعية."),
    "table_top": ExerciseGuide(["اجلس وركبتاك مثنيتان وقدماك مسطحتان ويداك على الأرض خلف وركيك.", "وجّه أصابعك نحو قدميك واضغط على يديك وقدميك.", "ارفع وركيك حتى يصبح جسمك مستويًا من الركبتين إلى الكتفين.", "اثبت 15 ثانية وانزل، بمجموع مجموعتين."], ["ترك الوركين يهبطان في المنتصف.", "رمي الرأس للخلف فتتوتر الرقبة."], "أدر أصابعك إلى الجانبين إذا شعرت بألم في معصميك."),
    "thoracic_extension": ExerciseGuide(["اجلس على كرسي متين بحيث يكون أعلى مسنده تحت لوحَي الكتف مباشرة.", "ضع يديك خلف رأسك وأبقِ مرفقيك واسعين.", "أمِل أعلى ظهرك ببطء فوق مسند الكرسي وانظر للأعلى.", "عُد للأعلى، ونفّذ 8 تكرارات ثم استرح، بمجموع مجموعتين."], ["الانحناء من أسفل الظهر بدل أعلاه.", "سحب الرأس للأمام باليدين."], "استخدم كرسيًا لا يتحرك ولا ينقلب، وأبقِ قدميك مسطحتين على الأرض."),
    "toe_touch": ExerciseGuide(["قف وقدماك بعرض الوركين وركبتاك مرتخيتان.", "انحنِ للأمام من وركيك ودع يديك تمتدان نحو أصابع قدميك.", "اثبت بلا حركة 20 ثانية وتنفّس ببطء.", "انهض ببطء، واسترح، وكرّر مرة أخرى."], ["الارتداد للوصول أبعد.", "شد الركبتين تمامًا."], "إذا لم تصل إلى أصابع قدميك فتوقف عند ساقيك. ما زال التمرين مفيدًا."),
    "tuck_jumps": ExerciseGuide(["قف باستقامة وقدماك بعرض الوركين.", "انزل بسرعة إلى ربع قرفصاء واقفز لأعلى ما تستطيع.", "اسحب ركبتيك معًا نحو صدرك في الأعلى، ثم اهبط بلطف على ركبتين مثنيتين.", "نفّذ 6 قفزات واسترح، وكرّر لـ 3 مجموعات."], ["ثني صدرك نحو ركبتيك بدل رفع الركبتين.", "الهبوط بقوة على ساقين مستقيمتين."], "استعد توازنك بين القفزات، وتأكد من وجود مساحة خالية وأرضية غير زلقة."),
    "upward_salute": ExerciseGuide(["قف وقدماك متلاصقتان وذراعاك بجانبك.", "خذ شهيقًا ومدّ ذراعيك معًا فوق رأسك.", "أبقِ أضلاعك للأسفل وكتفيك بعيدين عن أذنيك.", "اثبت 15 ثانية مع التنفس ببطء، ثم أنزل ذراعيك. بمجموع مجموعتين."], ["الميل للخلف وتقوس أسفل الظهر.", "ترك الأضلاع تندفع للأمام."], "مدّ للأعلى لا للخلف. أبقِ جسمك مستقيمًا فوق قدميك."),
    "wall_angels": ExerciseGuide(["قف وظهرك على الحائط وقدماك أمامك قليلًا.", "ضع ذراعيك على الحائط ومرفقاك مثنيان، كقائمي المرمى.", "أبقِ أضلاعك للأسفل ومرّر ذراعيك ببطء للأعلى ثم عُد للأسفل.", "نفّذ 8 تكرارات بطيئة في كل مجموعة، بمجموع مجموعتين."], ["ترك الأضلاع تبرز وأسفل الظهر يتقوس.", "ترك ذراعيك تنفصلان عن الحائط."], "ارتفع بقدر ما تبقى ذراعاك على الحائط. يصبح أسهل مع التمرين."),
    "wall_dog": ExerciseGuide(["قف مواجهًا حائطًا على بُعد طول ساق تقريبًا.", "ضع يديك على الحائط بمستوى الوركين.", "انحنِ للخلف من وركيك حتى تستقيم ذراعاك ويصبح عمودك الفقري ممدودًا.", "اثبت 20 ثانية مع التنفس ببطء، بمجموع مجموعتين."], ["تدوير أعلى الظهر.", "ثني المرفقين والاتكاء على الحائط."], "استراحة رائعة على مكتبك عندما لا تستطيع النزول إلى الأرض."),
    "wall_sit": ExerciseGuide(["قف وظهرك على الحائط وقدماك على بُعد خطوة أمامك.", "انزلق للأسفل حتى يصبح فخذاك بمستوى الأرض.", "أبقِ ركبتيك فوق كاحليك وظهرك كله على الحائط.", "اثبت 20 ثانية ثم قف، بمجموع 3 مجموعات."], ["وضع اليدين على الفخذين.", "ترك الركبتين تتجاوزان أصابع القدم للأمام."], "اجلس أعلى قليلًا إذا آلمتك ركبتاك، وانزل أكثر كلما قويت."),
    "wall_stand": ExerciseGuide(["قف وكعباك على الحائط وقدماك بعرض الوركين.", "المس الحائط بمؤخرتك ولوحَي كتفيك ومؤخرة رأسك.", "اسحب ذقنك قليلًا وأبقِ ذراعيك مسترخيتين على جانبيك.", "اثبت 5 دقائق مع التنفس بهدوء من أنفك."], ["تقويس أسفل الظهر بعيدًا عن الحائط.", "رفع الذقن بدل إبقائه مستويًا."], "لاحظ هذا الإحساس، ثم حاول أن تنقله إلى يومك."),
  },
  "id": {
    "band_pull_apart": ExerciseGuide(["Berdiri tegak dan pegang band di depanmu dengan lengan lurus setinggi bahu.", "Tarik band ke samping dengan merapatkan tulang belikatmu.", "Sentuhkan band ke dada, lalu kembalikan dengan perlahan.", "Lakukan 12 repetisi lalu istirahat, total 2 set."], ["Mengangkat bahu ke arah telinga.", "Membiarkan band menyentak balik, bukan mengembalikannya dengan perlahan."], "Pilih band yang cukup ringan agar setiap repetisi selesai dengan teknik yang baik, dan periksa dulu apakah band robek."),
    "bar_hanging": ExerciseGuide(["Pegang palang dengan genggaman dari atas, tangan selebar bahu.", "Angkat kakimu dan biarkan tubuhmu bergantung lurus dan rileks.", "Jaga bahu tetap sedikit aktif dan bernapas pelan selama 30 detik.", "Turun dengan lembut, istirahat 30 sampai 60 detik, lalu ulangi sebanyak 3 set."], ["Mengayun atau menendang-nendang kaki saat bergantung.", "Melompat jatuh dari palang, bukan turun dengan hati-hati."], "Mulai dengan tahanan yang lebih singkat dan tambah beberapa detik tiap minggu."),
    "bird_dog": ExerciseGuide(["Mulai dengan posisi merangkak, tangan di bawah bahu dan lutut di bawah pinggul.", "Julurkan satu lengan ke depan dan kaki di sisi berlawanan lurus ke belakang.", "Tahan dua detik dengan pinggul tetap rata, lalu kembali.", "Lakukan 8 repetisi, ganti sisi, dan lakukan 2 set di tiap sisi."], ["Membiarkan punggung bawah melengkung ke bawah saat kaki terangkat.", "Memutar pinggul ke samping agar kaki terangkat lebih tinggi."], "Bayangkan segelas air di atas punggung bawahmu yang tidak boleh tumpah."),
    "bow_pose": ExerciseGuide(["Berbaring tengkurap dan tekuk lututmu sehingga tumit mendekati pinggul.", "Julurkan tangan ke belakang dan pegang kedua pergelangan kaki.", "Dorong kakimu ke tangan untuk mengangkat dada dan paha.", "Tahan 10 detik dan turun dengan perlahan, total 2 set."], ["Membiarkan lutut terbuka lebih lebar dari pinggul.", "Mendongakkan kepala ke belakang dan menegangkan leher."], "Angkat hanya setinggi yang terasa nyaman, dan lewati gerakan ini jika punggung bawahmu sakit."),
    "broad_jumps": ExerciseGuide(["Berdiri dengan kaki selebar pinggul dan ujung jari kaki di belakang sebuah garis.", "Ayunkan lengan ke belakang, tekuk lutut, dan dorong pinggul ke belakang.", "Ayunkan lengan ke depan, lompat sejauh mungkin, dan mendarat dengan dua kaki.", "Tahan pendaratan satu detik, jalan kembali dan lakukan 5 lompatan, total 3 set."], ["Jatuh ke depan atau ke belakang saat mendarat.", "Mendarat dengan lutut terkunci lurus."], "Lompat di permukaan yang tidak licin, dan lompat lebih pendek dulu sampai kamu bisa menahan setiap pendaratan dengan stabil."),
    "burpees": ExerciseGuide(["Berdiri tegak, lalu squat dan letakkan tanganmu di lantai.", "Lompatkan kakimu ke belakang hingga membentuk plank yang lurus.", "Lompatkan kakimu kembali mendekati tangan.", "Lompat lurus ke atas, lakukan 5 repetisi lalu istirahat, total 3 set."], ["Membiarkan pinggul melorot saat plank.", "Mendarat keras dengan kaki lurus setelah melompat."], "Langkahkan kaki ke belakang dan ke depan, tanpa melompat, agar lebih mudah, dan perlambat jika tekniknya mulai berantakan."),
    "calf_pulses": ExerciseGuide(["Berdiri tegak dan naik ke ujung jari kaki, sentuh dinding dengan ujung jari jika perlu keseimbangan.", "Pantulkan tubuh naik turun dengan denyut kecil, hanya beberapa sentimeter.", "Jaga tumit tetap di atas lantai selama satu set penuh.", "Lanjutkan selama 20 detik, total 3 set."], ["Membiarkan tumit menyentuh lantai di antara denyutan.", "Membuat gerakan terlalu besar sampai tidak lagi menjadi denyutan."], "Rasa terbakar di betis itu normal. Nyeri tajam berarti berhenti."),
    "calf_raise": ExerciseGuide(["Berdiri tegak di samping dinding, ujung jari menyentuh dinding untuk keseimbangan.", "Naik perlahan ke bagian depan telapak kaki setinggi mungkin.", "Tahan 1 detik di atas, lalu turunkan tumit dengan perlahan.", "Lakukan 15 repetisi per set, total 3 set."], ["Memantul cepat, bukan bergerak perlahan.", "Membiarkan pergelangan kaki berputar ke luar di puncak gerakan."], "Lakukan sambil menyikat gigi supaya jadi kebiasaan harian yang mudah."),
    "cat_cow": ExerciseGuide(["Mulai dengan merangkak, pergelangan tangan di bawah bahu, lutut di bawah pinggul.", "Tarik napas, turunkan perut dan angkat dada serta pandanganmu (cow).", "Buang napas, bulatkan punggung dan tarik dagu ke dalam (cat).", "Bergeraklah perlahan mengikuti napas selama 10 putaran, 2 set."], ["Bergerak lebih cepat dari napasmu.", "Hanya menggerakkan leher, bukan seluruh tulang belakang."], "Cocok sebagai gerakan pertama di pagi hari atau untuk menyegarkan badan setelah duduk lama."),
    "chest_stretch": ExerciseGuide(["Berdiri di ambang pintu dan letakkan satu lengan bawah di kusen, siku setinggi bahu.", "Langkahkan kaki di sisi yang sama ke depan melewati pintu.", "Condongkan dada ke depan sampai terasa regangan di sepanjang bagian depan bahu.", "Tahan 20 detik, ganti sisi, dan lakukan 2 set di tiap sisi."], ["Melengkungkan punggung bawah agar bisa condong lebih jauh.", "Mengangkat bahu ke arah telinga."], "Lakukan regangan dengan lembut, dan kurangi jika bahumu terasa terjepit."),
    "childs_pose": ExerciseGuide(["Berlutut di lantai dengan ibu jari kaki saling menempel dan lutut terbuka.", "Duduk dengan pinggul ke belakang di atas tumit.", "Jalankan tanganmu ke depan dan letakkan dahi di lantai.", "Bernapas pelan selama 30 detik lalu bangun, total 2 set."], ["Mengangkat pinggul jauh dari tumit agar bisa menjangkau lebih jauh.", "Menahan napas dan menegangkan bahu."], "Selipkan bantal di antara pinggul dan tumit jika lututmu terasa kencang."),
    "chin_tucks": ExerciseGuide(["Duduk atau berdiri tegak dan lihat lurus ke depan.", "Geser dagumu lurus ke belakang, seperti membuat dagu berlipat.", "Tahan 3 detik, lalu rileks.", "Lakukan 8 repetisi per set, total 2 set."], ["Menunduk menganggukkan kepala, bukan menggesernya ke belakang.", "Mendorong terlalu keras sampai lehermu sakit."], "Lakukan beberapa kali setiap kali kamu meletakkan ponsel."),
    "cobra_stretch": ExerciseGuide(["Berbaring tengkurap dengan telapak tangan rata di bawah bahu.", "Dorong lantai menjauh dan angkat dadamu perlahan, pinggul tetap di bawah.", "Jaga siku sedikit menekuk dan bahu menjauh dari telinga.", "Tahan 15 detik sambil bernapas pelan, lalu turun dengan terkontrol."], ["Mendorong terlalu tinggi sampai punggung bawahmu terjepit.", "Mengangkat bahu ke arah telinga."], "Angkat hanya setinggi yang terasa nyaman; lama-lama akan lebih dalam."),
    "dead_bug": ExerciseGuide(["Berbaring telentang dengan lengan lurus ke atas dan lutut menekuk di atas pinggul.", "Tekan punggung bawahmu dengan lembut ke lantai.", "Turunkan satu lengan ke belakang kepala dan kaki yang berlawanan ke arah lantai, lalu kembali.", "Lakukan 8 repetisi di tiap sisi lalu istirahat, total 2 set."], ["Membiarkan punggung bawah melengkung dari lantai.", "Terburu-buru melakukan repetisi."], "Turunkan lengan dan kakimu hanya sejauh punggungmu masih bisa rata di lantai."),
    "dead_hang_active": ExerciseGuide(["Pegang palang dengan genggaman dari atas, tangan sedikit lebih lebar dari bahu.", "Bergantung dengan lengan lurus, lalu tarik tulang belikat ke bawah dan ke belakang.", "Rapatkan kaki dan kencangkan inti, lalu tahan selama 20 detik.", "Turun dengan lembut dan istirahat 40 detik di antara set."], ["Menekuk siku seperti pull-up.", "Mengangkat bahu ke arah telinga."], "Bayangkan mendorong palang menjauh darimu agar bahumu terasa bekerja."),
    "deadlift_stretch": ExerciseGuide(["Berdiri dengan kaki selebar pinggul dan lutut sedikit menekuk.", "Tekuk badan dari pinggul dan gerakkan tangan menyusuri pahamu ke bawah.", "Jaga punggung tetap rata dan jangkau ke arah jari kaki sampai hamstringmu teregang.", "Kencangkan otot bokong untuk berdiri kembali, 12 repetisi pelan per set."], ["Membulatkan punggung agar bisa menjangkau lebih rendah.", "Mengunci lutut sepenuhnya lurus."], "Bergeraklah perlahan; kendali lebih penting daripada seberapa jauh kamu menjangkau."),
    "downward_dog": ExerciseGuide(["Mulai dengan merangkak, tangan di bawah bahu.", "Angkat pinggul tinggi-tinggi sehingga tubuhmu membentuk huruf V terbalik.", "Jaga tulang belakang tetap panjang dan biarkan tumit turun ke arah lantai.", "Tahan 20 detik lalu istirahat, total 2 set."], ["Membulatkan punggung demi memaksa tumit turun.", "Mengangkat bahu ke arah telinga."], "Tekuk lutut sedikit jika punggungmu membulat. Tumitmu tidak harus menyentuh lantai."),
    "dumbbell_deadlift": ExerciseGuide(["Berdiri tegak dengan dumbbell di tiap tangan di depan pahamu.", "Lunakkan lutut dan dorong pinggul ke belakang dengan punggung rata.", "Geser beban menyusuri paha sampai tepat di bawah lutut.", "Kencangkan otot bokong untuk berdiri, lakukan 8 repetisi, total 3 set."], ["Membulatkan punggung saat beban turun.", "Mengubahnya jadi squat dengan menekuk lutut terlalu banyak."], "Pilih beban yang cukup ringan agar setiap repetisi selesai dengan teknik yang baik."),
    "dumbbell_row": ExerciseGuide(["Letakkan satu tangan di bangku atau kursi dan langkahkan kakimu ke belakang.", "Pegang dumbbell di tangan yang lain dengan punggung rata dan lengan menggantung ke bawah.", "Tarik beban ke pinggul dengan siku dekat badan, lalu turunkan dengan perlahan.", "Lakukan 8 repetisi di tiap sisi lalu istirahat, total 3 set."], ["Memutar badan untuk mengayunkan beban ke atas.", "Mengangkat bahu ke arah telinga."], "Pilih beban yang cukup ringan agar setiap repetisi selesai dengan teknik yang baik."),
    "evening_yoga": ExerciseGuide(["Mulai dengan merangkak dan alirkan gerakan cat-cow selama 60 detik.", "Duduk ke belakang dalam pose anak, lengan terjulur, dan bernapaslah selama 60 detik.", "Dorong naik ke downward dog, tumit menjangkau ke arah lantai.", "Berdiri dan tekuk badan ke depan, biarkan kepalamu menggantung berat.", "Tarik napas 4 hitungan dan buang napas 6 hitungan di setiap pose."], ["Terburu-buru berpindah pose, bukan menahannya.", "Memaksakan sebuah pose sampai sakit."], "Redupkan lampu saat bergerak agar tubuhmu lebih mudah rileks."),
    "farmer_carry": ExerciseGuide(["Berdiri di antara dua dumbbell atau dua tas berisi beban.", "Tekuk lutut, jaga punggung tetap rata, dan angkat keduanya.", "Berjalan dengan langkah kecil, bahu ke belakang dan pandangan ke depan.", "Berjalan selama 20 detik, letakkan bebannya lalu istirahat, total 3 set."], ["Condong ke satu sisi atau membiarkan bahu membulat ke depan.", "Membulatkan punggung saat mengangkat atau meletakkan beban."], "Pilih beban yang cukup ringan agar setiap set selesai dengan teknik yang baik, dan jaga kedua sisi tetap sama berat."),
    "glute_bridge": ExerciseGuide(["Berbaring telentang, lutut menekuk, telapak kaki rata dan selebar pinggul.", "Dorong lewat tumit dan angkat pinggul ke arah langit-langit.", "Kencangkan otot bokong di atas selama 2 detik.", "Turun perlahan, 12 repetisi per set, total 3 set."], ["Mendorong dengan jari kaki, bukan tumit.", "Melengkungkan punggung bawah berlebihan di atas."], "Jika terasa di otot bokong, bukan di punggung bawah, berarti kamu melakukannya dengan benar."),
    "goblet_squat": ExerciseGuide(["Peluk satu dumbbell atau ransel berisi beban di dada dengan kedua tangan.", "Berdiri dengan kaki selebar bahu dan ujung jari kaki sedikit menghadap keluar.", "Duduk di antara tumitmu dengan dada tegak, lalu berdiri kembali.", "Lakukan 8 repetisi lalu istirahat, total 3 set."], ["Membiarkan lutut masuk ke dalam.", "Membulatkan punggung dan membiarkan dada turun."], "Pilih beban yang cukup ringan agar setiap repetisi selesai dengan teknik yang baik."),
    "hanging_knee_raise": ExerciseGuide(["Pegang palang dengan genggaman dari atas dan bergantung dengan lengan lurus.", "Tarik bahumu ke bawah menjauh dari telinga.", "Angkat kedua lutut setinggi pinggul tanpa mengayun, lalu turunkan dengan perlahan.", "Lakukan 5 repetisi, turun dari palang lalu istirahat, total 3 set."], ["Mengayunkan badan untuk melemparkan lutut ke atas.", "Bergantung dengan bahu terangkat sampai dekat telinga."], "Pastikan palangnya kokoh sebelum bergantung, dan turun dengan hati-hati, jangan melompat jatuh."),
    "high_knees": ExerciseGuide(["Berdiri tegak dengan kaki selebar pinggul.", "Lari di tempat dan angkat tiap lutut setinggi pinggul.", "Ayunkan lengan dan tetap ringan di bagian depan telapak kaki.", "Lanjutkan selama 20 detik, total 3 set."], ["Condong ke belakang saat lutut naik.", "Menghentak lantai dengan telapak kaki rata."], "Perlambat menjadi jalan di tempat dengan lutut tinggi jika kamu mulai kehabisan napas."),
    "hiit_workout": ExerciseGuide(["Pemanasan 3 menit dengan jalan di tempat dan putaran lengan.", "Lakukan burpee, mountain climber, dan jump squat, masing-masing 45 detik.", "Istirahat 15 detik di antara gerakan dan bernapas dalam-dalam.", "Selesaikan 4 putaran, lalu berjalan pelan sampai napasmu tenang."], ["Membiarkan teknik berantakan demi lebih cepat.", "Menahan napas saat interval berat."], "Ikuti kecepatanmu sendiri; menyelesaikan semua 4 putaran lebih baik daripada start yang cepat."),
    "hip_flexor_stretch": ExerciseGuide(["Berlutut dengan satu lutut dan kaki yang lain menapak rata di depanmu.", "Selipkan pinggul sedikit ke bawah dan kencangkan otot bokong kaki belakang.", "Geser maju dengan lembut sampai terasa regangan di bagian depan pinggul.", "Tahan 30 detik sambil bernapas pelan, lalu ganti sisi."], ["Melengkungkan punggung bawah, bukan menyelipkan pinggul.", "Membiarkan lutut depan melewati jari kaki."], "Letakkan handuk terlipat di bawah lututmu supaya lebih nyaman."),
    "inversion_hang": ExerciseGuide(["Lakukan posisi terbalik hanya dengan pengawasan orang dewasa dan pada alat yang stabil dan sudah diperiksa.", "Kunci pergelangan kakimu dengan aman dan mulai dari kemiringan ringan, jangan langsung terbalik penuh.", "Rilekskan lenganmu dan bernapas pelan hingga 1 menit.", "Kembali tegak dengan perlahan dan duduk sebentar sebelum berdiri.", "Berhenti segera jika kamu merasa pusing, ada tekanan di kepala, atau nyeri apa pun."], ["Langsung terbalik penuh di sesi-sesi pertamamu.", "Berdiri cepat tepat setelah posisi terbalik."], "Sesi singkat dan lembut sudah cukup; tidak perlu bergantung lebih lama."),
    "jump_squats": ExerciseGuide(["Berdiri dengan kaki selebar bahu dan dada tegak.", "Duduk ke belakang dalam squat sampai pahamu hampir sejajar dengan lantai.", "Dorong kuat lewat kakimu, lompat lurus ke atas, dan mendarat dengan lembut kembali dalam posisi squat.", "Lakukan 8 lompatan, istirahat, dan ulangi sampai total 3 set."], ["Membiarkan lutut masuk ke dalam saat mendarat.", "Mendarat dengan kaki kaku dan lurus."], "Mendaratlah sepelan mungkin, dan hentikan set ketika pendaratanmu mulai berisik."),
    "jumping": ExerciseGuide(["Berdiri dengan kaki selebar pinggul dan lengan rileks di samping.", "Tekuk lutut, ayunkan lengan, dan lompat lurus ke atas.", "Mendarat dengan lembut di bagian depan telapak kaki dengan lutut sedikit menekuk.", "Lakukan 20 lompatan, istirahat 30 detik, dan ulangi sebanyak 3 set."], ["Mendarat dengan kaki kaku di atas tumit.", "Membiarkan lutut masuk ke dalam saat mendarat."], "Pendaratan yang tenang berarti kendali yang baik, jadi cobalah mendarat seperti kucing."),
    "knee_circles": ExerciseGuide(["Berdiri dengan kaki rapat dan tekuk lututmu sedikit.", "Letakkan tanganmu di lutut.", "Buat putaran kecil dan pelan dengan lututmu selama 15 detik ke satu arah.", "Ganti arah dan putar 15 detik ke arah sebaliknya."], ["Membuat putaran besar yang memelintir lutut.", "Memutar hanya ke satu arah."], "Gunakan sebagai pemanasan sebelum melompat atau berlari."),
    "legs_up_wall": ExerciseGuide(["Duduk menyamping di dekat dinding dengan satu pinggul menyentuhnya.", "Ayunkan kakimu ke atas dinding sambil berbaring ke belakang di lantai.", "Biarkan lenganmu beristirahat di samping dan rilekskan kaki di dinding.", "Bertahan selama 3 menit sambil bernapas pelan."], ["Mengangkat punggung bawah dari lantai.", "Mengunci lutut dengan keras dan menegangkan kaki."], "Geser pinggulmu sedikit menjauh dari dinding jika bagian belakang kakimu terasa kencang."),
    "low_lunge_arch": ExerciseGuide(["Langkahkan satu kaki ke depan dan turunkan lutut belakang ke lantai.", "Geser pinggul ke depan sampai terasa regangan di bagian depan pinggul belakang.", "Angkat kedua lengan ke atas dan angkat dada dalam lengkungan yang lembut.", "Tahan 20 detik, ganti kaki, dan lakukan 2 set di tiap sisi."], ["Membiarkan lutut depan maju jauh melewati jari kaki.", "Melengkung hanya dari punggung bawah."], "Letakkan handuk terlipat di bawah lutut belakang, dan buat lengkungannya kecil saja."),
    "lunges": ExerciseGuide(["Berdiri tegak dengan kaki selebar pinggul.", "Ambil langkah besar ke depan dan turun sampai kedua lutut menekuk sekitar 90 derajat.", "Dorong lewat tumit depan untuk melangkah kembali ke posisi awal.", "Lakukan 8 repetisi di tiap kaki lalu istirahat, total 3 set."], ["Membiarkan lutut depan masuk ke dalam.", "Mencondongkan dada jauh ke depan di atas kaki depan."], "Ambil langkah yang lebih pendek atau pegang kursi untuk keseimbangan sampai gerakannya terasa stabil."),
    "masai_jumps": ExerciseGuide(["Berdiri tegak dengan lengan di samping atau terjulur ke atas.", "Lakukan lompatan kecil yang melenting dan jaga tubuh tetap tegak sepanjang waktu.", "Mendarat dengan lembut di bagian depan telapak kaki, lutut sedikit menekuk.", "Lanjutkan selama 20 detik, total 3 set."], ["Mendarat keras di atas tumit.", "Membungkuk ke depan saat mulai lelah."], "Berhenti jika lutut atau tulang keringmu sakit, dan istirahat sebelum mencoba lagi."),
    "morning_stretch": ExerciseGuide(["Berdiri tegak dan putar lehermu perlahan, 5 putaran ke tiap arah.", "Julurkan kedua lengan ke atas kepala, kaitkan jari-jari, dan regangkan ke atas selama 30 detik.", "Tekuk badan ke depan dari pinggul dan biarkan tanganmu menggantung ke arah jari kaki.", "Melangkah ke posisi lunge, tahan 30 detik, lalu ganti kaki.", "Bernapaslah pelan lewat hidung dan jangan memantul saat meregang."], ["Memantul untuk masuk lebih dalam, bukan menahan diam.", "Menahan napas saat menahan posisi."], "Meregang sebelum mengecek ponsel membuat kebiasaan ini lebih cepat menetap."),
    "mountain_pose": ExerciseGuide(["Berdiri dengan kaki rapat dan beban tubuh merata di kedua kaki.", "Julurkan kedua lengan lurus ke atas kepala dengan telapak tangan saling berhadapan.", "Naik ke ujung jari kaki dan regangkan ke atas lewat ujung jarimu.", "Tahan 20 detik dan turun dengan perlahan, total 2 set."], ["Membuka tulang rusuk dan melengkungkan punggung bawah.", "Mengangkat bahu ke arah telinga."], "Fokuskan matamu pada satu titik di depanmu, atau biarkan tumit tetap di lantai jika kamu goyah."),
    "neck_stretches": ExerciseGuide(["Duduk atau berdiri tegak dengan bahu rileks dan turun.", "Miringkan telingamu perlahan ke arah bahu dan tahan 30 detik per sisi.", "Turunkan dagumu ke arah dada dan tahan selama 30 detik.", "Angkat pandanganmu dengan lembut selama 30 detik tanpa menjatuhkan kepala ke belakang."], ["Menarik kepala dengan keras memakai tangan.", "Mengangkat bahu untuk menemui telinga."], "Lakukan ini setelah sesi belajar yang panjang untuk melepas ketegangan."),
    "overhead_press": ExerciseGuide(["Berdiri tegak sambil memegang beban ringan atau botol air setinggi bahu.", "Kencangkan inti dan dorong kedua lengan lurus ke atas kepala.", "Akhiri dengan lengan di samping telinga, lalu turunkan perlahan ke bahu.", "Buang napas saat mendorong, tarik napas saat menurunkan, 10 repetisi per set."], ["Melengkungkan punggung bawah saat mendorong.", "Memakai beban yang terlalu berat untuk dikendalikan."], "Mulai dengan berat badan saja dan tambahkan beban ringan setelah tekniknya terasa mudah."),
    "pelvic_shift": ExerciseGuide(["Berbaring telentang dengan lutut menekuk dan telapak kaki rata di lantai.", "Selipkan tulang ekor dan lepaskan tulang belakang dari lantai mulai dari bawah.", "Jeda di atas, lalu turun perlahan, satu ruas tulang demi satu ruas.", "Lakukan 10 repetisi pelan lalu istirahat, total 2 set."], ["Mendorong pinggul ke atas dengan cepat sekaligus.", "Melengkungkan punggung bawah di atas."], "Bergeraklah cukup pelan untuk merasakan setiap bagian punggungmu menyentuh lantai."),
    "pilates_core": ExerciseGuide(["Tahan forearm plank selama 1 menit, tubuh dalam satu garis lurus.", "Berbaring telentang untuk dead bug, turunkan lengan dan kaki yang berlawanan perlahan.", "Beralih ke bird dog dengan posisi merangkak, julurkan lengan dan kaki yang berlawanan.", "Akhiri dengan 1 menit glute bridge dan 1 menit angkat kaki.", "Buang napas setiap kali kamu mengencangkan inti."], ["Membiarkan pinggul melorot saat plank.", "Melengkungkan punggung bawah dari lantai saat dead bug."], "Pelan dan terkontrol lebih baik daripada cepat; setiap repetisi yang bersih membangun kekuatan nyata."),
    "pilates_roll_over": ExerciseGuide(["Berbaring telentang dengan lengan di samping dan kaki lurus ke atas.", "Tekan lenganmu ke lantai dan angkat pinggul untuk menggulingkan kaki ke atas kepala.", "Berhenti saat kakimu sejajar dengan lantai di belakang kepala.", "Gulung turun perlahan, lakukan 5 repetisi lalu istirahat, total 2 set."], ["Mengayunkan kaki ke atas dengan momentum.", "Berguling ke leher, bukan ke bahu."], "Pusatkan beratmu di bahu dan jangan pernah di leher, dan tekuk lutut agar lebih mudah."),
    "plank": ExerciseGuide(["Letakkan lengan bawahmu di lantai, siku di bawah bahu.", "Langkahkan kakimu ke belakang sehingga tubuhmu membentuk satu garis lurus.", "Kencangkan otot bokong, tarik pusar ke dalam, dan tahan 30 detik.", "Istirahat 30 detik dan ulangi sebanyak 3 set."], ["Membiarkan pinggul melorot ke arah lantai.", "Mengangkat pinggul terlalu tinggi."], "Tambah 5 detik setiap minggu seiring gerakannya jadi lebih mudah."),
    "pogo_jumps": ExerciseGuide(["Berdiri tegak dengan kaki selebar pinggul dan tangan di pinggang.", "Memantul di bagian depan telapak kaki dengan lutut hampir lurus.", "Jaga setiap sentuhan ke tanah singkat dan cepat, seperti tongkat pogo.", "Lanjutkan selama 20 detik, total 3 set."], ["Menekuk lutut dalam-dalam di setiap pantulan.", "Membiarkan tumit menghantam lantai."], "Melompatlah di permukaan yang keras dan rata, dan berhenti jika tulang kering atau pergelangan kakimu sakit."),
    "posture_check": ExerciseGuide(["Atur pengingat setiap jam untuk memeriksa cara dudukmu atau berdirimu.", "Susun telingamu di atas bahu dan bahumu di atas pinggul.", "Putar bahu ke belakang dan ke bawah, dada terbuka dengan lembut.", "Bayangkan seutas tali menarik puncak kepalamu ke atas, lalu bernapaslah."], ["Mengoreksi berlebihan dengan punggung kaku dan melengkung.", "Menunduk melihat ponsel dengan kepala terdorong ke depan."], "Naikkan layarmu setinggi mata dan postur yang baik akan terjadi dengan sendirinya."),
    "pre_sleep_routine": ExerciseGuide(["Mulai 30 menit sebelum tidur: redupkan lampu dan simpan layar.", "Baca buku atau dengarkan musik yang tenang selama 15 menit.", "Lakukan peregangan lembut 5 menit di tempat tidur atau di lantai.", "Tarik napas 4 detik dan buang 6 detik, 10 putaran."], ["Menggulir ponsel hanya untuk semenit lagi.", "Mengubah jam tidurmu terlalu banyak dari malam ke malam."], "Jam yang sama dan langkah yang sama setiap malam membuat tidur lebih mudah."),
    "pull_ups": ExerciseGuide(["Pegang palang dengan genggaman dari atas, tangan sedikit lebih lebar dari bahu.", "Mulai dari posisi bergantung dengan lengan lurus dan tarik tulang belikat ke bawah.", "Tarik sampai dagumu melewati palang, lalu turunkan dirimu perlahan.", "Lakukan 2 repetisi, turun dari palang lalu istirahat, total 3 set."], ["Menendang dan mengayun agar bisa melewati palang.", "Jatuh cepat, bukan turun dengan terkontrol."], "Lilitkan band di bawah kaki atau lompat ke atas lalu turun perlahan, dan pastikan palangnya kokoh."),
    "puppy_pose": ExerciseGuide(["Mulai dengan merangkak dan pinggul tepat di atas lutut.", "Jalankan tanganmu ke depan dan biarkan pinggul tetap di tempatnya.", "Biarkan dada dan dahimu turun ke arah lantai.", "Tahan 20 detik dan kembali naik, total 2 set."], ["Membiarkan pinggul bergeser ke belakang mendekati tumit.", "Menekuk siku dan menaruhnya di lantai."], "Letakkan dahimu di atas bantal jika regangan di bahumu terasa terlalu kuat."),
    "push_ups": ExerciseGuide(["Letakkan tanganmu di lantai sedikit lebih lebar dari bahu.", "Langkahkan kakimu ke belakang sehingga tubuhmu membentuk satu garis lurus.", "Tekuk siku untuk menurunkan dada ke lantai, lalu dorong kembali ke atas.", "Lakukan 5 repetisi lalu istirahat, total 3 set."], ["Membiarkan pinggul melorot ke arah lantai.", "Membuka siku lurus ke samping."], "Turun ke lutut atau letakkan tangan di bangku agar lebih mudah."),
    "scapular_pull": ExerciseGuide(["Pegang palang dengan genggaman dari atas, tangan sedikit lebih lebar dari bahu.", "Bergantung dengan lengan lurus dan biarkan bahu naik ke arah telinga.", "Tarik tulang belikat ke bawah sehingga tubuhmu terangkat sedikit, siku tetap lurus.", "Tahan sedetik lalu lepaskan, lakukan 5 repetisi, total 3 set."], ["Menekuk siku untuk menarik lebih tinggi.", "Mengayunkan kaki untuk membantu."], "Pastikan palangnya kokoh, dan letakkan kakimu di atas kotak jika bergantung penuh terlalu berat."),
    "scapular_retraction": ExerciseGuide(["Duduk atau berdiri tegak dengan lengan rileks di samping.", "Tarik tulang belikat ke belakang dan ke bawah, seperti menyelipkannya ke saku belakang.", "Tahan rapatannya selama satu napas yang pelan, lalu lepaskan.", "Lakukan 10 repetisi lalu istirahat, total 2 set."], ["Mengangkat bahu sambil merapatkan.", "Mendorong tulang rusuk ke depan dan melengkungkan punggung."], "Jaga dagu tetap sejajar dan leher rileks sepanjang waktu."),
    "seated_forward_fold": ExerciseGuide(["Duduk di lantai dengan kaki lurus dan jari kaki menunjuk ke atas.", "Duduk tegak dan julurkan kedua lengan ke atas kepala.", "Tekuk badan ke depan dari pinggul dan jangkau tulang keringmu atau kakimu.", "Tahan 20 detik dan duduk tegak kembali, total 2 set."], ["Membulatkan punggung atas untuk menggapai jari kaki.", "Memantul agar masuk lebih dalam ke regangan."], "Tekuk lutut sedikit atau duduk di atas handuk terlipat jika punggung bawahmu membulat."),
    "shoulder_rolls": ExerciseGuide(["Berdiri tegak dengan lengan menggantung longgar di samping.", "Putar bahumu ke depan dalam lingkaran besar sebanyak 15 kali.", "Putar ke belakang 15 kali sambil merapatkan tulang belikat.", "Kaitkan tanganmu di belakang punggung dan buka dada selama 20 detik."], ["Membuat lingkaran kecil yang terburu-buru.", "Mengangkat bahu sambil menahan napas."], "Satu set singkat di sela pelajaran atau waktu belajar menjaga bahumu tetap terbuka."),
    "side_plank": ExerciseGuide(["Berbaring miring dengan lengan bawah di lantai, siku di bawah bahu.", "Tumpuk kakimu dan angkat pinggul dari lantai.", "Jaga tubuhmu dalam satu garis lurus dari kepala sampai tumit.", "Tahan 15 detik, ganti sisi, dan lakukan 2 set di tiap sisi."], ["Membiarkan pinggul jatuh ke arah lantai.", "Menggulirkan dada ke depan ke arah lantai."], "Biarkan lutut bagian bawah tetap di lantai agar lebih mudah."),
    "single_leg_calf_raise": ExerciseGuide(["Berdiri di tepi undakan dengan bagian depan telapak satu kaki dan berpeganglah pada dinding atau pagar.", "Turunkan tumitmu perlahan sampai di bawah permukaan undakan.", "Naik setinggi mungkin ke ujung jari kaki dan jeda sedetik.", "Lakukan 8 repetisi di tiap kaki lalu istirahat, total 3 set."], ["Memantul dari bawah, bukan bergerak perlahan.", "Menekuk lutut untuk membantu betis."], "Mulai dengan berat badan saja, dan jika menambah dumbbell atau ransel, pilih beban yang cukup ringan agar setiap repetisi selesai dengan teknik yang baik."),
    "single_leg_hops": ExerciseGuide(["Berdiri dengan satu kaki dan kaki yang lain terangkat ke belakang.", "Lakukan lompatan kecil di tempat, mendarat di bagian depan telapak kaki.", "Jaga pinggul tetap rata dan lutut kaki tumpuan sedikit menekuk.", "Lakukan 8 lompatan, ganti kaki, dan lakukan 2 set di tiap sisi."], ["Membiarkan lutut kaki yang melompat masuk ke dalam.", "Melompat terlalu tinggi sampai kehilangan keseimbangan."], "Berdirilah dekat dinding yang bisa kamu sentuh, dan jaga lompatan tetap rendah sampai keseimbanganmu terasa mantap."),
    "skipping_rope": ExerciseGuide(["Pegang gagang setinggi pinggul, siku dekat dengan sisi badan.", "Putar tali dengan pergelangan tangan, bukan seluruh lengan.", "Lompat setinggi yang cukup untuk melewati tali, mendarat di bagian depan telapak kaki.", "Lompat tali selama 5 menit, istirahat 1 menit, dan ulangi sebanyak 3 set."], ["Melompat terlalu tinggi dan cepat lelah.", "Mendarat dengan telapak kaki rata di atas tumit."], "Tersandung itu normal; mulai lagi saja dan jaga ritmenya."),
    "spinal_twist": ExerciseGuide(["Berbaring telentang dengan lengan terbuka ke samping.", "Tekuk satu lutut dan bawa menyilang tubuhmu ke arah lantai.", "Jaga kedua bahu di lantai dan tengok ke sisi yang berlawanan.", "Tahan 20 detik, ganti sisi, dan lakukan 2 set di tiap sisi."], ["Membiarkan bahu di sisi yang berlawanan terangkat dari lantai.", "Memaksa lutut turun dengan tangan."], "Letakkan lututmu di atas bantal jika tidak sampai ke lantai."),
    "sprint_intervals": ExerciseGuide(["Pemanasan dengan jogging santai 5 menit dan ayunan kaki.", "Sprint dengan usaha penuh selama 30 detik sambil mengayunkan lengan.", "Jalan atau jogging pelan selama 90 detik untuk pulih.", "Ulangi sampai 3 sprint, lalu pendinginan dengan berjalan 5 menit."], ["Sprint tanpa pemanasan dulu.", "Condong ke belakang dan melangkah terlalu lebar, bukan mendorong ke depan."], "Pilih permukaan yang rata dan aman, dan kerahkan semuanya hanya saat tubuhmu terasa segar."),
    "squats": ExerciseGuide(["Berdiri dengan kaki selebar bahu, jari kaki sedikit menghadap keluar.", "Dorong pinggul ke belakang dan turun sampai pahamu sejajar dengan lantai.", "Jaga dada tegak dan lutut sejalan dengan jari kaki.", "Dorong lewat tumit untuk berdiri, buang napas saat naik."], ["Mengangkat tumit dari lantai.", "Membulatkan punggung di bawah."], "Lakukan set pertamamu di depan cermin untuk memeriksa tekniknya."),
    "standing_side_stretch": ExerciseGuide(["Berdiri tegak dengan kaki selebar pinggul.", "Julurkan kedua lengan ke atas kepala dan pegang satu pergelangan tangan dengan tangan yang lain.", "Condongkan badan perlahan ke satu sisi dan tekan kedua kaki ke lantai.", "Tahan 15 detik, ganti sisi, dan lakukan 2 set di tiap sisi."], ["Condong ke depan atau memutar, bukan menekuk lurus ke samping.", "Mendorong pinggul jauh ke samping."], "Bayangkan kamu berdiri di antara dua dinding, sehingga hanya bisa bergerak ke samping."),
    "step_ups": ExerciseGuide(["Berdiri di depan undakan atau bangku rendah yang kokoh.", "Letakkan seluruh telapak satu kaki di undakan dan dorong naik sampai berdiri tegak.", "Turunkan kaki yang lain kembali ke lantai dengan perlahan.", "Lakukan 8 repetisi di tiap kaki lalu istirahat, total 3 set."], ["Mendorong keras dengan kaki yang di lantai.", "Jatuh cepat, bukan turun dengan terkontrol."], "Gunakan undakan yang tidak bisa bergeser atau terbalik, dan mulai dari yang rendah sebelum naik lebih tinggi."),
    "superman": ExerciseGuide(["Berbaring tengkurap dengan lengan terjulur ke depan.", "Angkat lengan dan kakimu sedikit dari lantai.", "Jaga leher tetap panjang, lihat ke lantai, dan tahan 2 detik.", "Turun perlahan, 8 repetisi per set, total 2 set."], ["Memaksa dada dan kaki naik setinggi mungkin.", "Mendongakkan kepala dan menjepit leher."], "Angkatan kecil sudah cukup. Jika punggung bawahmu terjepit, angkat lebih rendah."),
    "swimming_basketball": ExerciseGuide(["Pemanasan 5 menit dengan berenang santai atau men-dribble ringan.", "Berenang atau bermain minimal 30 menit dengan kecepatan stabil.", "Julurkan badan sepenuhnya di setiap kayuhan, tembakan, atau rebound.", "Pendinginan dengan 5 menit gerakan santai dan peregangan."], ["Melewatkan pemanasan dan langsung mulai dengan kecepatan penuh.", "Lupa minum air saat bermain."], "Ajak teman; olahraga lebih mudah dijaga kalau dilakukan bersama."),
    "table_top": ExerciseGuide(["Duduk dengan lutut menekuk, telapak kaki rata, dan tangan di lantai di belakang pinggul.", "Arahkan jari-jari ke kakimu dan tekan tangan serta kakimu.", "Angkat pinggul sampai tubuhmu rata dari lutut sampai bahu.", "Tahan 15 detik dan turun, total 2 set."], ["Membiarkan pinggul melorot di tengah.", "Menjatuhkan kepala ke belakang sehingga leher tegang."], "Arahkan jari-jarimu keluar ke samping jika pergelangan tanganmu terasa sakit."),
    "thoracic_extension": ExerciseGuide(["Duduk di kursi kokoh dengan sandarannya tepat di bawah tulang belikatmu.", "Letakkan tangan di belakang kepala dan jaga siku tetap terbuka lebar.", "Sandarkan punggung atasmu perlahan ke sandaran kursi dan lihat ke atas.", "Kembali naik, lakukan 8 repetisi lalu istirahat, total 2 set."], ["Menekuk dari punggung bawah, bukan dari punggung atas.", "Menarik kepala ke depan dengan tangan."], "Gunakan kursi yang tidak bisa menggelinding atau terbalik, dan letakkan kaki rata di lantai."),
    "toe_touch": ExerciseGuide(["Berdiri dengan kaki selebar pinggul dan lutut lunak.", "Tekuk badan ke depan dari pinggul dan biarkan tanganmu menjangkau jari kaki.", "Diam selama 20 detik dan bernapas pelan.", "Gulung naik perlahan, istirahat, dan ulangi sekali lagi."], ["Memantul untuk menjangkau lebih jauh.", "Mengunci lutut lurus."], "Jika tidak sampai ke jari kaki, berhenti di tulang keringmu. Tetap bermanfaat."),
    "tuck_jumps": ExerciseGuide(["Berdiri tegak dengan kaki selebar pinggul.", "Turun cepat ke seperempat squat dan lompat setinggi mungkin.", "Tarik kedua lutut ke arah dada di puncak, lalu mendarat dengan lembut dengan lutut menekuk.", "Lakukan 6 lompatan, istirahat, dan ulangi sampai total 3 set."], ["Membungkukkan dada ke lutut, bukan mengangkat lutut.", "Mendarat keras dengan kaki lurus."], "Atur ulang keseimbanganmu di antara lompatan, dan pastikan ada ruang kosong serta lantai yang tidak licin."),
    "upward_salute": ExerciseGuide(["Berdiri dengan kaki rapat dan lengan di samping.", "Tarik napas dan julurkan kedua lengan ke atas kepala.", "Jaga tulang rusuk tetap turun dan bahu menjauh dari telinga.", "Tahan 15 detik sambil bernapas pelan, lalu turunkan lengan. Total 2 set."], ["Condong ke belakang dan melengkungkan punggung bawah.", "Membiarkan tulang rusuk menonjol ke depan."], "Raih ke atas, bukan ke belakang. Jaga tubuhmu tertumpuk lurus di atas kaki."),
    "wall_angels": ExerciseGuide(["Berdiri dengan punggung bersandar di dinding, kaki sedikit di depanmu.", "Letakkan lenganmu di dinding dengan siku menekuk, seperti tiang gawang.", "Jaga tulang rusuk tetap turun dan geser lenganmu perlahan ke atas, lalu kembali turun.", "Lakukan 8 repetisi pelan per set, total 2 set."], ["Membiarkan tulang rusuk menonjol dan punggung bawah melengkung.", "Membiarkan lengan lepas dari dinding."], "Naiklah hanya sejauh lenganmu masih bisa menempel di dinding. Akan makin mudah dengan latihan."),
    "wall_dog": ExerciseGuide(["Berdiri menghadap dinding, sejauh kira-kira satu panjang kaki.", "Letakkan tanganmu di dinding setinggi pinggul.", "Tekuk badan ke belakang dari pinggul sampai lenganmu lurus dan tulang belakangmu panjang.", "Tahan 20 detik sambil bernapas pelan, total 2 set."], ["Membulatkan punggung atas.", "Menekuk siku dan bersandar pada dinding."], "Jeda yang bagus di meja kerja saat kamu tidak bisa turun ke lantai."),
    "wall_sit": ExerciseGuide(["Berdiri dengan punggung bersandar di dinding dan kaki satu langkah di depanmu.", "Geser turun sampai pahamu sejajar dengan lantai.", "Jaga lutut di atas pergelangan kaki dan seluruh punggung menempel di dinding.", "Tahan 20 detik lalu berdiri, total 3 set."], ["Menaruh tangan di atas paha.", "Membiarkan lutut maju melewati jari kaki."], "Duduklah sedikit lebih tinggi jika lututmu protes, dan turun lebih rendah seiring kamu makin kuat."),
    "wall_stand": ExerciseGuide(["Berdiri dengan tumit menempel dinding, kaki selebar pinggul.", "Sentuhkan bokong, tulang belikat, dan belakang kepalamu ke dinding.", "Selipkan dagu sedikit dan biarkan lenganmu rileks di samping.", "Tahan 5 menit sambil bernapas tenang lewat hidung."], ["Melengkungkan punggung bawah jauh dari dinding.", "Mendongakkan dagu, bukan menjaganya tetap sejajar."], "Perhatikan bagaimana rasanya, lalu cobalah membawanya ke dalam harimu."),
  },
  "ms": {
    "band_pull_apart": ExerciseGuide(["Berdiri tegak dan pegang band di hadapan anda dengan lengan lurus setinggi bahu.", "Tarik band ke sisi dengan merapatkan tulang belikat anda.", "Sentuhkan band pada dada, kemudian kembalikan dengan perlahan.", "Buat 12 ulangan dan rehat, 2 set kesemuanya."], ["Menjongket bahu ke arah telinga.", "Membiarkan band tersentap balik dan bukannya memulangkannya dengan perlahan."], "Pilih band yang cukup ringan supaya setiap ulangan dapat disiapkan dengan bentuk yang betul, dan periksa dahulu sama ada band koyak."),
    "bar_hanging": ExerciseGuide(["Pegang palang dengan genggaman atas, tangan selebar bahu.", "Angkat kaki anda dan biarkan badan bergayut lurus dan santai.", "Pastikan bahu sedikit aktif dan bernafas perlahan selama 30 saat.", "Turun dengan lembut, rehat 30 hingga 60 saat, kemudian ulang untuk 3 set."], ["Mengayun atau menendang kaki semasa bergayut.", "Terjun dari palang dan bukannya turun dengan berhati-hati."], "Mulakan dengan tahanan yang lebih pendek dan tambah beberapa saat setiap minggu."),
    "bird_dog": ExerciseGuide(["Mulakan dalam posisi merangkak, tangan di bawah bahu dan lutut di bawah pinggul.", "Julurkan satu lengan ke hadapan dan kaki bertentangan lurus ke belakang.", "Tahan selama dua saat dengan pinggul sama rata, kemudian kembali.", "Buat 8 ulangan, tukar sisi, dan buat 2 set pada setiap sisi."], ["Membiarkan belakang bawah melendut apabila kaki diangkat.", "Memutar pinggul terbuka untuk mengangkat kaki lebih tinggi."], "Bayangkan segelas air di atas belakang bawah anda yang tidak boleh tumpah."),
    "bow_pose": ExerciseGuide(["Berbaring meniarap dan bengkokkan lutut supaya tumit menghampiri pinggul.", "Capai ke belakang dan pegang kedua-dua buku lali.", "Tendang kaki ke arah tangan untuk mengangkat dada dan paha.", "Tahan 10 saat dan turun perlahan-lahan, 2 set kesemuanya."], ["Membiarkan lutut terbuka lebih luas daripada pinggul.", "Mendongak kepala ke belakang dan menegangkan leher."], "Angkat setakat yang terasa selesa sahaja, dan langkau pergerakan ini jika belakang bawah anda sakit."),
    "broad_jumps": ExerciseGuide(["Berdiri dengan kaki selebar pinggul dan jari kaki di belakang satu garisan.", "Ayunkan lengan ke belakang, bengkokkan lutut dan tolak pinggul ke belakang.", "Ayunkan lengan ke hadapan, lompat sejauh mungkin dan mendarat dengan kedua-dua kaki.", "Kekalkan pendaratan selama satu saat, berjalan balik dan buat 5 lompatan, 3 set kesemuanya."], ["Jatuh ke hadapan atau ke belakang semasa mendarat.", "Mendarat dengan lutut terkunci kaku."], "Lompat di permukaan yang tidak licin, dan lompat lebih pendek sehingga anda dapat mengekalkan setiap pendaratan dengan stabil."),
    "burpees": ExerciseGuide(["Berdiri tegak, kemudian squat dan letakkan tangan di atas lantai.", "Lompatkan kaki ke belakang dalam posisi plank yang lurus.", "Lompatkan kaki ke dalam semula ke arah tangan.", "Lompat lurus ke atas, buat 5 ulangan dan rehat, 3 set kesemuanya."], ["Membiarkan pinggul melendut semasa plank.", "Mendarat dengan kuat dengan kaki lurus selepas melompat."], "Langkahkan kaki ke belakang dan ke dalam tanpa melompat supaya lebih mudah, dan perlahankan jika bentuk anda mula tersasar."),
    "calf_pulses": ExerciseGuide(["Berdiri tegak dan naik ke hujung jari kaki, hujung jari tangan menyentuh dinding jika anda perlukan keseimbangan.", "Melantun naik dan turun dengan denyutan kecil, hanya beberapa sentimeter.", "Pastikan tumit tidak mencecah lantai sepanjang set.", "Teruskan selama 20 saat, 3 set kesemuanya."], ["Membiarkan tumit mencecah lantai di antara denyutan.", "Membuat pergerakan terlalu besar sehingga ia tidak lagi menjadi denyutan."], "Rasa terbakar pada betis adalah biasa. Sakit yang tajam bermakna berhenti."),
    "calf_raise": ExerciseGuide(["Berdiri tegak di tepi dinding, hujung jari tangan menyentuhnya untuk keseimbangan.", "Naik perlahan ke atas hujung kaki setinggi yang boleh.", "Tahan 1 saat di atas, kemudian turunkan tumit dengan perlahan.", "Buat 15 ulangan setiap set, 3 set kesemuanya."], ["Melantun dengan pantas dan bukannya bergerak perlahan.", "Membiarkan buku lali berpusing ke luar di bahagian atas."], "Lakukannya sambil memberus gigi untuk menjadikannya tabiat harian yang mudah."),
    "cat_cow": ExerciseGuide(["Mulakan dengan merangkak, pergelangan tangan di bawah bahu, lutut di bawah pinggul.", "Tarik nafas, turunkan perut dan angkat dada serta pandangan anda (lembu).", "Hembus nafas, bulatkan belakang dan rapatkan dagu (kucing).", "Bergerak perlahan mengikut nafas selama 10 pusingan, 2 set."], ["Bergerak lebih laju daripada nafas anda.", "Hanya menggerakkan leher dan bukannya seluruh tulang belakang."], "Sesuai sebagai pergerakan pertama pada waktu pagi atau untuk menyegarkan badan selepas duduk lama."),
    "chest_stretch": ExerciseGuide(["Berdiri di ambang pintu dan letakkan satu lengan bawah pada bingkai, siku setinggi bahu.", "Langkahkan kaki di sisi yang sama ke hadapan melalui pintu.", "Condongkan dada ke hadapan sehingga anda rasa regangan di sepanjang bahagian depan bahu.", "Tahan 20 saat, tukar sisi, dan buat 2 set pada setiap sisi."], ["Melengkungkan belakang bawah untuk condong lebih jauh.", "Menjongket bahu ke arah telinga."], "Pastikan regangan lembut sahaja, dan kurangkan jika anda rasa bahu terhimpit."),
    "childs_pose": ExerciseGuide(["Melutut di lantai dengan ibu jari kaki bersentuhan dan lutut terbuka.", "Duduk dengan pinggul dilabuhkan ke atas tumit.", "Jalankan tangan ke hadapan dan letakkan dahi di atas lantai.", "Bernafas perlahan selama 30 saat dan bangun, 2 set kesemuanya."], ["Mengangkat pinggul jauh dari tumit untuk mencapai lebih jauh.", "Menahan nafas dan menegangkan bahu."], "Letakkan kusyen di antara pinggul dan tumit jika lutut anda terasa tegang."),
    "chin_tucks": ExerciseGuide(["Duduk atau berdiri tegak dan pandang lurus ke hadapan.", "Gelongsorkan dagu lurus ke belakang, seolah-olah membuat dagu berlapis.", "Tahan 3 saat, kemudian lepaskan.", "Buat 8 ulangan setiap set, 2 set kesemuanya."], ["Mengangguk kepala ke bawah dan bukannya menggelongsorkannya ke belakang.", "Menolak sekuat-kuatnya sehingga leher anda sakit."], "Buat beberapa kali setiap kali anda meletakkan telefon."),
    "cobra_stretch": ExerciseGuide(["Berbaring meniarap dengan tapak tangan rata di bawah bahu.", "Tolak lantai menjauh dan angkat dada perlahan-lahan, pinggul kekal di bawah.", "Pastikan siku sedikit bengkok dan bahu jauh daripada telinga.", "Tahan 15 saat sambil bernafas perlahan, kemudian turun dengan terkawal."], ["Menolak terlalu tinggi sehingga belakang bawah anda terhimpit.", "Menjongket bahu ke arah telinga."], "Angkat setakat yang terasa selesa sahaja; ia akan bertambah dalam dengan latihan."),
    "dead_bug": ExerciseGuide(["Berbaring telentang dengan lengan lurus ke atas dan lutut bengkok di atas pinggul.", "Tekan belakang bawah anda dengan lembut ke lantai.", "Turunkan satu lengan ke belakang kepala dan kaki yang bertentangan ke arah lantai, kemudian kembali.", "Buat 8 ulangan pada setiap sisi dan rehat, 2 set kesemuanya."], ["Membiarkan belakang bawah melengkung daripada lantai.", "Tergesa-gesa menyiapkan ulangan."], "Turunkan lengan dan kaki anda hanya setakat belakang anda masih boleh kekal rata pada lantai."),
    "dead_hang_active": ExerciseGuide(["Pegang palang dengan genggaman atas, tangan sedikit lebih luas daripada bahu.", "Bergayut dengan lengan lurus, kemudian tarik tulang belikat ke bawah dan ke belakang.", "Rapatkan kaki dan ketatkan teras, dan tahan selama 20 saat.", "Turun dengan lembut dan rehat 40 saat di antara set."], ["Membengkokkan siku seperti pull-up.", "Menjongket bahu ke arah telinga."], "Bayangkan menolak palang menjauhi anda supaya anda dapat merasai bahu bekerja."),
    "deadlift_stretch": ExerciseGuide(["Berdiri dengan kaki selebar pinggul dan lutut sedikit bengkok.", "Bongkokkan badan dari pinggul dan gelongsorkan tangan ke bawah di sepanjang paha.", "Pastikan belakang rata dan capai ke arah jari kaki sehingga hamstring anda teregang.", "Ketatkan punggung untuk berdiri semula, 12 ulangan perlahan setiap set."], ["Membulatkan belakang untuk mencapai lebih rendah.", "Mengunci lutut hingga lurus sepenuhnya."], "Bergerak perlahan; kawalan lebih penting daripada sejauh mana anda mencapai."),
    "downward_dog": ExerciseGuide(["Mulakan dengan merangkak, tangan di bawah bahu.", "Angkat pinggul tinggi supaya badan anda membentuk huruf V songsang.", "Pastikan tulang belakang panjang dan biarkan tumit turun ke arah lantai.", "Tahan 20 saat dan rehat, 2 set kesemuanya."], ["Membulatkan belakang untuk memaksa tumit turun.", "Menjongket bahu ke arah telinga."], "Bengkokkan lutut sedikit jika belakang anda membulat. Tumit anda tidak perlu mencecah lantai."),
    "dumbbell_deadlift": ExerciseGuide(["Berdiri tegak dengan sebiji dumbbell pada setiap tangan di hadapan paha.", "Lembutkan lutut dan tolak pinggul ke belakang dengan belakang yang rata.", "Gelongsorkan berat ke bawah di sepanjang paha sehingga tepat di bawah lutut.", "Ketatkan punggung untuk berdiri, buat 8 ulangan, 3 set kesemuanya."], ["Membulatkan belakang semasa berat turun.", "Mengubahnya menjadi squat dengan membengkokkan lutut terlalu banyak."], "Pilih berat yang cukup ringan supaya setiap ulangan dapat disiapkan dengan bentuk yang betul."),
    "dumbbell_row": ExerciseGuide(["Letakkan satu tangan pada bangku atau kerusi dan langkahkan kaki ke belakang.", "Pegang dumbbell pada tangan yang lain dengan belakang rata dan lengan tergantung ke bawah.", "Tarik berat ke pinggul dengan siku rapat, kemudian turunkan dengan perlahan.", "Buat 8 ulangan pada setiap sisi dan rehat, 3 set kesemuanya."], ["Memulas badan untuk mengangkat berat ke atas.", "Menjongket bahu ke arah telinga."], "Pilih berat yang cukup ringan supaya setiap ulangan dapat disiapkan dengan bentuk yang betul."),
    "evening_yoga": ExerciseGuide(["Mulakan dengan merangkak dan alirkan pergerakan kucing-lembu selama 60 saat.", "Duduk ke belakang dalam pose kanak-kanak, lengan terjulur, dan bernafas selama 60 saat.", "Tolak naik ke anjing menunduk, tumit mencapai ke arah lantai.", "Berdiri dan bongkokkan badan ke hadapan, biarkan kepala tergantung berat.", "Tarik nafas selama 4 kiraan dan hembus selama 6 kiraan dalam setiap pose."], ["Tergesa-gesa berpindah pose dan bukannya menahannya.", "Memaksa sesuatu pose sehingga sakit."], "Malapkan lampu semasa bergerak untuk membantu badan anda bertenang."),
    "farmer_carry": ExerciseGuide(["Berdiri di antara dua dumbbell atau dua beg yang berisi.", "Bengkokkan lutut, pastikan belakang rata dan angkat kedua-duanya.", "Berjalan dengan langkah kecil, bahu ke belakang dan mata ke hadapan.", "Berjalan selama 20 saat, letakkan semula dan rehat, 3 set kesemuanya."], ["Condong ke satu sisi atau membiarkan bahu membulat ke hadapan.", "Membulatkan belakang semasa mengangkat atau meletakkan berat."], "Pilih berat yang cukup ringan supaya setiap set dapat disiapkan dengan bentuk yang betul, dan pastikan kedua-dua sisi sama berat."),
    "glute_bridge": ExerciseGuide(["Berbaring telentang, lutut bengkok, tapak kaki rata dan selebar pinggul.", "Tekan melalui tumit dan angkat pinggul ke arah siling.", "Ketatkan punggung di atas selama 2 saat.", "Turun perlahan, 12 ulangan setiap set, 3 set kesemuanya."], ["Menolak melalui jari kaki dan bukannya tumit.", "Melengkungkan belakang bawah secara berlebihan di atas."], "Jika anda rasa pada punggung dan bukan pada belakang bawah, anda melakukannya dengan betul."),
    "goblet_squat": ExerciseGuide(["Pegang sebiji dumbbell atau beg galas berisi pada dada dengan kedua-dua tangan.", "Berdiri dengan kaki selebar bahu dan jari kaki dihalakan sedikit ke luar.", "Duduk di antara tumit dengan dada tegak, kemudian berdiri semula.", "Buat 8 ulangan dan rehat, 3 set kesemuanya."], ["Membiarkan lutut jatuh ke dalam.", "Membulatkan belakang dan membiarkan dada jatuh."], "Pilih berat yang cukup ringan supaya setiap ulangan dapat disiapkan dengan bentuk yang betul."),
    "hanging_knee_raise": ExerciseGuide(["Pegang palang dengan genggaman atas dan bergayut dengan lengan lurus.", "Tarik bahu ke bawah jauh daripada telinga.", "Angkat kedua-dua lutut setinggi pinggul tanpa berayun, kemudian turunkan dengan perlahan.", "Buat 5 ulangan, turun dan rehat, 3 set kesemuanya."], ["Mengayun badan untuk melambung lutut ke atas.", "Bergayut dengan bahu terangkat sehingga dekat telinga."], "Pastikan palang kukuh sebelum anda bergayut, dan turun dengan berhati-hati dan bukannya terjun."),
    "high_knees": ExerciseGuide(["Berdiri tegak dengan kaki terbuka selebar pinggul.", "Berlari di tempat dan angkat setiap lutut setinggi pinggul.", "Ayunkan lengan dan kekal ringan di atas hujung kaki.", "Teruskan selama 20 saat, 3 set kesemuanya."], ["Bersandar ke belakang semasa lutut naik.", "Menghentak lantai dengan tapak kaki rata."], "Perlahankan menjadi berjalan di tempat dengan lutut tinggi jika anda semput."),
    "hiit_workout": ExerciseGuide(["Panaskan badan selama 3 minit dengan berjalan di tempat dan pusingan lengan.", "Buat burpee, mountain climber dan jump squat, 45 saat setiap satu.", "Rehat 15 saat di antara pergerakan dan bernafas dalam-dalam.", "Siapkan 4 pusingan, kemudian berjalan perlahan sehingga nafas anda reda."], ["Membiarkan bentuk tersasar demi kelajuan.", "Menahan nafas semasa selang yang berat."], "Ikut rentak sendiri; menyiapkan kesemua 4 pusingan lebih baik daripada permulaan yang laju."),
    "hip_flexor_stretch": ExerciseGuide(["Melutut pada satu lutut dengan kaki yang lain rata di hadapan anda.", "Selitkan pinggul sedikit ke bawah dan ketatkan otot punggung di sebelah kaki belakang.", "Anjak ke hadapan dengan lembut sehingga anda rasa regangan di bahagian depan pinggul.", "Tahan 30 saat sambil bernafas perlahan, kemudian tukar sisi."], ["Melengkungkan belakang bawah dan bukannya menyelitkan pinggul.", "Membiarkan lutut depan melepasi jari kaki."], "Letakkan tuala yang dilipat di bawah lutut supaya lebih selesa."),
    "inversion_hang": ExerciseGuide(["Songsangkan badan hanya dengan pengawasan orang dewasa dan pada peralatan yang stabil dan sudah diperiksa.", "Kunci buku lali anda dengan selamat dan mulakan pada kecondongan sedikit, bukan terus songsang sepenuhnya.", "Rehatkan lengan dan bernafas perlahan sehingga 1 minit.", "Kembali tegak dengan perlahan dan duduk seketika sebelum berdiri.", "Berhenti serta-merta jika anda rasa pening, tekanan pada kepala atau sebarang kesakitan."], ["Terus songsang sepenuhnya dalam sesi pertama anda.", "Berdiri dengan pantas sejurus selepas songsang."], "Sesi yang pendek dan lembut sudah memadai; tidak perlu bergayut lebih lama."),
    "jump_squats": ExerciseGuide(["Berdiri dengan kaki terbuka selebar bahu dan dada tegak.", "Duduk ke belakang dalam squat sehingga paha anda hampir selari dengan lantai.", "Tolak kuat melalui kaki, lompat lurus ke atas dan mendarat dengan lembut semula dalam squat.", "Buat 8 lompatan, rehat, dan ulang untuk 3 set kesemuanya."], ["Membiarkan lutut jatuh ke dalam semasa mendarat.", "Mendarat dengan kaki yang kaku dan lurus."], "Mendarat setenang mungkin, dan hentikan set apabila pendaratan anda mula kuat bunyinya."),
    "jumping": ExerciseGuide(["Berdiri dengan kaki selebar pinggul dan lengan santai di sisi.", "Bengkokkan lutut, ayunkan lengan dan lompat lurus ke atas.", "Mendarat dengan lembut di atas hujung kaki dengan lutut sedikit bengkok.", "Buat 20 lompatan, rehat 30 saat, dan ulang untuk 3 set."], ["Mendarat dengan kaki yang kaku pada tumit.", "Membiarkan lutut jatuh ke dalam semasa mendarat."], "Pendaratan yang senyap bermakna kawalan yang baik, jadi cuba mendarat seperti kucing."),
    "knee_circles": ExerciseGuide(["Berdiri dengan kaki rapat dan bengkokkan lutut sedikit.", "Letakkan tangan pada lutut.", "Buat pusingan kecil dan perlahan dengan lutut selama 15 saat ke satu arah.", "Tukar arah dan pusing 15 saat ke arah yang satu lagi."], ["Membuat pusingan besar yang memulas lutut.", "Membuat semua pusingan ke satu arah sahaja."], "Gunakannya sebagai pemanasan badan sebelum melompat atau berlari."),
    "legs_up_wall": ExerciseGuide(["Duduk mengiring bersebelahan dinding dengan satu pinggul menyentuhnya.", "Ayunkan kaki ke atas dinding semasa anda berbaring ke belakang di lantai.", "Biarkan lengan berehat di sisi dan rehatkan kaki pada dinding.", "Kekal selama 3 minit sambil bernafas perlahan."], ["Mengangkat belakang bawah daripada lantai.", "Mengunci lutut dengan kuat dan menegangkan kaki."], "Alihkan pinggul sedikit menjauhi dinding jika bahagian belakang kaki anda terasa tegang."),
    "low_lunge_arch": ExerciseGuide(["Langkahkan satu kaki ke hadapan dan turunkan lutut belakang ke lantai.", "Anjakkan pinggul ke hadapan sehingga anda rasa regangan di bahagian depan pinggul belakang.", "Angkat kedua-dua lengan ke atas dan angkat dada dalam lengkungan yang lembut.", "Tahan 20 saat, tukar kaki, dan buat 2 set pada setiap sisi."], ["Membiarkan lutut depan maju jauh melepasi jari kaki.", "Melengkung hanya dari belakang bawah."], "Letakkan tuala yang dilipat di bawah lutut belakang, dan pastikan lengkungan kecil sahaja."),
    "lunges": ExerciseGuide(["Berdiri tegak dengan kaki terbuka selebar pinggul.", "Ambil langkah besar ke hadapan dan turun sehingga kedua-dua lutut bengkok kira-kira 90 darjah.", "Tolak melalui tumit depan untuk melangkah balik ke posisi mula.", "Buat 8 ulangan pada setiap kaki dan rehat, 3 set kesemuanya."], ["Membiarkan lutut depan jatuh ke dalam.", "Mencondongkan dada jauh ke hadapan di atas kaki depan."], "Ambil langkah yang lebih pendek atau pegang kerusi untuk keseimbangan sehingga pergerakan terasa stabil."),
    "masai_jumps": ExerciseGuide(["Berdiri tegak dengan lengan di sisi atau menjulur ke atas.", "Buat lompatan kecil yang melantun dan pastikan badan tegak sepanjang masa.", "Mendarat dengan lembut di atas hujung kaki, lutut sedikit bengkok.", "Teruskan selama 20 saat, 3 set kesemuanya."], ["Mendarat dengan kuat di atas tumit.", "Membongkok ke hadapan apabila anda letih."], "Berhenti jika lutut atau tulang kering anda sakit, dan rehat sebelum mencuba lagi."),
    "morning_stretch": ExerciseGuide(["Berdiri tegak dan pusing leher perlahan-lahan, 5 pusingan ke setiap arah.", "Julurkan kedua-dua lengan ke atas kepala, kaitkan jari dan regangkan ke atas selama 30 saat.", "Bongkokkan badan ke hadapan dari pinggul dan biarkan tangan tergantung ke arah jari kaki.", "Melangkah ke posisi lunge, tahan 30 saat, kemudian tukar kaki.", "Bernafas perlahan melalui hidung dan jangan melantun semasa meregang."], ["Melantun untuk masuk lebih dalam dan bukannya menahan dengan tenang.", "Menahan nafas semasa menahan posisi."], "Meregang sebelum menyemak telefon menjadikan tabiat ini lebih cepat melekat."),
    "mountain_pose": ExerciseGuide(["Berdiri dengan kaki rapat dan berat badan sekata pada kedua-dua kaki.", "Julurkan kedua-dua lengan lurus ke atas kepala dengan tapak tangan saling berhadapan.", "Naik ke hujung jari kaki dan regangkan ke atas melalui hujung jari.", "Tahan 20 saat dan turun perlahan-lahan, 2 set kesemuanya."], ["Membuka tulang rusuk dan melengkungkan belakang bawah.", "Menjongket bahu ke arah telinga."], "Tetapkan pandangan pada satu titik di hadapan anda, atau kekalkan tumit di lantai jika anda goyah."),
    "neck_stretches": ExerciseGuide(["Duduk atau berdiri tegak dengan bahu santai dan turun.", "Condongkan telinga perlahan-lahan ke arah bahu dan tahan 30 saat setiap sisi.", "Turunkan dagu ke arah dada dan tahan selama 30 saat.", "Angkat pandangan dengan lembut selama 30 saat tanpa mendongak kepala ke belakang."], ["Menarik kepala dengan kuat menggunakan tangan.", "Mengangkat bahu untuk bertemu telinga."], "Lakukan ini selepas sesi belajar yang panjang untuk melepaskan ketegangan."),
    "overhead_press": ExerciseGuide(["Berdiri tegak sambil memegang berat ringan atau botol air setinggi bahu.", "Ketatkan teras dan tolak kedua-dua lengan lurus ke atas kepala.", "Akhiri dengan lengan di tepi telinga, kemudian turunkan perlahan ke bahu.", "Hembus nafas semasa menolak, tarik nafas semasa menurunkan, 10 ulangan setiap set."], ["Melengkungkan belakang bawah semasa menolak.", "Menggunakan berat yang terlalu berat untuk dikawal."], "Mulakan dengan berat badan sahaja dan tambah berat ringan apabila bentuk anda terasa mudah."),
    "pelvic_shift": ExerciseGuide(["Berbaring telentang dengan lutut bengkok dan tapak kaki rata di lantai.", "Selitkan tulang ekor dan angkat tulang belakang dari lantai bermula dari bawah.", "Jeda di atas, kemudian turun perlahan-lahan, satu ruas tulang pada satu masa.", "Buat 10 ulangan perlahan dan rehat, 2 set kesemuanya."], ["Menolak pinggul ke atas dengan pantas dalam satu blok.", "Melengkungkan belakang bawah di atas."], "Bergerak cukup perlahan untuk merasai setiap bahagian belakang anda menyentuh lantai."),
    "pilates_core": ExerciseGuide(["Tahan forearm plank selama 1 minit, badan dalam satu garisan lurus.", "Berbaring telentang untuk dead bug, turunkan lengan dan kaki yang bertentangan dengan perlahan.", "Beralih ke bird dog dalam posisi merangkak, julurkan lengan dan kaki yang bertentangan.", "Akhiri dengan 1 minit glute bridge dan 1 minit angkat kaki.", "Hembus nafas setiap kali anda mengetatkan teras."], ["Membiarkan pinggul melendut semasa plank.", "Melengkungkan belakang bawah daripada lantai semasa dead bug."], "Perlahan dan terkawal lebih baik daripada laju; setiap ulangan yang bersih membina kekuatan sebenar."),
    "pilates_roll_over": ExerciseGuide(["Berbaring telentang dengan lengan di sisi dan kaki lurus ke atas.", "Tekan lengan ke lantai dan angkat pinggul untuk menggulingkan kaki ke atas kepala.", "Berhenti apabila kaki anda selari dengan lantai di belakang kepala.", "Gulung turun perlahan-lahan, buat 5 ulangan dan rehat, 2 set kesemuanya."], ["Mengayun kaki ke atas dengan momentum.", "Bergolek ke atas leher dan bukannya bahu."], "Pastikan berat anda pada bahu dan tidak pernah pada leher, dan bengkokkan lutut untuk menjadikannya lebih mudah."),
    "plank": ExerciseGuide(["Letakkan lengan bawah di atas lantai, siku di bawah bahu.", "Langkahkan kaki ke belakang supaya badan anda membentuk satu garisan lurus.", "Ketatkan punggung, tarik pusat ke dalam dan tahan 30 saat.", "Rehat 30 saat dan ulang untuk 3 set."], ["Membiarkan pinggul melendut ke arah lantai.", "Menjongketkan pinggul terlalu tinggi."], "Tambah 5 saat setiap minggu apabila ia menjadi lebih mudah."),
    "pogo_jumps": ExerciseGuide(["Berdiri tegak dengan kaki terbuka selebar pinggul dan tangan di pinggang.", "Melantun di atas hujung kaki dengan lutut hampir lurus.", "Pastikan setiap sentuhan dengan tanah singkat dan pantas, seperti tongkat pogo.", "Teruskan selama 20 saat, 3 set kesemuanya."], ["Membengkokkan lutut dalam-dalam pada setiap lantunan.", "Membiarkan tumit menghentam lantai."], "Lompat di permukaan yang keras dan rata, dan berhenti jika tulang kering atau buku lali anda sakit."),
    "posture_check": ExerciseGuide(["Tetapkan peringatan setiap jam untuk menyemak cara anda duduk atau berdiri.", "Susun telinga di atas bahu dan bahu di atas pinggul.", "Pusingkan bahu ke belakang dan ke bawah, biarkan dada terbuka dengan lembut.", "Bayangkan seutas tali menarik puncak kepala anda ke atas, kemudian bernafas."], ["Membetulkan secara berlebihan dengan belakang yang kaku dan melengkung.", "Menunduk melihat telefon dengan kepala terdorong ke hadapan."], "Naikkan skrin anda setinggi mata dan postur yang baik akan menjadi automatik."),
    "pre_sleep_routine": ExerciseGuide(["Mulakan 30 minit sebelum tidur: malapkan lampu dan simpan skrin.", "Baca buku atau dengar muzik yang tenang selama 15 minit.", "Buat regangan lembut selama 5 minit di atas katil atau di lantai.", "Tarik nafas selama 4 saat dan hembus selama 6 saat, 10 pusingan."], ["Menatal telefon hanya untuk seminit lagi.", "Mengubah waktu tidur anda terlalu banyak dari malam ke malam."], "Waktu yang sama dan langkah yang sama setiap malam menjadikan tidur lebih mudah."),
    "pull_ups": ExerciseGuide(["Pegang palang dengan genggaman atas, tangan sedikit lebih luas daripada bahu.", "Mulakan dari posisi bergayut dengan lengan lurus dan tarik tulang belikat ke bawah.", "Tarik sehingga dagu melepasi palang, kemudian turunkan diri perlahan-lahan.", "Buat 2 ulangan, turun dan rehat, 3 set kesemuanya."], ["Menendang dan mengayun untuk melepasi palang.", "Jatuh dengan pantas dan bukannya turun dengan terkawal."], "Lilitkan band di bawah kaki atau lompat ke atas dan turun perlahan-lahan, dan pastikan palang kukuh."),
    "puppy_pose": ExerciseGuide(["Mulakan dengan merangkak dengan pinggul tepat di atas lutut.", "Jalankan tangan ke hadapan dan kekalkan pinggul di tempatnya.", "Biarkan dada dan dahi tenggelam ke arah lantai.", "Tahan 20 saat dan naik semula, 2 set kesemuanya."], ["Membiarkan pinggul tergelincir ke belakang ke arah tumit.", "Membengkokkan siku dan merehatkannya di atas lantai."], "Rehatkan dahi pada kusyen jika regangan pada bahu terasa terlalu kuat."),
    "push_ups": ExerciseGuide(["Letakkan tangan di atas lantai sedikit lebih luas daripada bahu.", "Langkahkan kaki ke belakang supaya badan anda membentuk satu garisan lurus.", "Bengkokkan siku untuk menurunkan dada ke lantai, kemudian tolak naik semula.", "Buat 5 ulangan dan rehat, 3 set kesemuanya."], ["Membiarkan pinggul melendut ke arah lantai.", "Membuka siku lurus ke sisi."], "Turun ke lutut atau letakkan tangan pada bangku untuk menjadikannya lebih mudah."),
    "scapular_pull": ExerciseGuide(["Pegang palang dengan genggaman atas, tangan sedikit lebih luas daripada bahu.", "Bergayut dengan lengan lurus dan biarkan bahu naik ke arah telinga.", "Tarik tulang belikat ke bawah supaya badan anda naik sedikit, siku kekal lurus.", "Tahan sesaat dan lepaskan, buat 5 ulangan, 3 set kesemuanya."], ["Membengkokkan siku untuk menarik lebih tinggi.", "Mengayun kaki untuk membantu."], "Pastikan palang kukuh, dan letakkan kaki di atas kotak jika bergayut penuh terlalu sukar."),
    "scapular_retraction": ExerciseGuide(["Duduk atau berdiri tegak dengan lengan santai di sisi.", "Tarik tulang belikat ke belakang dan ke bawah, seolah-olah menyelitkannya ke dalam poket belakang.", "Tahan kepitan itu selama satu nafas yang perlahan, kemudian lepaskan.", "Buat 10 ulangan dan rehat, 2 set kesemuanya."], ["Mengangkat bahu semasa mengepit.", "Menolak tulang rusuk ke hadapan dan melengkungkan belakang."], "Pastikan dagu sama aras dan leher santai sepanjang masa."),
    "seated_forward_fold": ExerciseGuide(["Duduk di lantai dengan kaki lurus dan jari kaki menghala ke atas.", "Duduk tegak dan julurkan kedua-dua lengan ke atas kepala.", "Bongkokkan badan ke hadapan dari pinggul dan capai tulang kering atau kaki anda.", "Tahan 20 saat dan duduk tegak semula, 2 set kesemuanya."], ["Membulatkan belakang atas untuk mencapai jari kaki.", "Melantun untuk masuk lebih dalam ke dalam regangan."], "Bengkokkan lutut sedikit atau duduk di atas tuala yang dilipat jika belakang bawah anda membulat."),
    "shoulder_rolls": ExerciseGuide(["Berdiri tegak dengan lengan tergantung longgar di sisi.", "Putar bahu ke hadapan dalam bulatan besar sebanyak 15 kali.", "Pusing ke belakang 15 kali sambil merapatkan tulang belikat.", "Kaitkan tangan di belakang badan dan buka dada selama 20 saat."], ["Membuat bulatan kecil yang tergesa-gesa.", "Mengangkat bahu sambil menahan nafas."], "Satu set pantas di antara kelas atau sesi belajar memastikan bahu anda terbuka."),
    "side_plank": ExerciseGuide(["Berbaring mengiring dengan lengan bawah di atas lantai, siku di bawah bahu.", "Susun kaki anda dan angkat pinggul dari lantai.", "Pastikan badan dalam satu garisan lurus dari kepala ke tumit.", "Tahan 15 saat, tukar sisi, dan buat 2 set pada setiap sisi."], ["Membiarkan pinggul menurun ke arah lantai.", "Menggolekkan dada ke hadapan ke arah lantai."], "Kekalkan lutut bawah di atas lantai untuk menjadikannya lebih mudah."),
    "single_leg_calf_raise": ExerciseGuide(["Berdiri di tepi anak tangga pada hujung satu kaki dan berpegang pada dinding atau palang.", "Turunkan tumit perlahan-lahan di bawah aras anak tangga.", "Naik setinggi mungkin ke hujung jari kaki dan jeda sesaat.", "Buat 8 ulangan pada setiap kaki dan rehat, 3 set kesemuanya."], ["Melantun keluar dari bawah dan bukannya bergerak perlahan.", "Membengkokkan lutut untuk membantu betis."], "Mulakan dengan berat badan sahaja, dan jika anda menambah dumbbell atau beg galas, pilih berat yang cukup ringan supaya setiap ulangan dapat disiapkan dengan bentuk yang betul."),
    "single_leg_hops": ExerciseGuide(["Berdiri pada satu kaki dengan kaki yang satu lagi diangkat ke belakang.", "Buat lompatan kecil di tempat, mendarat di atas hujung kaki.", "Pastikan pinggul sama rata dan lutut kaki yang berdiri sedikit bengkok.", "Buat 8 lompatan, tukar kaki, dan buat 2 set pada setiap sisi."], ["Membiarkan lutut kaki yang melompat jatuh ke dalam.", "Melompat terlalu tinggi sehingga hilang keseimbangan."], "Kekal dekat dengan dinding yang boleh anda sentuh, dan pastikan lompatan rendah sehingga keseimbangan anda terasa mantap."),
    "skipping_rope": ExerciseGuide(["Pegang pemegang setinggi pinggul, siku rapat dengan sisi badan.", "Pusingkan tali dengan pergelangan tangan, bukan seluruh lengan.", "Lompat setinggi yang cukup untuk melepasi tali, mendarat di atas hujung kaki.", "Lompat tali selama 5 minit, rehat 1 minit, dan ulang untuk 3 set."], ["Melompat terlalu tinggi dan cepat letih.", "Mendarat dengan tapak kaki rata di atas tumit."], "Tersandung adalah biasa; mulakan semula sahaja dan kekalkan rentak."),
    "spinal_twist": ExerciseGuide(["Berbaring telentang dengan lengan terbuka ke sisi.", "Bengkokkan satu lutut dan bawa menyilang badan ke arah lantai.", "Pastikan kedua-dua bahu di atas lantai dan pandang ke sisi yang bertentangan.", "Tahan 20 saat, tukar sisi, dan buat 2 set pada setiap sisi."], ["Membiarkan bahu sebelah yang bertentangan terangkat daripada lantai.", "Memaksa lutut ke bawah menggunakan tangan."], "Rehatkan lutut pada kusyen jika ia tidak sampai ke lantai."),
    "sprint_intervals": ExerciseGuide(["Panaskan badan dengan berjoging perlahan selama 5 minit dan ayunan kaki.", "Pecut dengan usaha penuh selama 30 saat sambil mengayun lengan.", "Berjalan atau berjoging perlahan selama 90 saat untuk pulih.", "Ulang sehingga 3 pecutan, kemudian sejukkan badan dengan berjalan selama 5 minit."], ["Memecut tanpa memanaskan badan dahulu.", "Bersandar ke belakang dan melangkah terlalu luas dan bukannya menolak ke hadapan."], "Pilih permukaan yang rata dan selamat, dan berikan segala-galanya hanya apabila anda rasa segar."),
    "squats": ExerciseGuide(["Berdiri dengan kaki selebar bahu, jari kaki dihalakan sedikit ke luar.", "Tolak pinggul ke belakang dan turun sehingga paha selari dengan lantai.", "Pastikan dada tegak dan lutut sejajar dengan jari kaki.", "Tekan melalui tumit untuk berdiri, hembus nafas semasa naik."], ["Mengangkat tumit daripada lantai.", "Membulatkan belakang di bawah."], "Buat set pertama anda di hadapan cermin untuk menyemak bentuk anda."),
    "standing_side_stretch": ExerciseGuide(["Berdiri tegak dengan kaki terbuka selebar pinggul.", "Julurkan kedua-dua lengan ke atas kepala dan pegang satu pergelangan tangan dengan tangan yang lain.", "Condong perlahan-lahan ke satu sisi dan tekan kedua-dua kaki ke lantai.", "Tahan 15 saat, tukar sisi, dan buat 2 set pada setiap sisi."], ["Condong ke hadapan atau memutar dan bukannya membengkok lurus ke sisi.", "Menolak pinggul jauh ke sisi."], "Bayangkan anda berdiri di antara dua dinding, jadi anda hanya boleh bergerak ke sisi."),
    "step_ups": ExerciseGuide(["Berdiri di hadapan anak tangga atau bangku rendah yang kukuh.", "Letakkan seluruh satu kaki di atas anak tangga dan tolak naik sehingga anda berdiri tegak.", "Turunkan kaki yang satu lagi ke lantai dengan perlahan.", "Buat 8 ulangan pada setiap kaki dan rehat, 3 set kesemuanya."], ["Menolak dengan kuat menggunakan kaki yang berada di lantai.", "Jatuh dengan pantas dan bukannya turun dengan terkawal."], "Gunakan anak tangga yang tidak boleh tergelincir atau terbalik, dan mulakan dari yang rendah sebelum naik lebih tinggi."),
    "superman": ExerciseGuide(["Berbaring meniarap dengan lengan menjulur ke hadapan.", "Angkat lengan dan kaki sedikit dari lantai.", "Pastikan leher panjang, pandang ke lantai dan tahan 2 saat.", "Turun perlahan, 8 ulangan setiap set, 2 set kesemuanya."], ["Memaksa dada dan kaki naik setinggi yang boleh.", "Mendongak kepala dan memicit leher."], "Angkatan kecil sudah memadai. Jika belakang bawah anda terhimpit, angkat lebih rendah."),
    "swimming_basketball": ExerciseGuide(["Panaskan badan selama 5 minit dengan berenang perlahan atau mendrib ringan.", "Berenang atau bermain sekurang-kurangnya 30 minit pada kadar yang stabil.", "Capai sepenuhnya pada setiap kayuhan, tembakan atau lantunan semula.", "Sejukkan badan dengan 5 minit pergerakan perlahan dan regangan."], ["Melangkau pemanasan badan dan terus bermula pada kelajuan penuh.", "Terlupa minum air semasa bermain."], "Bawa seorang kawan; sukan lebih mudah diteruskan apabila dilakukan bersama."),
    "table_top": ExerciseGuide(["Duduk dengan lutut bengkok, tapak kaki rata dan tangan di atas lantai di belakang pinggul.", "Halakan jari ke arah kaki dan tekan pada tangan dan kaki.", "Angkat pinggul sehingga badan anda rata dari lutut ke bahu.", "Tahan 15 saat dan turun, 2 set kesemuanya."], ["Membiarkan pinggul melendut di tengah.", "Mendongak kepala ke belakang sehingga leher tegang."], "Halakan jari ke sisi jika pergelangan tangan anda terasa sakit."),
    "thoracic_extension": ExerciseGuide(["Duduk di atas kerusi yang kukuh dengan bahagian atas sandarannya tepat di bawah tulang belikat.", "Letakkan tangan di belakang kepala dan pastikan siku terbuka luas.", "Sandarkan belakang atas perlahan-lahan pada sandaran kerusi dan pandang ke atas.", "Naik semula, buat 8 ulangan dan rehat, 2 set kesemuanya."], ["Membengkok dari belakang bawah dan bukannya belakang atas.", "Menarik kepala ke hadapan dengan tangan."], "Gunakan kerusi yang tidak boleh bergolek atau terbalik, dan pastikan kaki rata di atas lantai."),
    "toe_touch": ExerciseGuide(["Berdiri dengan kaki selebar pinggul dan lutut lembut.", "Bongkokkan badan ke hadapan dari pinggul dan biarkan tangan mencapai ke arah jari kaki.", "Kekal diam selama 20 saat dan bernafas perlahan.", "Gulung naik perlahan-lahan, rehat, dan ulang sekali lagi."], ["Melantun untuk mencapai lebih jauh.", "Mengunci lutut hingga lurus."], "Jika anda tidak sampai ke jari kaki, berhenti pada tulang kering. Ia masih berkesan."),
    "tuck_jumps": ExerciseGuide(["Berdiri tegak dengan kaki terbuka selebar pinggul.", "Turun pantas ke suku squat dan lompat setinggi yang boleh.", "Tarik kedua-dua lutut ke arah dada di puncak, kemudian mendarat dengan lembut pada lutut yang bengkok.", "Buat 6 lompatan, rehat, dan ulang untuk 3 set kesemuanya."], ["Membongkokkan dada ke lutut dan bukannya mengangkat lutut.", "Mendarat dengan kuat dengan kaki lurus."], "Seimbangkan semula badan di antara lompatan, dan pastikan anda ada ruang kosong dan lantai yang tidak licin."),
    "upward_salute": ExerciseGuide(["Berdiri dengan kaki rapat dan lengan di sisi.", "Tarik nafas dan julurkan kedua-dua lengan ke atas kepala.", "Pastikan tulang rusuk turun dan bahu jauh daripada telinga.", "Tahan 15 saat sambil bernafas perlahan, kemudian turunkan lengan. 2 set kesemuanya."], ["Bersandar ke belakang dan melengkungkan belakang bawah.", "Membiarkan tulang rusuk menonjol ke hadapan."], "Capai ke atas, bukan ke belakang. Pastikan badan tersusun lurus di atas kaki."),
    "wall_angels": ExerciseGuide(["Berdiri dengan belakang bersandar pada dinding, kaki sedikit di hadapan anda.", "Letakkan lengan pada dinding dengan siku bengkok, seperti tiang gol.", "Pastikan tulang rusuk turun dan gelongsorkan lengan perlahan-lahan ke atas, kemudian turun semula.", "Buat 8 ulangan perlahan setiap set, 2 set kesemuanya."], ["Membiarkan tulang rusuk menonjol dan belakang bawah melengkung.", "Membiarkan lengan terlepas daripada dinding."], "Naik hanya setakat lengan anda masih boleh melekat pada dinding. Ia menjadi lebih mudah dengan latihan."),
    "wall_dog": ExerciseGuide(["Berdiri menghadap dinding, kira-kira sepanjang satu kaki jauhnya.", "Letakkan tangan pada dinding setinggi pinggul.", "Bongkokkan badan ke belakang dari pinggul sehingga lengan lurus dan tulang belakang panjang.", "Tahan 20 saat sambil bernafas perlahan, 2 set kesemuanya."], ["Membulatkan belakang atas.", "Membengkokkan siku dan bersandar pada dinding."], "Rehat yang baik di meja anda apabila anda tidak boleh turun ke lantai."),
    "wall_sit": ExerciseGuide(["Berdiri dengan belakang bersandar pada dinding dan kaki satu langkah di hadapan anda.", "Gelongsor turun sehingga paha anda sama aras dengan lantai.", "Pastikan lutut di atas buku lali dan seluruh belakang pada dinding.", "Tahan 20 saat dan berdiri, 3 set kesemuanya."], ["Merehatkan tangan di atas paha.", "Membiarkan lutut bergerak ke hadapan melepasi jari kaki."], "Duduk sedikit lebih tinggi jika lutut anda tidak selesa, dan turun lebih rendah apabila anda bertambah kuat."),
    "wall_stand": ExerciseGuide(["Berdiri dengan tumit pada dinding, kaki selebar pinggul.", "Sentuhkan punggung, tulang belikat dan belakang kepala anda pada dinding.", "Rapatkan dagu sedikit dan biarkan lengan santai di sisi.", "Tahan selama 5 minit sambil bernafas dengan tenang melalui hidung."], ["Melengkungkan belakang bawah jauh dari dinding.", "Menolak dagu ke atas dan bukannya mengekalkannya sama aras."], "Perhatikan bagaimana rasanya, kemudian cuba bawa kesan itu ke dalam hari anda."),
  },
  "ja": {
    "band_pull_apart": ExerciseGuide(["背すじを伸ばして立ち、腕をまっすぐにして肩の高さでバンドを持ちます。", "肩甲骨を寄せながら、バンドを左右に引き離します。", "バンドを胸につけたら、ゆっくり戻します。", "12回行って休憩します。合計2セットです。"], ["肩を耳のほうへすくめてしまう。", "バンドが勢いよく戻ってしまい、ゆっくり戻していない。"], "バンドは、1回ごとにきれいなフォームで最後までできる軽さを選び、使う前に破れがないか確認しましょう。"),
    "bar_hanging": ExerciseGuide(["鉄棒を順手で、肩幅に手を開いて握ります。", "足を浮かせて、体をまっすぐ、力を抜いてぶら下げます。", "肩を軽く引き締めたまま、30秒間ゆっくり呼吸します。", "そっと降りて30〜60秒休み、合計3セット行います。"], ["ぶら下がっている間に脚を振ったり蹴ったりしてしまう。", "そっと降りずに、鉄棒から飛び降りてしまう。"], "短い時間から始めて、毎週数秒ずつ増やしましょう。"),
    "bird_dog": ExerciseGuide(["四つんばいになり、手は肩の真下、ひざは股関節の真下に置きます。", "片腕を前へ、反対側の脚をまっすぐ後ろへ伸ばします。", "腰の高さをそろえたまま2秒キープして戻します。", "8回行って左右を入れ替え、左右とも2セットずつ行います。"], ["脚を上げるときに腰が反って落ちてしまう。", "脚を高く上げようとして骨盤が開いてしまう。"], "腰の上にコップ一杯の水がのっていて、こぼしてはいけないと想像しましょう。"),
    "bow_pose": ExerciseGuide(["うつ伏せになり、かかとがお尻に近づくようにひざを曲げます。", "後ろに手を伸ばして、両足首をつかみます。", "足を手に向かって蹴り出すようにして、胸と太ももを持ち上げます。", "10秒キープしてゆっくり下ろします。合計2セットです。"], ["ひざが腰幅より広がってしまう。", "頭を後ろに倒して首を痛めてしまう。"], "無理のない高さまでにして、腰が痛いときはこの種目を休みましょう。"),
    "broad_jumps": ExerciseGuide(["足を腰幅に開き、つま先をラインの手前にそろえて立ちます。", "腕を後ろに振り、ひざを曲げて、お尻を後ろに引きます。", "腕を前に振って思い切り遠くへ跳び、両足で着地します。", "1秒着地を止め、歩いて戻って5回跳びます。合計3セットです。"], ["着地で前や後ろに倒れてしまう。", "ひざを伸ばしきったまま着地してしまう。"], "すべりにくい場所で跳び、着地をピタッと止められるまでは距離を短めにしましょう。"),
    "burpees": ExerciseGuide(["背すじを伸ばして立ち、しゃがんで両手を床につきます。", "足を後ろへ跳ばして、まっすぐなプランクの姿勢になります。", "足を手のほうへ跳んで戻します。", "まっすぐ上に跳びます。5回行って休憩し、合計3セットです。"], ["プランクで腰が落ちてしまう。", "ジャンプのあと、脚を伸ばしたまま強く着地してしまう。"], "楽にしたいときは、跳ばずに足を後ろへ歩かせて戻し、フォームが崩れたらペースを落としましょう。"),
    "calf_pulses": ExerciseGuide(["背すじを伸ばしてつま先立ちになります。バランスが必要なら指先を壁にそえます。", "数センチだけ、小さく上下に弾みます。", "セットの間ずっと、かかとを床から浮かせたままにします。", "20秒続けます。合計3セットです。"], ["弾む合間にかかとが床についてしまう。", "動きが大きすぎて、パルスにならなくなってしまう。"], "ふくらはぎが熱くなるのは普通です。鋭い痛みがあれば中止しましょう。"),
    "calf_raise": ExerciseGuide(["壁のそばに立ち、バランスのために指先を壁にそえます。", "足の指のつけ根で、ゆっくりできるだけ高く伸び上がります。", "上で1秒止め、かかとをゆっくり下ろします。", "1セット15回、合計3セット行います。"], ["ゆっくり動かず、はずみをつけて素早く動かしてしまう。", "上で足首が外側に倒れてしまう。"], "歯みがきをしながら行うと、毎日の習慣にしやすいです。"),
    "cat_cow": ExerciseGuide(["四つんばいになり、手首は肩の真下、ひざは股関節の真下に置きます。", "息を吸いながらお腹を落とし、胸と視線を上げます（カウ）。", "息を吐きながら背中を丸め、あごを引きます（キャット）。", "呼吸に合わせてゆっくり10往復します。2セット行います。"], ["呼吸より速く動いてしまう。", "背骨全体ではなく、首だけを動かしてしまう。"], "朝いちばんの動きや、座ったあとのリセットにぴったりです。"),
    "chest_stretch": ExerciseGuide(["ドア口に立ち、片方の前腕を枠にのせます。ひじは肩の高さです。", "同じ側の足を、ドアの向こうへ一歩踏み出します。", "肩の前側が伸びるのを感じるまで、胸を前に傾けます。", "20秒キープし、反対側も行います。左右それぞれ2セットです。"], ["もっと傾けようとして腰を反らしてしまう。", "肩を耳のほうへすくめてしまう。"], "ストレッチはやさしく行い、肩に挟まる感じがあれば弱めましょう。"),
    "childs_pose": ExerciseGuide(["床にひざをつき、足の親指をつけて、ひざは開きます。", "お尻をかかとの上に引いて座ります。", "手を前に歩かせ、おでこを床につけて休みます。", "30秒ゆっくり呼吸して起き上がります。合計2セットです。"], ["もっと先へ伸ばそうとして、お尻がかかとから大きく浮いてしまう。", "息を止めて肩に力が入ってしまう。"], "ひざがつらいときは、お尻とかかとの間にクッションをはさみましょう。"),
    "chin_tucks": ExerciseGuide(["背すじを伸ばして座るか立ち、まっすぐ前を見ます。", "二重あごをつくるように、あごをまっすぐ後ろへ引きます。", "3秒キープして力をぬきます。", "1セット8回、合計2セット行います。"], ["頭を後ろに引かず、下にうなずいてしまう。", "首が痛くなるほど強く押し込んでしまう。"], "スマホを置くたびに、数回行いましょう。"),
    "cobra_stretch": ExerciseGuide(["うつ伏せになり、手を肩の下で床につけます。", "床を押して、ゆっくり胸を持ち上げます。腰は床につけたままです。", "ひじは軽く曲げ、肩は耳から遠ざけます。", "ゆっくり呼吸しながら15秒キープし、コントロールしながら下ります。"], ["腰がつまるほど高く上がってしまう。", "肩を耳のほうへすくめてしまう。"], "無理のない高さまでにしましょう。練習で少しずつ深くなります。"),
    "dead_bug": ExerciseGuide(["仰向けになり、腕を真上に伸ばし、ひざを股関節の真上で曲げます。", "腰をやさしく床に押しつけます。", "片腕を頭の上へ、反対側の脚を床へ向けて下ろし、元に戻します。", "左右8回ずつ行って休憩します。合計2セットです。"], ["腰が床から浮いて反ってしまう。", "急いで回数をこなしてしまう。"], "腕と脚は、腰を床につけたままでいられる範囲までだけ下ろしましょう。"),
    "dead_hang_active": ExerciseGuide(["鉄棒を順手で、肩幅より少し広く握ります。", "腕をまっすぐにしてぶら下がり、肩甲骨を下げて後ろへ寄せます。", "脚をそろえて体幹に力を入れ、20秒キープします。", "そっと降りて、セットの間に40秒休みます。"], ["懸垂のようにひじを曲げてしまう。", "肩を耳まですくめてしまう。"], "鉄棒を自分から遠くへ押すイメージにすると、肩が働くのを感じられます。"),
    "deadlift_stretch": ExerciseGuide(["足を腰幅に開き、ひざを軽く曲げて立ちます。", "股関節から体を折り、手を太ももにそって下ろします。", "背中は平らなまま、ハムストリングが伸びるところまでつま先へ手を伸ばします。", "お尻に力を入れて立ち上がります。1セット12回、ゆっくり行います。"], ["もっと下まで届かせようとして背中を丸めてしまう。", "ひざを完全に伸ばしきってしまう。"], "ゆっくり動きましょう。どこまで届くかより、コントロールが大切です。"),
    "downward_dog": ExerciseGuide(["四つんばいになり、手は肩の真下に置きます。", "お尻を高く持ち上げて、体を逆V字にします。", "背骨を長く保ち、かかとを床のほうへ沈めます。", "20秒キープして休みます。合計2セットです。"], ["かかとを床に近づけようとして背中が丸まってしまう。", "肩を耳まですくめてしまう。"], "背中が丸まるときは、ひざを少し曲げましょう。かかとは床につかなくて大丈夫です。"),
    "dumbbell_deadlift": ExerciseGuide(["両手にダンベルを持ち、太ももの前で背すじを伸ばして立ちます。", "ひざをゆるめ、背中を平らに保ったままお尻を後ろへ引きます。", "ダンベルを太ももにそって、ひざのすぐ下まで下ろします。", "お尻に力を入れて立ち上がります。8回行って、合計3セットです。"], ["ダンベルを下ろすときに背中が丸まってしまう。", "ひざを大きく曲げて、スクワットのようになってしまう。"], "1回ごとにきれいなフォームで最後までできる軽さの重りを選びましょう。"),
    "dumbbell_row": ExerciseGuide(["片手をベンチか椅子につき、足を後ろへ引きます。", "もう片方の手でダンベルを持ち、背中を平らにして腕をたらします。", "ひじを体に近づけたままダンベルを腰へ引き、ゆっくり下ろします。", "左右8回ずつ行って休憩します。合計3セットです。"], ["体をひねって、勢いでダンベルを持ち上げてしまう。", "肩を耳のほうへすくめてしまう。"], "1回ごとにきれいなフォームで最後までできる軽さの重りを選びましょう。"),
    "evening_yoga": ExerciseGuide(["四つんばいになり、60秒間キャット＆カウで動きます。", "チャイルドポーズで腕を長く伸ばして座り、60秒呼吸します。", "ダウンドッグに押し上げ、かかとを床へ伸ばします。", "立って前屈し、頭を重く垂らします。", "どのポーズでも、4カウントで吸って6カウントで吐きます。"], ["ポーズをキープせず、急いで次へ移ってしまう。", "痛くなるまでポーズを無理にとってしまう。"], "ライトを暗くしてから行うと、体が休む準備をしやすくなります。"),
    "farmer_carry": ExerciseGuide(["2つのダンベルか、重みを入れた2つのバッグの間に立ちます。", "ひざを曲げ、背中を平らにして持ち上げます。", "肩を後ろに引き、目線は前にして、小さな歩幅で歩きます。", "20秒歩いたら重りを置いて休みます。合計3セットです。"], ["片側に傾いたり、肩が前に丸まってしまう。", "持ち上げるときや置くときに背中が丸まってしまう。"], "1セットごとにきれいなフォームで最後までできる軽さの重りを選び、左右を同じにしましょう。"),
    "glute_bridge": ExerciseGuide(["仰向けになり、ひざを曲げ、足裏を腰幅に開いて床につけます。", "かかとで床を押して、腰を天井のほうへ持ち上げます。", "上でお尻をぎゅっと締め、2秒キープします。", "ゆっくり下ろします。1セット12回、合計3セットです。"], ["かかとではなく、つま先で押してしまう。", "上で腰を反らしすぎてしまう。"], "腰ではなくお尻に効いていれば、正しくできています。"),
    "goblet_squat": ExerciseGuide(["ダンベルか重みを入れたリュックを、両手で胸に抱えます。", "足を肩幅に開き、つま先を少し外に向けて立ちます。", "胸を張ったまま、かかとの間に腰を下ろし、立ち上がります。", "8回行って休憩します。合計3セットです。"], ["ひざが内側に入ってしまう。", "背中が丸まって胸が落ちてしまう。"], "1回ごとにきれいなフォームで最後までできる軽さの重りを選びましょう。"),
    "hanging_knee_raise": ExerciseGuide(["鉄棒を順手で握り、腕をまっすぐにしてぶら下がります。", "肩を耳から遠ざけるように下げます。", "体を揺らさずに両ひざを股関節の高さまで上げ、ゆっくり下ろします。", "5回行ったら降りて休憩します。合計3セットです。"], ["体を揺らして、勢いでひざを上げてしまう。", "肩を耳のそばまで上げたまま、ぶら下がってしまう。"], "ぶら下がる前に鉄棒がしっかりしているか確認し、飛び降りずにそっと降りましょう。"),
    "high_knees": ExerciseGuide(["足を腰幅に開いて、背すじを伸ばして立ちます。", "その場で走り、ひざを1つずつ腰の高さまで上げます。", "腕を振り、足の指のつけ根で軽く動きます。", "20秒続けます。合計3セットです。"], ["ひざを上げるときに体が後ろに反ってしまう。", "足裏全体でドタドタと床を踏んでしまう。"], "息が上がるときは、ひざを高く上げる足踏みにペースを落としましょう。"),
    "hiit_workout": ExerciseGuide(["その場足踏みと腕回しで、3分間ウォームアップします。", "バーピー、マウンテンクライマー、ジャンプスクワットを、それぞれ45秒行います。", "種目の間に15秒休み、深く呼吸します。", "4ラウンド行ったら、呼吸が落ち着くまでゆっくり歩きます。"], ["速くしようとして、フォームが崩れてしまう。", "きついインターバルの間に息を止めてしまう。"], "自分のペースで行いましょう。速く始めるより、4ラウンドやりきることが大切です。"),
    "hip_flexor_stretch": ExerciseGuide(["片ひざをつき、もう片方の足は前の床にしっかりつけます。", "骨盤を少し丸めるように入れ、後ろ脚のお尻を締めます。", "股関節の前側が伸びるのを感じるまで、やさしく前へ体重を移します。", "ゆっくり呼吸しながら30秒キープし、反対側も行います。"], ["骨盤を入れず、腰を反らしてしまう。", "前のひざがつま先より前に出てしまう。"], "折りたたんだタオルをひざの下に敷くと、楽になります。"),
    "inversion_hang": ExerciseGuide(["逆さになるのは、大人が見ているとき、安定して点検済みの器具でだけにします。", "足首をしっかり固定し、完全に逆さにならず、少し傾けた角度から始めます。", "腕の力を抜き、最大1分間ゆっくり呼吸します。", "ゆっくり起き上がり、立つ前にしばらく座ります。", "めまい、頭の圧迫感、痛みがあれば、すぐにやめます。"], ["最初の数回で完全に逆さまになってしまう。", "逆さになったあと、すぐに立ち上がってしまう。"], "短くやさしいセッションで十分です。長くぶら下がる必要はありません。"),
    "jump_squats": ExerciseGuide(["足を肩幅に開き、胸を張って立ちます。", "太ももが床とほぼ水平になるまで、お尻を引いてしゃがみます。", "足でしっかり床を押してまっすぐ跳び、スクワットの姿勢にやさしく着地します。", "8回跳んだら休憩し、合計3セット行います。"], ["着地でひざが内側に入ってしまう。", "脚をこわばらせて、伸ばしたまま着地してしまう。"], "できるだけ静かに着地しましょう。着地の音が大きくなったら、そのセットは終わりにします。"),
    "jumping": ExerciseGuide(["足を腰幅に開き、腕は体の横でリラックスして立ちます。", "ひざを曲げ、腕を振って、まっすぐ上に跳びます。", "足の指のつけ根で、ひざを軽く曲げてやさしく着地します。", "20回跳んで30秒休み、合計3セット行います。"], ["ひざを伸ばしたまま、かかとで着地してしまう。", "着地でひざが内側に入ってしまう。"], "静かな着地はコントロールできている証拠です。猫のように着地してみましょう。"),
    "knee_circles": ExerciseGuide(["足をそろえて立ち、ひざを少し曲げます。", "両手をひざにのせます。", "ひざでゆっくり小さな円を描き、15秒間、同じ向きに回します。", "向きを変えて、反対向きに15秒回します。"], ["円が大きすぎて、ひざをねじってしまう。", "ずっと同じ向きにだけ回してしまう。"], "ジャンプやランニングの前のウォームアップに使いましょう。"),
    "legs_up_wall": ExerciseGuide(["壁の横に座り、片方の腰を壁につけます。", "仰向けに寝ながら、脚を壁に振り上げます。", "腕は体の横に置き、脚の力を抜いて壁にあずけます。", "3分間、ゆっくり呼吸しながら休みます。"], ["腰が床から浮いてしまう。", "ひざを強く突っ張って、脚に力が入ってしまう。"], "脚の裏側が突っ張るときは、腰を壁から少し離しましょう。"),
    "low_lunge_arch": ExerciseGuide(["片足を前に出し、後ろのひざを床に下ろします。", "後ろ脚の股関節の前側が伸びるのを感じるまで、腰を前にスライドさせます。", "両腕を上げて、胸を持ち上げ、やさしく反らします。", "20秒キープし、反対側も行います。左右それぞれ2セットです。"], ["前のひざがつま先より大きく前に出てしまう。", "腰だけで反ってしまう。"], "後ろのひざの下に折りたたんだタオルを敷き、反りは小さくしましょう。"),
    "lunges": ExerciseGuide(["足を腰幅に開いて、背すじを伸ばして立ちます。", "大きく一歩前に出て、両ひざが約90度になるまで腰を下ろします。", "前足のかかとで床を押して、一歩下がって元の姿勢に戻ります。", "左右の脚で8回ずつ行って休憩します。合計3セットです。"], ["前のひざが内側に入ってしまう。", "胸が前脚の上に大きく倒れてしまう。"], "動きが安定するまでは、歩幅を小さくするか、椅子につかまってバランスをとりましょう。"),
    "masai_jumps": ExerciseGuide(["腕は体の横に下ろすか、上に伸ばして、背すじを伸ばして立ちます。", "小さく弾むように跳び、ずっと体をまっすぐに保ちます。", "足の指のつけ根で、ひざを軽く曲げてやさしく着地します。", "20秒続けます。合計3セットです。"], ["かかとで強く着地してしまう。", "疲れてくると前かがみになってしまう。"], "ひざやすねが痛くなったらやめて、休んでからもう一度行いましょう。"),
    "morning_stretch": ExerciseGuide(["背すじを伸ばして立ち、首をゆっくり左右5回ずつ回します。", "両腕を頭の上に上げて指を組み、30秒間上に伸びます。", "股関節から前に倒し、手をつま先のほうへ垂らします。", "ランジの姿勢になって30秒キープし、脚を入れ替えます。", "鼻からゆっくり呼吸し、はずみをつけて伸ばさないようにします。"], ["じっとキープせず、はずみをつけて深く行ってしまう。", "キープ中に息を止めてしまう。"], "スマホを見る前にストレッチすると、習慣が早く身につきます。"),
    "mountain_pose": ExerciseGuide(["足をそろえ、体重を両足に均等にのせて立ちます。", "両腕をまっすぐ頭の上に伸ばし、手のひらを向かい合わせます。", "つま先立ちになり、指先まで上に伸びます。", "20秒キープしてゆっくり下ります。合計2セットです。"], ["あばらが開いて腰が反ってしまう。", "肩を耳まですくめてしまう。"], "前の1点を見つめるか、ふらつくときはかかとを床につけたままにしましょう。"),
    "neck_stretches": ExerciseGuide(["肩の力を抜いて下げ、背すじを伸ばして座るか立ちます。", "耳をゆっくり片方の肩へ傾け、左右それぞれ30秒キープします。", "あごを胸に近づけて、30秒キープします。", "頭を後ろに倒さずに、視線をやさしく上げて30秒キープします。"], ["手で頭を強く引っぱってしまう。", "耳に近づけようとして肩を上げてしまう。"], "長く勉強したあとに行うと、こわばりがほぐれます。"),
    "overhead_press": ExerciseGuide(["軽いダンベルかペットボトルを肩の高さで持ち、背すじを伸ばして立ちます。", "お腹に力を入れて、両腕をまっすぐ頭の上へ押し上げます。", "腕が耳の横にくるまで押し上げたら、ゆっくり肩まで下ろします。", "押すときに息を吐き、下ろすときに吸います。1セット10回です。"], ["押し上げるときに腰を反らしてしまう。", "コントロールできないほど重い重りを使ってしまう。"], "まずは自重から始め、フォームが楽になったら軽い重りを足しましょう。"),
    "pelvic_shift": ExerciseGuide(["仰向けになり、ひざを曲げ、足裏を床につけます。", "尾骨を丸めるように入れ、背骨を下から順に床から離していきます。", "上で一度止め、背骨を1つずつ、ゆっくり下ろします。", "ゆっくり10回行って休憩します。合計2セットです。"], ["腰を一気に、ひとかたまりで押し上げてしまう。", "上で腰を反らしてしまう。"], "背中の各部分が順に床につくのを感じられるくらい、ゆっくり動きましょう。"),
    "pilates_core": ExerciseGuide(["前腕プランクを1分間キープします。体は一直線です。", "仰向けでデッドバグを行い、反対側の腕と脚をゆっくり下ろします。", "四つんばいでバードドッグに切り替え、反対側の腕と脚を伸ばします。", "最後にグルートブリッジを1分、レッグレイズを1分行います。", "体幹を締めるたびに、息を吐きます。"], ["プランクで腰が落ちてしまう。", "デッドバグで腰が床から浮いて反ってしまう。"], "速さよりも、ゆっくりコントロールすることが大切です。きれいな1回ごとに本当の力がつきます。"),
    "pilates_roll_over": ExerciseGuide(["仰向けになり、腕は体の横、脚はまっすぐ上に上げます。", "腕で床を押して腰を持ち上げ、脚を頭の上へ転がします。", "脚が頭の後ろで床と水平になったら止めます。", "ゆっくり転がして戻します。5回行って休憩し、合計2セットです。"], ["勢いで脚を振り上げてしまう。", "肩ではなく首の上に乗ってしまう。"], "体重は首ではなく肩で受け、楽にしたいときはひざを曲げましょう。"),
    "plank": ExerciseGuide(["前腕を床につけ、ひじを肩の真下に置きます。", "足を後ろに引いて、体を一直線にします。", "お尻を締め、おへそを引き込んで30秒キープします。", "30秒休んで、合計3セット行います。"], ["腰が床のほうへ落ちてしまう。", "腰が高く上がりすぎてしまう。"], "楽になってきたら、毎週5秒ずつ増やしましょう。"),
    "pogo_jumps": ExerciseGuide(["足を腰幅に開き、手は腰にあてて立ちます。", "ひざをほぼ伸ばしたまま、足の指のつけ根で弾みます。", "ホッピングのように、床に触れる時間を短く素早くします。", "20秒続けます。合計3セットです。"], ["弾むたびにひざを深く曲げてしまう。", "かかとを床にたたきつけてしまう。"], "硬くて平らな場所で跳び、すねや足首が痛くなったらやめましょう。"),
    "posture_check": ExerciseGuide(["1時間ごとのリマインダーをセットして、座り方や立ち方をチェックします。", "耳を肩の真上に、肩を腰の真上にそろえます。", "肩を後ろへ回して下げ、胸をやさしく開きます。", "頭のてっぺんが糸で上に引かれているのを想像して、息をします。"], ["やりすぎて、かたい反り腰になってしまう。", "頭が前に出たまま、スマホを見下ろしてしまう。"], "画面を目の高さに上げると、よい姿勢が自然に身につきます。"),
    "pre_sleep_routine": ExerciseGuide(["寝る30分前に始めます。照明を暗くして、画面を片づけます。", "本を読むか、落ち着いた音楽を15分聴きます。", "ベッドか床で、やさしいストレッチを5分行います。", "4秒で吸って6秒で吐く呼吸を、10回行います。"], ["あと1分だけとスマホをスクロールしてしまう。", "寝る時間が日によって大きくずれてしまう。"], "毎晩同じ時間に同じ手順を行うと、眠りやすくなります。"),
    "pull_ups": ExerciseGuide(["鉄棒を順手で、肩幅より少し広く握ります。", "腕を伸ばしたぶら下がりから始め、肩甲骨を下げます。", "あごが鉄棒を越えるまで引き上げ、ゆっくり体を下ろします。", "2回行ったら降りて休憩します。合計3セットです。"], ["鉄棒を越えようと、脚を蹴って揺らしてしまう。", "コントロールして下ろさず、勢いよく落ちてしまう。"], "足の下にバンドをかけるか、ジャンプで上まで上がってゆっくり下りましょう。鉄棒がしっかりしているかも確認します。"),
    "puppy_pose": ExerciseGuide(["四つんばいになり、腰をひざの真上に置きます。", "手を前に歩かせ、腰はそのままの位置に保ちます。", "胸とおでこを床のほうへ沈めます。", "20秒キープして戻ります。合計2セットです。"], ["腰がかかとのほうへ後ろにずれてしまう。", "ひじを曲げて、床にのせてしまう。"], "肩の伸びが強すぎるときは、おでこをクッションにのせましょう。"),
    "push_ups": ExerciseGuide(["手を肩幅より少し広く床につきます。", "足を後ろに引いて、体を一直線にします。", "ひじを曲げて胸を床へ近づけ、押し上げて戻ります。", "5回行って休憩します。合計3セットです。"], ["腰が床のほうへ落ちてしまう。", "ひじを真横に開いてしまう。"], "楽にしたいときは、ひざをつくか、ベンチに手をつきましょう。"),
    "scapular_pull": ExerciseGuide(["鉄棒を順手で、肩幅より少し広く握ります。", "腕を伸ばしてぶら下がり、肩が耳のほうへ上がるのにまかせます。", "肩甲骨を下げて、ひじは伸ばしたまま体を少し持ち上げます。", "1秒止めて力をぬきます。5回行って、合計3セットです。"], ["高く引こうとして、ひじを曲げてしまう。", "脚を振って勢いをつけてしまう。"], "鉄棒がしっかりしているか確認し、フルのぶら下がりがきついときは、足を台にのせましょう。"),
    "scapular_retraction": ExerciseGuide(["背すじを伸ばして座るか立ち、腕は体の横でリラックスします。", "肩甲骨を後ろポケットにしまい込むように、後ろ下へ寄せます。", "ゆっくり1呼吸の間、寄せたままキープして力をぬきます。", "10回行って休憩します。合計2セットです。"], ["寄せるときに肩をすくめてしまう。", "あばらを前に出して背中を反らしてしまう。"], "ずっとあごは水平のまま、首の力を抜きましょう。"),
    "seated_forward_fold": ExerciseGuide(["床に座って脚をまっすぐ伸ばし、つま先を上に向けます。", "背すじを伸ばして座り、両腕を頭の上に伸ばします。", "股関節から前に倒し、すねか足に手を伸ばします。", "20秒キープして起き上がります。合計2セットです。"], ["つま先に届かせようとして、上背部を丸めてしまう。", "もっと深く伸ばそうとして、はずみをつけてしまう。"], "腰が丸まるときは、ひざを少し曲げるか、折りたたんだタオルの上に座りましょう。"),
    "shoulder_rolls": ExerciseGuide(["腕を体の横に力を抜いてたらし、背すじを伸ばして立ちます。", "肩を前に大きく回します。15回行います。", "後ろに15回回し、肩甲骨を寄せます。", "手を背中で組み、胸を20秒開きます。"], ["小さく急いだ円を描いてしまう。", "息を止めたまま肩をすくめてしまう。"], "授業や勉強の合間に1セット行うと、肩が開いた状態を保てます。"),
    "side_plank": ExerciseGuide(["横向きに寝て、前腕を床につけます。ひじは肩の真下です。", "足を重ねて、腰を床から持ち上げます。", "頭からかかとまで、体を一直線に保ちます。", "15秒キープし、反対側も行います。左右それぞれ2セットです。"], ["腰が床のほうへ落ちてしまう。", "胸が床のほうへ前に倒れてしまう。"], "下側のひざを床につけると、楽になります。"),
    "single_leg_calf_raise": ExerciseGuide(["段のふちで片足の指のつけ根で立ち、壁か手すりにつかまります。", "かかとを段の高さより低くなるまで、ゆっくり下ろします。", "できるだけ高くつま先立ちになり、1秒止めます。", "左右の脚で8回ずつ行って休憩します。合計3セットです。"], ["ゆっくり動かず、下ではずんで戻ってしまう。", "ふくらはぎを助けるためにひざを曲げてしまう。"], "まずは自分の体重で行いましょう。ダンベルやリュックを足すときは、1回ごとにきれいなフォームで最後までできる軽さの重りにします。"),
    "single_leg_hops": ExerciseGuide(["片脚で立ち、もう片方の足は後ろに上げます。", "その場で小さくホップし、足の指のつけ根で着地します。", "腰の高さをそろえ、立っているほうのひざは軽く曲げます。", "8回ホップしたら脚を入れ替えます。左右それぞれ2セットです。"], ["ホップしている脚のひざが内側に入ってしまう。", "高く跳びすぎてバランスを崩してしまう。"], "手で触れられる壁のそばで、バランスが安定するまでホップは低くしましょう。"),
    "skipping_rope": ExerciseGuide(["グリップを腰の高さで持ち、ひじを体の近くに置きます。", "腕全体ではなく手首で縄を回します。", "縄をこえるだけの高さで跳び、足の指のつけ根で着地します。", "5分間跳び、1分休みます。これを3セット行います。"], ["高く跳びすぎて、すぐ疲れてしまう。", "足裏全体でかかとから着地してしまう。"], "ひっかかるのは普通です。やり直して、リズムを続けましょう。"),
    "spinal_twist": ExerciseGuide(["仰向けになり、腕を横に広げます。", "片ひざを曲げて、体の反対側の床のほうへ倒します。", "両肩は床につけたまま、反対側を見ます。", "20秒キープし、反対側も行います。左右それぞれ2セットです。"], ["反対側の肩が床から浮いてしまう。", "手でひざを無理に床へ押し下げてしまう。"], "ひざが床に届かないときは、ひざの下にクッションをはさみましょう。"),
    "sprint_intervals": ExerciseGuide(["5分間の軽いジョギングとレッグスイングでウォームアップします。", "腕を振って、全力で30秒間ダッシュします。", "90秒間、歩くか軽くジョギングして回復します。", "ダッシュを3本くり返し、5分間歩いてクールダウンします。"], ["ウォームアップなしでダッシュしてしまう。", "体が後ろにそって歩幅が大きくなりすぎ、前に進む走りになっていない。"], "平らで安全な場所を選び、元気なときだけ全力で走りましょう。"),
    "squats": ExerciseGuide(["足を肩幅に開き、つま先を少し外に向けて立ちます。", "お尻を後ろに引き、太ももが床と平行になるまで下ろします。", "胸を張り、ひざがつま先と同じ向きになるようにします。", "かかとで床を押して立ち上がり、上がるときに息を吐きます。"], ["かかとが床から浮いてしまう。", "いちばん下で背中が丸まってしまう。"], "最初の数セットは、鏡の前でフォームを確認しましょう。"),
    "standing_side_stretch": ExerciseGuide(["足を腰幅に開いて、背すじを伸ばして立ちます。", "両腕を頭の上に伸ばし、片方の手首をもう片方の手でつかみます。", "ゆっくり片側へ傾け、両足は床をしっかり踏みます。", "15秒キープし、反対側も行います。左右それぞれ2セットです。"], ["まっすぐ真横ではなく、前に倒れたりひねったりしてしまう。", "腰を横に大きく突き出してしまう。"], "2枚の壁の間に立っていて、横にしか動けないと想像しましょう。"),
    "step_ups": ExerciseGuide(["段か、頑丈な低いベンチの前に立ちます。", "片足を足裏全体で段にのせ、押し上げてまっすぐ立ちます。", "もう片方の足をゆっくり床に下ろします。", "左右の脚で8回ずつ行って休憩します。合計3セットです。"], ["床についている足で強く蹴ってしまう。", "コントロールして下ろさず、勢いよく落ちてしまう。"], "すべったり倒れたりしない段を使い、高くする前は低い段から始めましょう。"),
    "superman": ExerciseGuide(["うつ伏せになり、腕を前に伸ばします。", "腕と脚を床から少しだけ持ち上げます。", "首を長く保って床を見て、2秒キープします。", "ゆっくり下ろします。1セット8回、合計2セットです。"], ["胸と脚をできるだけ高く上げようと力んでしまう。", "頭を上に向けて首を縮めてしまう。"], "少し上げれば十分です。腰がつまるときは、上げる高さを低くしましょう。"),
    "swimming_basketball": ExerciseGuide(["5分間、ゆっくり泳ぐか、軽いドリブルでウォームアップします。", "ペースを保って、30分以上泳ぐかプレーします。", "ストロークやシュート、リバウンドのたびに、しっかり伸ばします。", "5分間、軽く動いてストレッチしてクールダウンします。"], ["ウォームアップを飛ばして、いきなり全力で始めてしまう。", "プレー中に水を飲むのを忘れてしまう。"], "友達を誘いましょう。みんなでやるスポーツは続けやすいです。"),
    "table_top": ExerciseGuide(["ひざを曲げて座り、足裏を床につけて、手は腰の後ろの床に置きます。", "指先を足のほうに向け、手と足で床を押します。", "ひざから肩まで体が平らになるまで、腰を持ち上げます。", "15秒キープして下ろします。合計2セットです。"], ["真ん中で腰が落ちてしまう。", "頭を後ろに倒して首を痛めてしまう。"], "手首が痛いときは、指先を外側に向けましょう。"),
    "thoracic_extension": ExerciseGuide(["しっかりした椅子に座り、背もたれの上端が肩甲骨のすぐ下にくるようにします。", "手を頭の後ろに添え、ひじは広げたままにします。", "上背部をゆっくり背もたれに沿って反らし、上を見ます。", "戻ります。8回行って休憩し、合計2セットです。"], ["上背部ではなく、腰から反ってしまう。", "手で頭を前に引っぱってしまう。"], "動いたり倒れたりしない椅子を使い、足裏は床にしっかりつけましょう。"),
    "toe_touch": ExerciseGuide(["足を腰幅に開いて立ち、ひざはゆるめます。", "股関節から前に倒し、手をつま先のほうへ伸ばします。", "じっと20秒キープし、ゆっくり呼吸します。", "ゆっくり起き上がり、休んでもう1回行います。"], ["届かせようとして、はずみをつけてしまう。", "ひざを伸ばしきってしまう。"], "つま先に届かなくても、すねまでで大丈夫です。ちゃんと効きます。"),
    "tuck_jumps": ExerciseGuide(["足を腰幅に開いて、背すじを伸ばして立ちます。", "素早く浅いスクワットに沈み、できるだけ高く跳びます。", "上で両ひざを胸に引き寄せ、ひざを曲げてやさしく着地します。", "6回跳んで休憩し、合計3セット行います。"], ["ひざを上げず、胸をひざに倒してしまう。", "脚を伸ばしたまま強く着地してしまう。"], "ジャンプの合間にバランスを整え、まわりに広い空間があり、すべらない床かも確認しましょう。"),
    "upward_salute": ExerciseGuide(["足をそろえ、腕は体の横にして立ちます。", "息を吸いながら、両腕を頭の上に伸ばします。", "あばらは下げたまま、肩は耳から遠ざけます。", "ゆっくり呼吸して15秒キープし、腕を下ろします。合計2セットです。"], ["後ろにそって腰を反らしてしまう。", "あばらが前に突き出てしまう。"], "後ろではなく上に伸びましょう。体は足の真上に重ねます。"),
    "wall_angels": ExerciseGuide(["壁に背中をつけ、足は少し前に出して立ちます。", "ひじを曲げて腕を壁にのせます。ゴールポストの形です。", "あばらは下げたまま、ゆっくり腕を上にスライドさせて、また下ろします。", "ゆっくり1セット8回、合計2セット行います。"], ["あばらが開いて腰が反ってしまう。", "腕が壁から離れてしまう。"], "腕を壁につけたままでいられる高さまでにしましょう。練習すると楽になります。"),
    "wall_dog": ExerciseGuide(["壁に向かって、脚1本分ほど離れて立ちます。", "手を腰の高さで壁につけます。", "腕がまっすぐで背骨が長くなるまで、股関節から後ろに引きます。", "ゆっくり呼吸して20秒キープします。合計2セットです。"], ["上背部が丸まってしまう。", "ひじを曲げて壁にもたれてしまう。"], "床に降りられないとき、机での休憩にぴったりです。"),
    "wall_sit": ExerciseGuide(["壁に背中をつけ、足は一歩前に出して立ちます。", "太ももが床と水平になるまで、滑るように下ります。", "ひざは足首の真上に、背中全体は壁につけたままです。", "20秒キープして立ち上がります。合計3セットです。"], ["手を太ももにのせてしまう。", "ひざがつま先より前に出てしまう。"], "ひざがつらいときは少し高めにして、強くなったら低くしましょう。"),
    "wall_stand": ExerciseGuide(["かかとを壁につけ、足を腰幅に開いて立ちます。", "お尻、肩甲骨、後頭部を壁につけます。", "あごを少し引き、腕は体の横でリラックスします。", "鼻から落ち着いて呼吸しながら、5分キープします。"], ["腰を壁から大きく離して反らしてしまう。", "あごを水平に保たず、上に突き出してしまう。"], "この感覚を覚えて、日中も保てるようにしましょう。"),
  },
  "ko": {
    "band_pull_apart": ExerciseGuide(["바르게 서서 팔을 쭉 펴고 어깨 높이로 밴드를 잡아요.", "날개뼈를 모으면서 밴드를 양쪽으로 벌려요.", "밴드가 가슴에 닿게 한 뒤 천천히 돌아와요.", "12회 하고 쉬어요. 모두 2세트예요."], ["어깨가 귀 쪽으로 올라가요.", "밴드를 천천히 돌려놓지 않고 튕겨 보내요."], "매 횟수를 바른 자세로 끝낼 수 있을 만큼 가벼운 밴드를 고르고, 먼저 찢어진 곳이 없는지 확인해요."),
    "bar_hanging": ExerciseGuide(["철봉을 오버핸드로 잡고, 손은 어깨너비로 벌려요.", "발을 들고 몸을 곧게, 힘을 빼고 매달려요.", "어깨에 살짝 힘을 주고 30초 동안 천천히 숨 쉬어요.", "조심히 내려와 30~60초 쉬고, 모두 3세트 해요."], ["매달린 채 다리를 흔들거나 차요.", "조심히 내려오지 않고 철봉에서 뛰어내려요."], "짧게 시작해서 매주 몇 초씩 늘려요."),
    "bird_dog": ExerciseGuide(["네발 자세로 시작해요. 손은 어깨 아래, 무릎은 엉덩이 아래에 둬요.", "한쪽 팔은 앞으로, 반대쪽 다리는 뒤로 곧게 뻗어요.", "엉덩이 높이를 맞춘 채 2초 버티고 돌아와요.", "8회 하고 좌우를 바꿔요. 양쪽 모두 2세트씩 해요."], ["다리를 들 때 허리가 아래로 처져요.", "다리를 더 높이 들려고 골반이 열려요."], "허리 위에 물컵이 놓여 있어서 쏟으면 안 된다고 상상해요."),
    "bow_pose": ExerciseGuide(["엎드려서 뒤꿈치가 엉덩이 쪽으로 오게 무릎을 굽혀요.", "손을 뒤로 뻗어 양쪽 발목을 잡아요.", "발을 손 쪽으로 차듯이 해서 가슴과 허벅지를 들어 올려요.", "10초 버티고 천천히 내려와요. 모두 2세트예요."], ["무릎이 골반보다 넓게 벌어져요.", "고개를 뒤로 젖혀서 목이 힘들어요."], "편안한 만큼만 들어요. 허리가 아프면 이 동작은 건너뛰어요."),
    "broad_jumps": ExerciseGuide(["발을 골반 너비로 벌리고 발끝을 선 뒤에 둬요.", "팔을 뒤로 휘두르고 무릎을 굽히며 엉덩이를 뒤로 빼요.", "팔을 앞으로 휘두르며 최대한 멀리 뛰어 두 발로 착지해요.", "착지를 1초 유지하고 걸어서 돌아와요. 5번 뛰고, 모두 3세트예요."], ["착지할 때 앞이나 뒤로 넘어져요.", "무릎을 쭉 편 채로 착지해요."], "미끄럽지 않은 바닥에서 뛰고, 착지를 매번 멈출 수 있을 때까지 짧게 뛰어요."),
    "burpees": ExerciseGuide(["바르게 선 다음 쪼그려 앉아 손을 바닥에 짚어요.", "발을 뒤로 점프해서 곧은 플랭크 자세를 만들어요.", "발을 손 쪽으로 다시 점프해서 가져와요.", "위로 곧게 점프해요. 5회 하고 쉬어요. 모두 3세트예요."], ["플랭크에서 엉덩이가 처져요.", "점프 후 다리를 쭉 편 채 세게 착지해요."], "쉽게 하려면 점프하지 말고 발을 걸어서 뒤로 뺐다 가져오고, 자세가 흐트러지면 속도를 늦춰요."),
    "calf_pulses": ExerciseGuide(["바르게 서서 발끝으로 올라가요. 균형이 필요하면 손끝을 벽에 대요.", "몇 센티미터만 작게 위아래로 튕겨요.", "세트 내내 뒤꿈치를 바닥에서 뗀 채로 있어요.", "20초 동안 계속해요. 모두 3세트예요."], ["튕기는 사이에 뒤꿈치가 바닥에 닿아요.", "동작이 너무 커져서 펄스가 아니게 돼요."], "종아리가 뜨거운 느낌은 괜찮아요. 찌릿한 통증이 있으면 멈춰요."),
    "calf_raise": ExerciseGuide(["벽 옆에 바르게 서서 균형을 위해 손끝을 벽에 대요.", "발볼로 천천히 최대한 높이 올라가요.", "맨 위에서 1초 멈추고 뒤꿈치를 천천히 내려요.", "한 세트에 15회, 모두 3세트 해요."], ["천천히 하지 않고 빠르게 튕겨요.", "맨 위에서 발목이 바깥으로 꺾여요."], "양치하면서 하면 매일 하는 습관으로 만들기 쉬워요."),
    "cat_cow": ExerciseGuide(["네발 자세로 시작해요. 손목은 어깨 아래, 무릎은 엉덩이 아래에 둬요.", "숨을 들이마시며 배를 내리고 가슴과 시선을 들어요(카우).", "숨을 내쉬며 등을 둥글게 말고 턱을 당겨요(캣).", "호흡에 맞춰 천천히 10번 움직여요. 2세트 해요."], ["호흡보다 빠르게 움직여요.", "척추 전체가 아니라 목만 움직여요."], "아침에 가장 먼저 하는 동작이나, 오래 앉아 있다가 몸을 풀 때 좋아요."),
    "chest_stretch": ExerciseGuide(["문틀 사이에 서서 한쪽 팔뚝을 문틀에 대요. 팔꿈치는 어깨 높이예요.", "같은 쪽 발을 문 너머로 한 걸음 내디뎌요.", "어깨 앞쪽이 늘어나는 느낌이 들 때까지 가슴을 앞으로 기울여요.", "20초 버티고 반대쪽으로 바꿔요. 양쪽 모두 2세트씩 해요."], ["더 기울이려고 허리를 젖혀요.", "어깨가 귀 쪽으로 올라가요."], "스트레칭은 부드럽게 하고, 어깨가 찝히는 느낌이 들면 줄여요."),
    "childs_pose": ExerciseGuide(["바닥에 무릎을 꿇고 엄지발가락은 붙이고 무릎은 벌려요.", "엉덩이를 뒤로 보내 뒤꿈치 위에 앉아요.", "손을 앞으로 걸어 나가고 이마를 바닥에 대고 쉬어요.", "30초 동안 천천히 숨 쉬고 일어나요. 모두 2세트예요."], ["더 멀리 뻗으려고 엉덩이가 뒤꿈치에서 많이 떠요.", "숨을 참고 어깨에 힘을 줘요."], "무릎이 당기면 엉덩이와 뒤꿈치 사이에 쿠션을 끼워요."),
    "chin_tucks": ExerciseGuide(["바르게 앉거나 서서 정면을 봐요.", "이중턱을 만들듯이 턱을 곧게 뒤로 밀어요.", "3초 버티고 힘을 풀어요.", "한 세트에 8회, 모두 2세트 해요."], ["머리를 뒤로 밀지 않고 아래로 숙여요.", "목이 아플 만큼 세게 밀어요."], "휴대폰을 내려놓을 때마다 몇 번씩 해요."),
    "cobra_stretch": ExerciseGuide(["엎드려서 손바닥을 어깨 아래 바닥에 짚어요.", "바닥을 밀어내며 가슴을 천천히 들어요. 골반은 바닥에 둬요.", "팔꿈치는 살짝 굽히고 어깨는 귀에서 멀리 둬요.", "천천히 숨 쉬며 15초 버티고, 천천히 내려와요."], ["너무 높이 올라가서 허리가 찝혀요.", "어깨가 귀 쪽으로 올라가요."], "편안한 만큼만 올라가요. 연습하면 점점 깊어져요."),
    "dead_bug": ExerciseGuide(["누워서 팔은 위로 곧게 뻗고 무릎은 엉덩이 위에서 굽혀요.", "허리를 바닥에 살며시 눌러요.", "한쪽 팔은 머리 위로, 반대쪽 다리는 바닥 쪽으로 내렸다가 돌아와요.", "양쪽 8회씩 하고 쉬어요. 모두 2세트예요."], ["허리가 바닥에서 떠서 젖혀져요.", "횟수를 서둘러 해치워요."], "허리를 바닥에 붙인 채 할 수 있는 만큼만 팔과 다리를 내려요."),
    "dead_hang_active": ExerciseGuide(["철봉을 오버핸드로 잡고, 손은 어깨보다 조금 넓게 벌려요.", "팔을 쭉 펴고 매달린 다음 날개뼈를 아래로, 뒤로 당겨요.", "다리는 모으고 코어에 힘을 주고 20초 버텨요.", "조심히 내려와 세트 사이에 40초 쉬어요."], ["턱걸이처럼 팔꿈치를 굽혀요.", "어깨가 귀까지 올라가요."], "철봉을 몸에서 밀어낸다고 생각하면 어깨가 일하는 느낌이 들어요."),
    "deadlift_stretch": ExerciseGuide(["발을 골반 너비로 벌리고 무릎을 살짝 굽히고 서요.", "골반에서 앞으로 숙이며 허벅지를 따라 손을 내려요.", "등은 평평하게 두고 햄스트링이 늘어날 때까지 발끝 쪽으로 손을 뻗어요.", "엉덩이에 힘을 주며 일어나요. 한 세트에 천천히 12회 해요."], ["더 내려가려고 등이 둥글게 말려요.", "무릎을 완전히 쭉 펴요."], "천천히 움직여요. 얼마나 멀리 뻗느냐보다 조절이 중요해요."),
    "downward_dog": ExerciseGuide(["네발 자세로 시작해요. 손은 어깨 아래에 둬요.", "엉덩이를 높이 들어 몸이 거꾸로 된 V자가 되게 해요.", "척추를 길게 하고 뒤꿈치를 바닥 쪽으로 내려요.", "20초 버티고 쉬어요. 모두 2세트예요."], ["뒤꿈치를 내리려고 등이 둥글게 말려요.", "어깨가 귀까지 올라가요."], "등이 둥글어지면 무릎을 조금 굽혀요. 뒤꿈치가 바닥에 닿지 않아도 괜찮아요."),
    "dumbbell_deadlift": ExerciseGuide(["양손에 덤벨을 들고 허벅지 앞에서 바르게 서요.", "무릎을 살짝 풀고 등을 평평하게 한 채 엉덩이를 뒤로 밀어요.", "덤벨을 허벅지를 따라 무릎 바로 아래까지 내려요.", "엉덩이에 힘을 주며 일어나요. 8회 하고, 모두 3세트예요."], ["덤벨이 내려갈 때 등이 둥글게 말려요.", "무릎을 많이 굽혀서 스쿼트가 돼 버려요."], "모든 횟수를 바른 자세로 끝낼 수 있는 가벼운 무게를 골라요."),
    "dumbbell_row": ExerciseGuide(["한 손은 벤치나 의자에 짚고 발을 뒤로 빼요.", "다른 손에 덤벨을 들고 등은 평평하게, 팔은 아래로 늘어뜨려요.", "팔꿈치를 몸에 붙인 채 덤벨을 엉덩이 쪽으로 당기고 천천히 내려요.", "양쪽 8회씩 하고 쉬어요. 모두 3세트예요."], ["몸을 비틀어서 반동으로 덤벨을 들어 올려요.", "어깨가 귀 쪽으로 올라가요."], "모든 횟수를 바른 자세로 끝낼 수 있는 가벼운 무게를 골라요."),
    "evening_yoga": ExerciseGuide(["네발 자세로 60초 동안 캣카우로 움직여요.", "아기 자세로 앉아 팔을 길게 뻗고 60초 동안 숨 쉬어요.", "다운독으로 밀어 올리며 뒤꿈치를 바닥 쪽으로 뻗어요.", "서서 앞으로 숙이고 머리를 무겁게 늘어뜨려요.", "모든 자세에서 4카운트 들이마시고 6카운트 내쉬어요."], ["자세를 유지하지 않고 서둘러 넘어가요.", "아플 때까지 자세를 억지로 해요."], "조명을 어둡게 하고 하면 몸이 편안해지는 데 도움이 돼요."),
    "farmer_carry": ExerciseGuide(["덤벨 두 개나 무게를 채운 가방 두 개 사이에 서요.", "무릎을 굽히고 등은 평평하게 해서 들어 올려요.", "어깨는 뒤로, 시선은 앞으로 두고 작은 걸음으로 걸어요.", "20초 걷고 내려놓은 뒤 쉬어요. 모두 3세트예요."], ["한쪽으로 기울거나 어깨가 앞으로 말려요.", "들거나 내려놓을 때 등이 둥글게 말려요."], "세트마다 바른 자세로 끝낼 수 있는 가벼운 무게를 고르고, 양쪽을 똑같이 해요."),
    "glute_bridge": ExerciseGuide(["누워서 무릎을 굽히고 발바닥을 골반 너비로 바닥에 둬요.", "뒤꿈치로 바닥을 밀며 엉덩이를 천장 쪽으로 들어요.", "맨 위에서 엉덩이를 2초 동안 꽉 조여요.", "천천히 내려와요. 한 세트에 12회, 모두 3세트 해요."], ["뒤꿈치가 아니라 발끝으로 밀어요.", "맨 위에서 허리를 너무 젖혀요."], "허리가 아니라 엉덩이에 힘이 느껴지면 잘하고 있는 거예요."),
    "goblet_squat": ExerciseGuide(["덤벨이나 무게를 채운 배낭을 두 손으로 가슴에 안아요.", "발을 어깨너비로 벌리고 발끝은 살짝 바깥으로 향해요.", "가슴을 편 채 뒤꿈치 사이로 앉았다가 다시 일어나요.", "8회 하고 쉬어요. 모두 3세트예요."], ["무릎이 안쪽으로 모여요.", "등이 둥글게 말리고 가슴이 내려가요."], "모든 횟수를 바른 자세로 끝낼 수 있는 가벼운 무게를 골라요."),
    "hanging_knee_raise": ExerciseGuide(["철봉을 오버핸드로 잡고 팔을 쭉 펴고 매달려요.", "어깨를 귀에서 멀어지게 아래로 당겨요.", "몸을 흔들지 않고 양 무릎을 골반 높이까지 올렸다가 천천히 내려요.", "5회 하고 내려와 쉬어요. 모두 3세트예요."], ["몸을 흔들어서 반동으로 무릎을 올려요.", "어깨가 귀 옆까지 올라간 채 매달려요."], "매달리기 전에 철봉이 튼튼한지 확인하고, 뛰어내리지 말고 조심히 내려와요."),
    "high_knees": ExerciseGuide(["발을 골반 너비로 벌리고 바르게 서요.", "제자리에서 달리며 무릎을 하나씩 골반 높이까지 올려요.", "팔을 흔들고 발볼로 가볍게 움직여요.", "20초 동안 계속해요. 모두 3세트예요."], ["무릎이 올라올 때 몸이 뒤로 젖혀져요.", "발바닥 전체로 쿵쿵 바닥을 밟아요."], "숨이 차면 무릎을 높이 드는 제자리걸음으로 속도를 늦춰요."),
    "hiit_workout": ExerciseGuide(["제자리 행진과 팔 돌리기로 3분 동안 준비운동을 해요.", "버피, 마운틴 클라이머, 점프 스쿼트를 각각 45초씩 해요.", "동작 사이에 15초 쉬며 깊게 숨 쉬어요.", "4라운드를 마치면 숨이 가라앉을 때까지 천천히 걸어요."], ["더 빠르게 하려고 자세가 흐트러져요.", "힘든 구간에서 숨을 참아요."], "자기 속도로 해요. 빠르게 시작하는 것보다 4라운드를 끝까지 하는 게 더 나아요."),
    "hip_flexor_stretch": ExerciseGuide(["한쪽 무릎을 꿇고 다른 발은 앞에서 바닥에 평평하게 둬요.", "골반을 살짝 말아 넣고 뒤쪽 다리의 엉덩이를 조여요.", "고관절 앞쪽이 늘어나는 느낌이 들 때까지 부드럽게 앞으로 옮겨요.", "천천히 숨 쉬며 30초 버티고, 반대쪽도 해요."], ["골반을 말지 않고 허리를 젖혀요.", "앞쪽 무릎이 발끝보다 앞으로 나가요."], "무릎 밑에 접은 수건을 깔면 더 편해요."),
    "inversion_hang": ExerciseGuide(["거꾸로 매달리는 건 어른이 지켜볼 때, 안정적이고 점검한 기구에서만 해요.", "발목을 단단히 고정하고, 완전히 거꾸로가 아니라 살짝 기울인 각도에서 시작해요.", "팔에 힘을 빼고 최대 1분 동안 천천히 숨 쉬어요.", "천천히 원래 자세로 돌아오고, 일어나기 전에 잠깐 앉아 있어요.", "어지럽거나 머리가 눌리는 느낌이나 통증이 있으면 바로 멈춰요."], ["처음부터 완전히 거꾸로 매달려요.", "거꾸로 있다가 바로 벌떡 일어나요."], "짧고 부드럽게 해도 충분해요. 더 오래 매달릴 필요는 없어요."),
    "jump_squats": ExerciseGuide(["발을 어깨너비로 벌리고 가슴을 펴고 서요.", "허벅지가 바닥과 거의 평행해질 때까지 엉덩이를 뒤로 빼고 앉아요.", "발로 바닥을 힘껏 밀어 곧게 점프하고, 스쿼트 자세로 부드럽게 착지해요.", "8번 점프하고 쉬어요. 모두 3세트예요."], ["착지할 때 무릎이 안쪽으로 모여요.", "다리를 뻣뻣하게 편 채 착지해요."], "최대한 조용히 착지해요. 착지 소리가 커지면 그 세트는 멈춰요."),
    "jumping": ExerciseGuide(["발을 골반 너비로 벌리고 팔은 몸 옆에 편하게 두고 서요.", "무릎을 굽히고 팔을 휘두르며 곧게 위로 점프해요.", "무릎을 살짝 굽히고 발볼로 부드럽게 착지해요.", "20번 점프하고 30초 쉬어요. 모두 3세트 해요."], ["다리를 편 채 뒤꿈치로 착지해요.", "착지할 때 무릎이 안쪽으로 모여요."], "조용한 착지는 조절이 잘된다는 뜻이에요. 고양이처럼 착지해 봐요."),
    "knee_circles": ExerciseGuide(["발을 모으고 서서 무릎을 살짝 굽혀요.", "두 손을 무릎에 올려요.", "무릎으로 작고 천천히 원을 그려요. 한 방향으로 15초 해요.", "방향을 바꿔서 반대로 15초 해요."], ["원을 너무 크게 그려서 무릎이 꼬여요.", "한 방향으로만 돌려요."], "점프나 달리기 전에 준비운동으로 써요."),
    "legs_up_wall": ExerciseGuide(["벽 옆에 옆으로 앉아 한쪽 엉덩이를 벽에 붙여요.", "바닥에 눕으면서 다리를 벽 위로 올려요.", "팔은 몸 옆에 두고 다리는 벽에 기대 힘을 빼요.", "3분 동안 천천히 숨 쉬며 있어요."], ["허리가 바닥에서 떠요.", "무릎을 세게 펴서 다리에 힘이 들어가요."], "다리 뒤쪽이 당기면 엉덩이를 벽에서 조금 떼요."),
    "low_lunge_arch": ExerciseGuide(["한 발을 앞으로 내딛고 뒤쪽 무릎을 바닥에 내려요.", "뒤쪽 고관절 앞이 늘어나는 느낌이 들 때까지 엉덩이를 앞으로 밀어요.", "양팔을 위로 뻗고 가슴을 들어 부드럽게 젖혀요.", "20초 버티고 반대쪽으로 바꿔요. 양쪽 모두 2세트씩 해요."], ["앞쪽 무릎이 발끝보다 많이 앞으로 나가요.", "허리만으로 젖혀요."], "뒤쪽 무릎 밑에 접은 수건을 깔고, 젖히는 건 조금만 해요."),
    "lunges": ExerciseGuide(["발을 골반 너비로 벌리고 바르게 서요.", "크게 한 걸음 앞으로 나가 두 무릎이 약 90도가 될 때까지 내려가요.", "앞쪽 뒤꿈치로 바닥을 밀어 처음 자세로 돌아와요.", "다리마다 8회씩 하고 쉬어요. 모두 3세트예요."], ["앞쪽 무릎이 안쪽으로 모여요.", "가슴이 앞다리 위로 많이 숙여져요."], "움직임이 안정될 때까지 걸음을 짧게 하거나 의자를 잡고 균형을 잡아요."),
    "masai_jumps": ExerciseGuide(["바르게 서서 팔은 몸 옆에 두거나 위로 뻗어요.", "작게 통통 뛰고 내내 몸을 곧게 세워요.", "무릎을 살짝 굽히고 발볼로 부드럽게 착지해요.", "20초 동안 계속해요. 모두 3세트예요."], ["뒤꿈치로 세게 착지해요.", "지치면 몸이 앞으로 숙여져요."], "무릎이나 정강이가 아프면 멈추고, 쉰 다음에 다시 해요."),
    "morning_stretch": ExerciseGuide(["바르게 서서 목을 천천히 양쪽으로 5번씩 돌려요.", "양팔을 머리 위로 올려 깍지를 끼고 30초 동안 위로 늘려요.", "골반에서 앞으로 숙이고 손은 발끝 쪽으로 늘어뜨려요.", "런지 자세를 하고 30초 버틴 다음 다리를 바꿔요.", "코로 천천히 숨 쉬고, 반동으로 스트레칭하지 않아요."], ["가만히 버티지 않고 반동으로 더 깊이 가요.", "버티는 동안 숨을 참아요."], "휴대폰을 보기 전에 스트레칭하면 습관이 더 빨리 자리 잡아요."),
    "mountain_pose": ExerciseGuide(["발을 모으고 체중을 양발에 고르게 실어요.", "양팔을 머리 위로 곧게 뻗고 손바닥이 서로 마주 보게 해요.", "발끝으로 올라서 손끝까지 위로 늘려요.", "20초 버티고 천천히 내려와요. 모두 2세트예요."], ["갈비뼈가 벌어지고 허리가 젖혀져요.", "어깨가 귀까지 올라가요."], "앞의 한 점을 바라보거나, 흔들리면 뒤꿈치를 바닥에 두어요."),
    "neck_stretches": ExerciseGuide(["어깨 힘을 빼고 내린 채 바르게 앉거나 서요.", "귀를 한쪽 어깨 쪽으로 천천히 기울이고, 양쪽 각각 30초씩 버텨요.", "턱을 가슴 쪽으로 내리고 30초 버텨요.", "머리를 뒤로 젖히지 않고 시선만 부드럽게 올려서 30초 버텨요."], ["손으로 머리를 세게 잡아당겨요.", "귀에 닿게 하려고 어깨를 올려요."], "오래 공부한 뒤에 하면 뭉친 곳이 풀려요."),
    "overhead_press": ExerciseGuide(["가벼운 덤벨이나 물병을 어깨 높이로 들고 바르게 서요.", "코어에 힘을 주고 양팔을 머리 위로 곧게 밀어 올려요.", "팔이 귀 옆에 올 때까지 올린 다음 천천히 어깨로 내려요.", "밀 때 숨을 내쉬고 내릴 때 들이마셔요. 한 세트에 10회예요."], ["밀어 올릴 때 허리가 젖혀져요.", "조절하기 힘들 만큼 무거운 무게를 써요."], "맨몸으로 시작하고, 자세가 편해지면 가벼운 무게를 더해요."),
    "pelvic_shift": ExerciseGuide(["누워서 무릎을 굽히고 발바닥을 바닥에 둬요.", "꼬리뼈를 말아 넣고 척추를 아래부터 차례로 바닥에서 떼요.", "맨 위에서 잠깐 멈추고, 척추뼈를 하나씩 천천히 내려요.", "천천히 10회 하고 쉬어요. 모두 2세트예요."], ["엉덩이를 한 덩어리로 빠르게 밀어 올려요.", "맨 위에서 허리를 젖혀요."], "등의 각 부분이 바닥에 닿는 걸 느낄 만큼 천천히 움직여요."),
    "pilates_core": ExerciseGuide(["팔뚝 플랭크를 1분 동안 해요. 몸은 한 직선이에요.", "누워서 데드버그를 하며 반대쪽 팔과 다리를 천천히 내려요.", "네발 자세로 버드독으로 바꿔 반대쪽 팔과 다리를 뻗어요.", "마지막으로 글루트 브리지 1분, 레그 레이즈 1분을 해요.", "코어에 힘을 줄 때마다 숨을 내쉬어요."], ["플랭크에서 엉덩이가 처져요.", "데드버그에서 허리가 바닥에서 떠서 젖혀져요."], "빠른 것보다 천천히 조절하는 게 나아요. 바른 한 번 한 번이 진짜 힘이 돼요."),
    "pilates_roll_over": ExerciseGuide(["누워서 팔은 몸 옆에, 다리는 곧게 위로 들어요.", "팔로 바닥을 누르며 엉덩이를 들어 다리를 머리 위로 넘겨요.", "다리가 머리 뒤에서 바닥과 평행해지면 멈춰요.", "천천히 굴러서 내려와요. 5회 하고 쉬어요. 모두 2세트예요."], ["반동으로 다리를 넘겨요.", "어깨가 아니라 목 위로 굴러요."], "체중은 목이 아니라 어깨에 싣고, 쉽게 하려면 무릎을 굽혀요."),
    "plank": ExerciseGuide(["팔뚝을 바닥에 대고 팔꿈치는 어깨 아래에 둬요.", "발을 뒤로 빼서 몸이 한 직선이 되게 해요.", "엉덩이를 조이고 배꼽을 당긴 채 30초 버텨요.", "30초 쉬고 모두 3세트 해요."], ["엉덩이가 바닥 쪽으로 처져요.", "엉덩이를 너무 높이 들어요."], "쉬워지면 매주 5초씩 늘려요."),
    "pogo_jumps": ExerciseGuide(["발을 골반 너비로 벌리고 손은 허리에 얹고 서요.", "무릎을 거의 편 채 발볼로 통통 뛰어요.", "포고 스틱처럼 바닥에 닿는 시간을 짧고 빠르게 해요.", "20초 동안 계속해요. 모두 3세트예요."], ["뛸 때마다 무릎을 깊이 굽혀요.", "뒤꿈치가 바닥에 쿵 부딪혀요."], "단단하고 평평한 바닥에서 뛰고, 정강이나 발목이 아프면 멈춰요."),
    "posture_check": ExerciseGuide(["한 시간마다 알림을 맞춰 앉은 자세나 선 자세를 확인해요.", "귀가 어깨 위에, 어깨가 골반 위에 오도록 쌓아요.", "어깨를 뒤로, 아래로 돌리고 가슴을 부드럽게 열어요.", "머리 꼭대기가 줄에 매달려 위로 당겨진다고 상상하고 숨 쉬어요."], ["너무 신경 쓴 나머지 뻣뻣하게 허리를 젖혀요.", "머리가 앞으로 나온 채 휴대폰을 내려다봐요."], "화면을 눈높이로 올리면 바른 자세가 저절로 돼요."),
    "pre_sleep_routine": ExerciseGuide(["자기 30분 전에 시작해요. 조명을 어둡게 하고 화면은 치워요.", "15분 동안 책을 읽거나 차분한 음악을 들어요.", "침대나 바닥에서 5분 동안 부드럽게 스트레칭해요.", "4초 들이마시고 6초 내쉬는 호흡을 10번 해요."], ["딱 1분만 더 하며 휴대폰을 넘겨 봐요.", "자는 시간이 날마다 크게 달라져요."], "매일 밤 같은 시간에 같은 순서로 하면 잠들기가 쉬워져요."),
    "pull_ups": ExerciseGuide(["철봉을 오버핸드로 잡고, 손은 어깨보다 조금 넓게 벌려요.", "팔을 편 채 매달린 상태에서 시작해 날개뼈를 아래로 당겨요.", "턱이 철봉을 넘을 때까지 당기고 천천히 내려와요.", "2회 하고 내려와 쉬어요. 모두 3세트예요."], ["철봉을 넘으려고 다리를 차며 흔들어요.", "천천히 내려오지 않고 툭 떨어져요."], "밴드를 발 밑에 걸거나 점프로 위까지 올라간 다음 천천히 내려와요. 철봉이 튼튼한지도 확인해요."),
    "puppy_pose": ExerciseGuide(["네발 자세로 시작해요. 엉덩이는 무릎 바로 위에 둬요.", "손을 앞으로 걸어 나가고 엉덩이는 그 자리에 둬요.", "가슴과 이마를 바닥 쪽으로 내려요.", "20초 버티고 다시 올라와요. 모두 2세트예요."], ["엉덩이가 뒤꿈치 쪽으로 밀려요.", "팔꿈치를 굽혀 바닥에 내려놓아요."], "어깨가 너무 당기면 이마를 쿠션 위에 올려요."),
    "push_ups": ExerciseGuide(["손을 어깨보다 조금 넓게 바닥에 짚어요.", "발을 뒤로 빼서 몸이 한 직선이 되게 해요.", "팔꿈치를 굽혀 가슴을 바닥 쪽으로 내리고, 다시 밀어 올라와요.", "5회 하고 쉬어요. 모두 3세트예요."], ["엉덩이가 바닥 쪽으로 처져요.", "팔꿈치가 옆으로 활짝 벌어져요."], "쉽게 하려면 무릎을 대거나 손을 벤치에 올려요."),
    "scapular_pull": ExerciseGuide(["철봉을 오버핸드로 잡고, 손은 어깨보다 조금 넓게 벌려요.", "팔을 쭉 펴고 매달려 어깨가 귀 쪽으로 올라가게 둬요.", "날개뼈를 아래로 당겨 팔꿈치는 편 채 몸이 조금 올라가게 해요.", "1초 버티고 풀어요. 5회 하고, 모두 3세트예요."], ["더 높이 당기려고 팔꿈치를 굽혀요.", "다리를 흔들어 도움을 받아요."], "철봉이 튼튼한지 확인하고, 완전히 매달리기 힘들면 발을 박스에 올려요."),
    "scapular_retraction": ExerciseGuide(["바르게 앉거나 서서 팔은 몸 옆에 편하게 둬요.", "날개뼈를 뒤로, 아래로 당겨요. 뒷주머니에 넣는다고 생각해요.", "숨 한 번 천천히 쉬는 동안 모은 채 버티고 풀어요.", "10회 하고 쉬어요. 모두 2세트예요."], ["모으면서 어깨가 올라가요.", "갈비뼈를 앞으로 내밀고 등을 젖혀요."], "내내 턱은 수평으로, 목은 편안하게 둬요."),
    "seated_forward_fold": ExerciseGuide(["바닥에 앉아 다리를 곧게 펴고 발끝은 위로 향해요.", "바르게 앉아 양팔을 머리 위로 뻗어요.", "골반에서 앞으로 숙이며 정강이나 발을 향해 손을 뻗어요.", "20초 버티고 다시 앉아요. 모두 2세트예요."], ["발끝에 닿으려고 위쪽 등이 둥글게 말려요.", "더 깊이 가려고 반동을 줘요."], "허리가 둥글어지면 무릎을 조금 굽히거나 접은 수건 위에 앉아요."),
    "shoulder_rolls": ExerciseGuide(["바르게 서서 팔을 몸 옆에 느슨하게 늘어뜨려요.", "어깨를 앞으로 크게 15번 돌려요.", "뒤로 15번 돌리며 날개뼈를 모아요.", "손을 등 뒤에서 깍지 끼고 20초 동안 가슴을 열어요."], ["작고 서두르는 원을 그려요.", "숨을 참은 채 어깨를 으쓱해요."], "수업이나 공부 사이에 한 세트만 해도 어깨가 열린 채로 있어요."),
    "side_plank": ExerciseGuide(["옆으로 누워 팔뚝을 바닥에 대요. 팔꿈치는 어깨 아래예요.", "발을 포개고 엉덩이를 바닥에서 들어요.", "머리부터 뒤꿈치까지 몸을 한 직선으로 유지해요.", "15초 버티고 반대쪽으로 바꿔요. 양쪽 모두 2세트씩 해요."], ["엉덩이가 바닥 쪽으로 떨어져요.", "가슴이 앞쪽 바닥을 향해 굴러요."], "아래쪽 무릎을 바닥에 대면 쉬워져요."),
    "single_leg_calf_raise": ExerciseGuide(["계단 모서리에 한 발의 발볼로 서서 벽이나 난간을 잡아요.", "뒤꿈치를 계단 높이보다 아래로 천천히 내려요.", "최대한 높이 발끝으로 올라가 1초 멈춰요.", "다리마다 8회씩 하고 쉬어요. 모두 3세트예요."], ["천천히 하지 않고 아래에서 튕겨 올라와요.", "종아리를 도우려고 무릎을 굽혀요."], "맨몸으로 시작하고, 덤벨이나 배낭을 더할 땐 모든 횟수를 바른 자세로 끝낼 수 있는 가벼운 무게를 골라요."),
    "single_leg_hops": ExerciseGuide(["한 다리로 서고 다른 발은 뒤로 들어요.", "제자리에서 작게 뛰며 발볼로 착지해요.", "골반 높이를 맞추고 서 있는 무릎은 살짝 굽혀요.", "8번 뛰고 다리를 바꿔요. 양쪽 모두 2세트씩 해요."], ["뛰는 다리의 무릎이 안쪽으로 모여요.", "너무 높이 뛰어서 균형을 잃어요."], "손이 닿는 벽 가까이에서 하고, 균형이 안정될 때까지 낮게 뛰어요."),
    "skipping_rope": ExerciseGuide(["손잡이를 골반 높이에 잡고 팔꿈치는 몸 옆에 붙여요.", "팔 전체가 아니라 손목으로 줄을 돌려요.", "줄을 넘을 만큼만 뛰고 발볼로 착지해요.", "5분 동안 줄넘기하고 1분 쉬어요. 모두 3세트 해요."], ["너무 높이 뛰어서 금방 지쳐요.", "발바닥 전체로 뒤꿈치부터 착지해요."], "줄에 걸리는 건 괜찮아요. 다시 시작해서 리듬을 이어 가요."),
    "spinal_twist": ExerciseGuide(["누워서 팔을 양옆으로 벌려요.", "한쪽 무릎을 굽혀 몸 반대쪽 바닥 쪽으로 넘겨요.", "두 어깨는 바닥에 붙이고 반대쪽을 바라봐요.", "20초 버티고 반대쪽으로 바꿔요. 양쪽 모두 2세트씩 해요."], ["반대쪽 어깨가 바닥에서 떠요.", "손으로 무릎을 억지로 눌러 내려요."], "무릎이 바닥에 닿지 않으면 쿠션 위에 올려요."),
    "sprint_intervals": ExerciseGuide(["5분 동안 가볍게 조깅하고 다리를 흔들어 준비운동을 해요.", "팔을 흔들며 30초 동안 전력으로 달려요.", "90초 동안 천천히 걷거나 조깅하며 회복해요.", "전력 질주를 3번 반복하고, 5분 걸으며 마무리해요."], ["준비운동 없이 전력으로 달려요.", "앞으로 밀고 나가지 않고 몸을 젖힌 채 보폭만 너무 크게 해요."], "평평하고 안전한 곳을 고르고, 몸이 가벼울 때만 전력을 다해요."),
    "squats": ExerciseGuide(["발을 어깨너비로 벌리고 발끝은 살짝 바깥으로 향하고 서요.", "엉덩이를 뒤로 빼고 허벅지가 바닥과 평행해질 때까지 내려가요.", "가슴은 펴고 무릎은 발끝과 같은 방향으로 둬요.", "뒤꿈치로 바닥을 밀며 일어나고, 올라오면서 숨을 내쉬어요."], ["뒤꿈치가 바닥에서 떠요.", "맨 아래에서 등이 둥글게 말려요."], "처음 몇 세트는 거울 앞에서 자세를 확인해요."),
    "standing_side_stretch": ExerciseGuide(["발을 골반 너비로 벌리고 바르게 서요.", "양팔을 머리 위로 뻗고 한 손으로 다른 손목을 잡아요.", "한쪽으로 천천히 기울이고 두 발은 바닥을 꾹 눌러요.", "15초 버티고 반대쪽으로 바꿔요. 양쪽 모두 2세트씩 해요."], ["곧게 옆으로 숙이지 않고 앞으로 숙이거나 비틀어요.", "엉덩이를 옆으로 많이 밀어요."], "양옆에 벽이 있어서 옆으로만 움직일 수 있다고 상상해요."),
    "step_ups": ExerciseGuide(["계단이나 튼튼한 낮은 벤치 앞에 서요.", "한 발 전체를 계단에 올리고 밀어서 곧게 서요.", "다른 발을 천천히 바닥으로 내려요.", "다리마다 8회씩 하고 쉬어요. 모두 3세트예요."], ["바닥에 있는 발로 세게 밀어요.", "천천히 내려오지 않고 툭 떨어져요."], "미끄러지거나 넘어지지 않는 계단을 쓰고, 높이는 낮은 데서 시작해 점점 올려요."),
    "superman": ExerciseGuide(["엎드려서 팔을 앞으로 뻗어요.", "팔과 다리를 바닥에서 살짝 들어요.", "목은 길게 하고 바닥을 보며 2초 버텨요.", "천천히 내려와요. 한 세트에 8회, 모두 2세트 해요."], ["가슴과 다리를 최대한 높이 올리려고 힘을 줘요.", "고개를 들어 목이 조여요."], "조금만 들어도 충분해요. 허리가 찝히면 덜 들어요."),
    "swimming_basketball": ExerciseGuide(["5분 동안 천천히 수영하거나 가볍게 드리블하며 준비운동을 해요.", "꾸준한 속도로 최소 30분 동안 수영하거나 경기해요.", "스트로크, 슛, 리바운드마다 몸을 끝까지 뻗어요.", "5분 동안 가볍게 움직이고 스트레칭하며 마무리해요."], ["준비운동을 건너뛰고 전속력으로 시작해요.", "운동하는 동안 물 마시는 걸 잊어요."], "친구와 함께해요. 함께하는 운동이 꾸준히 하기 더 쉬워요."),
    "table_top": ExerciseGuide(["무릎을 굽히고 앉아 발바닥은 바닥에, 손은 엉덩이 뒤 바닥에 짚어요.", "손가락 끝이 발 쪽을 향하게 하고 손과 발로 바닥을 밀어요.", "무릎부터 어깨까지 몸이 평평해질 때까지 엉덩이를 들어요.", "15초 버티고 내려와요. 모두 2세트예요."], ["가운데에서 엉덩이가 처져요.", "고개를 뒤로 떨궈서 목이 힘들어요."], "손목이 아프면 손가락을 옆으로 돌려요."),
    "thoracic_extension": ExerciseGuide(["튼튼한 의자에 앉아 등받이 위쪽 끝이 날개뼈 바로 아래에 오게 해요.", "손은 머리 뒤에 두고 팔꿈치는 넓게 벌려요.", "위쪽 등을 등받이 너머로 천천히 젖히며 위를 봐요.", "다시 올라와요. 8회 하고 쉬어요. 모두 2세트예요."], ["위쪽 등이 아니라 허리에서 젖혀요.", "손으로 머리를 앞으로 당겨요."], "굴러가거나 넘어지지 않는 의자를 쓰고, 발은 바닥에 평평하게 둬요."),
    "toe_touch": ExerciseGuide(["발을 골반 너비로 벌리고 서서 무릎은 살짝 풀어 둬요.", "골반에서 앞으로 숙이며 손을 발끝 쪽으로 뻗어요.", "20초 동안 가만히 천천히 숨 쉬어요.", "천천히 일어나 쉬고, 한 번 더 해요."], ["더 닿으려고 반동을 줘요.", "무릎을 쭉 펴 버려요."], "발끝에 닿지 않으면 정강이까지만 가도 돼요. 그래도 효과가 있어요."),
    "tuck_jumps": ExerciseGuide(["발을 골반 너비로 벌리고 바르게 서요.", "빠르게 4분의 1 스쿼트로 내려갔다가 최대한 높이 점프해요.", "맨 위에서 두 무릎을 가슴 쪽으로 끌어당기고, 무릎을 굽혀 부드럽게 착지해요.", "6번 점프하고 쉬어요. 모두 3세트 반복해요."], ["무릎을 올리지 않고 가슴을 무릎 쪽으로 숙여요.", "다리를 편 채 세게 착지해요."], "점프 사이에 균형을 다시 잡고, 주변이 넓고 바닥이 미끄럽지 않은지 확인해요."),
    "upward_salute": ExerciseGuide(["발을 모으고 팔은 몸 옆에 두고 서요.", "숨을 들이마시며 양팔을 머리 위로 뻗어요.", "갈비뼈는 내리고 어깨는 귀에서 멀리 둬요.", "천천히 숨 쉬며 15초 버티고 팔을 내려요. 모두 2세트예요."], ["뒤로 젖혀 허리가 꺾여요.", "갈비뼈가 앞으로 튀어나와요."], "뒤가 아니라 위로 뻗어요. 몸은 발 위에 쌓아 올려요."),
    "wall_angels": ExerciseGuide(["벽에 등을 대고 발은 조금 앞에 둬요.", "팔꿈치를 굽혀 팔을 벽에 대요. 골대 모양이에요.", "갈비뼈는 내린 채 팔을 천천히 위로 미끄러뜨렸다가 다시 내려요.", "한 세트에 천천히 8회, 모두 2세트 해요."], ["갈비뼈가 벌어지고 허리가 젖혀져요.", "팔이 벽에서 떨어져요."], "팔이 벽에 붙어 있을 수 있는 높이까지만 가요. 연습하면 쉬워져요."),
    "wall_dog": ExerciseGuide(["벽을 마주 보고 다리 한 개 길이만큼 떨어져 서요.", "손을 골반 높이로 벽에 대요.", "팔이 곧게 펴지고 척추가 길어질 때까지 골반에서 뒤로 빼요.", "천천히 숨 쉬며 20초 버텨요. 모두 2세트예요."], ["위쪽 등이 둥글게 말려요.", "팔꿈치를 굽히고 벽에 기대요."], "바닥에 내려갈 수 없을 때 책상에서 쉬는 시간에 딱 좋아요."),
    "wall_sit": ExerciseGuide(["벽에 등을 대고 발은 한 걸음 앞에 둬요.", "허벅지가 바닥과 수평이 될 때까지 미끄러져 내려가요.", "무릎은 발목 위에, 등 전체는 벽에 붙여 둬요.", "20초 버티고 일어나요. 모두 3세트예요."], ["손을 허벅지 위에 올려놓아요.", "무릎이 발끝보다 앞으로 나가요."], "무릎이 불편하면 조금 높게 앉고, 힘이 붙으면 더 낮게 내려가요."),
    "wall_stand": ExerciseGuide(["뒤꿈치를 벽에 대고 발은 골반 너비로 벌리고 서요.", "엉덩이, 날개뼈, 뒤통수를 벽에 붙여요.", "턱을 살짝 당기고 팔은 몸 옆에 편하게 둬요.", "코로 차분하게 숨 쉬며 5분 동안 버텨요."], ["허리를 벽에서 멀리 띄워 젖혀요.", "턱을 수평으로 두지 않고 위로 들어요."], "이 느낌을 기억하고 하루 동안에도 이어 가 봐요."),
  },
  "zh": {
    "band_pull_apart": ExerciseGuide(["站直，双手握住弹力带放在身前，手臂伸直，与肩同高。", "夹紧肩胛骨，把弹力带向两侧拉开。", "让弹力带碰到胸口，然后慢慢还原。", "做 12 次后休息，共 2 组。"], ["耸肩，肩膀往耳朵靠。", "弹力带直接弹回去，而不是慢慢还原。"], "选一条够轻的弹力带，让每一次都能保持标准动作，用之前先检查有没有破损。"),
    "bar_hanging": ExerciseGuide(["双手正握单杠，握距与肩同宽。", "抬起双脚，让身体笔直、放松地悬挂。", "肩膀稍微用力，慢慢呼吸 30 秒。", "轻轻踩回地面，休息 30 到 60 秒，再做，共 3 组。"], ["悬挂时晃动身体或踢腿。", "直接从单杠上跳下来，而不是轻轻踩回地面。"], "先从短一点的时间开始，每周加几秒。"),
    "bird_dog": ExerciseGuide(["四肢着地，双手在肩膀正下方，膝盖在髋部正下方。", "一只手向前伸直，同时对侧的腿向后伸直。", "保持髋部水平，停 2 秒，然后还原。", "做 8 次后换边，每侧做 2 组。"], ["抬腿时下背部塌下去。", "为了把腿抬更高，让髋部向外转开。"], "想象下背部放着一杯水，不能洒出来。"),
    "bow_pose": ExerciseGuide(["俯卧，弯曲膝盖，让脚跟靠近臀部。", "手向后伸，抓住双脚脚踝。", "双脚用力蹬向双手，抬起胸口和大腿。", "保持 10 秒，慢慢放下，共 2 组。"], ["膝盖分开得比髋部还宽。", "头往后仰，让颈部太用力。"], "只抬到舒服的高度，如果下背部疼，就跳过这个动作。"),
    "broad_jumps": ExerciseGuide(["双脚与髋同宽，脚尖在一条线后面。", "双臂向后摆，弯曲膝盖，髋部向后坐。", "双臂向前摆，尽量跳远，双脚同时落地。", "落地后稳住 1 秒，走回起点，做 5 次，共 3 组。"], ["落地时身体向前或向后倒。", "落地时膝盖完全伸直锁死。"], "在不打滑的地面上跳，先跳近一点，直到每次都能稳住落地。"),
    "burpees": ExerciseGuide(["站直，然后下蹲，双手撑在地上。", "双脚向后跳，成一条直线的平板支撑。", "双脚跳回，靠近双手。", "向上跳起，做 5 次后休息，共 3 组。"], ["做平板支撑时髋部下沉。", "跳起后双腿伸直，重重落地。"], "想轻松一点，可以用走的方式把脚向后踩再收回，不要跳。动作变形时就放慢。"),
    "calf_pulses": ExerciseGuide(["站直，踮起脚尖，如果需要平衡，指尖可以扶着墙。", "小幅度地上下弹动，只动几厘米。", "整组动作中，脚跟都不要碰到地面。", "持续 20 秒，共 3 组。"], ["弹动之间脚跟碰到地面。", "动作幅度太大，不再是小幅弹动。"], "小腿有灼热感是正常的，如果出现刺痛就停下来。"),
    "calf_raise": ExerciseGuide(["站直，站在墙边，指尖碰着墙保持平衡。", "慢慢踮起脚，尽量踮到最高。", "在最高点停 1 秒，然后慢慢放下脚跟。", "每组做 15 次，共 3 组。"], ["快速弹动，而不是慢慢地动。", "在最高点时脚踝向外翻。"], "刷牙的时候做，很容易养成每天的习惯。"),
    "cat_cow": ExerciseGuide(["双手双膝着地，手腕在肩膀正下方，膝盖在髋部正下方。", "吸气，肚子下沉，抬起胸口和视线（牛式）。", "呼气，弓起背部，收下巴（猫式）。", "配合呼吸慢慢动，做 10 轮，共 2 组。"], ["动作比呼吸快。", "只动脖子，而不是带动整条脊柱。"], "很适合当作早上起床后的第一个动作，或坐久之后用来重新放松。"),
    "chest_stretch": ExerciseGuide(["站在门框里，一只前臂贴在门框上，手肘与肩同高。", "同侧的脚向前迈过门框。", "胸口向前靠，直到肩膀前侧有拉伸感。", "保持 20 秒，换另一侧，每侧做 2 组。"], ["为了靠得更前，让下背部过度拱起。", "耸肩，肩膀往耳朵靠。"], "拉伸要轻柔，如果肩膀有被夹到的感觉，就退回来一点。"),
    "childs_pose": ExerciseGuide(["跪在地上，双脚大脚趾并拢，膝盖分开。", "髋部向后，坐到脚跟上。", "双手向前爬，额头放在地上。", "慢慢呼吸 30 秒后起身，共 2 组。"], ["为了伸得更远，髋部离脚跟太远。", "屏住呼吸，肩膀用力。"], "如果膝盖觉得紧，可以在髋部和脚跟之间放一个靠垫。"),
    "chin_tucks": ExerciseGuide(["坐直或站直，眼睛看向正前方。", "把下巴笔直地向后收，像在做双下巴。", "保持 3 秒，然后放松。", "每组做 8 次，共 2 组。"], ["低头点头，而不是把头向后收。", "收得太用力，让脖子疼。"], "每次放下手机时，都做几次。"),
    "cobra_stretch": ExerciseGuide(["俯卧，双手平放在肩膀正下方。", "用手撑地，慢慢抬起胸口，髋部保持贴地。", "手肘保持微弯，肩膀远离耳朵。", "保持 15 秒，慢慢呼吸，然后有控制地放下。"], ["撑得太高，让下背部有被夹到的感觉。", "耸肩，肩膀往耳朵靠。"], "只抬到舒服的高度，多练习后会慢慢抬得更深。"),
    "dead_bug": ExerciseGuide(["仰卧，双臂向上伸直，膝盖弯曲，停在髋部上方。", "把下背部轻轻压向地面。", "一只手臂向头顶后方放下，同时对侧的腿向地面放下，然后还原。", "每侧做 8 次后休息，共 2 组。"], ["下背部离开地面，拱了起来。", "动作太急。"], "手臂和腿只放到背部还能保持贴地的位置。"),
    "dead_hang_active": ExerciseGuide(["双手正握单杠，握距比肩膀稍宽。", "手臂伸直悬挂，然后把肩胛骨向下、向后拉。", "双腿并拢，核心收紧，保持 20 秒。", "轻轻踩回地面，每组之间休息 40 秒。"], ["弯曲手肘，像在做引体向上。", "耸肩，肩膀往耳朵靠。"], "想象把单杠往远处推，就能感觉到肩膀在用力。"),
    "deadlift_stretch": ExerciseGuide(["双脚与髋同宽，膝盖微弯站立。", "从髋部向前折，双手沿着大腿向下滑。", "背部保持平直，向脚尖伸去，直到腘绳肌有拉伸感。", "夹紧臀部站起来，每组慢慢做 12 次。"], ["为了够得更低，让背部弓起来。", "膝盖完全伸直锁死。"], "动作要慢，控制比伸得多远更重要。"),
    "downward_dog": ExerciseGuide(["双手双膝着地，双手在肩膀正下方。", "把髋部抬高，让身体呈倒 V 形。", "脊柱保持伸长，让脚跟往地面沉。", "保持 20 秒后休息，共 2 组。"], ["为了让脚跟踩下去，让背部弓起来。", "耸肩，肩膀往耳朵靠。"], "如果背部弓起来，就稍微弯一点膝盖。脚跟不一定要碰到地面。"),
    "dumbbell_deadlift": ExerciseGuide(["站直，双手各拿一只哑铃，放在大腿前面。", "膝盖放松，背部保持平直，把髋部向后推。", "让哑铃沿着大腿下滑，到膝盖稍微下方。", "夹紧臀部站起来，做 8 次，共 3 组。"], ["哑铃往下时，背部弓起来。", "膝盖弯得太多，变成了深蹲。"], "选一个够轻的重量，让每一次都能保持标准动作。"),
    "dumbbell_row": ExerciseGuide(["一只手扶在长凳或椅子上，双脚向后退。", "另一只手拿着哑铃，背部保持平直，手臂自然下垂。", "手肘贴近身体，把哑铃拉向髋部，然后慢慢放下。", "每侧做 8 次后休息，共 3 组。"], ["扭转身体，用甩的方式把哑铃拉起来。", "耸肩，肩膀往耳朵靠。"], "选一个够轻的重量，让每一次都能保持标准动作。"),
    "evening_yoga": ExerciseGuide(["双手双膝着地，做猫牛式 60 秒。", "向后坐成婴儿式，手臂向前伸长，呼吸 60 秒。", "撑起成下犬式，脚跟向地面伸去。", "站起来，身体向前折，让头自然下垂。", "每个动作都吸气数 4 拍，呼气数 6 拍。"], ["在动作之间匆匆带过，没有停留。", "硬撑一个动作，直到感到疼痛。"], "做的时候把灯调暗，帮助身体慢慢放松下来。"),
    "farmer_carry": ExerciseGuide(["站在两只哑铃或两个有重物的袋子中间。", "弯曲膝盖，背部保持平直，把它们拿起来。", "小步走，肩膀向后，眼睛看向前方。", "走 20 秒，放下重物后休息，共 3 组。"], ["身体倾向一边，或让肩膀向前含。", "拿起或放下重物时，背部弓起来。"], "选一个够轻的重量，让每一组都能保持标准动作，并且两边要一样重。"),
    "glute_bridge": ExerciseGuide(["仰卧，膝盖弯曲，双脚平放，与髋同宽。", "脚跟用力踩地，把髋部向天花板抬起。", "在最高点夹紧臀部 2 秒。", "慢慢放下，每组做 12 次，共 3 组。"], ["用脚尖发力，而不是用脚跟。", "在最高点时下背部过度拱起。"], "如果是臀部有感觉，而不是下背部，就说明你做对了。"),
    "goblet_squat": ExerciseGuide(["双手把一只哑铃或一个装了重物的背包抱在胸前。", "双脚与肩同宽，脚尖稍微向外。", "在双脚之间坐下去，胸口挺起，然后站起来。", "做 8 次后休息，共 3 组。"], ["膝盖向内塌。", "背部弓起来，胸口掉下去。"], "选一个够轻的重量，让每一次都能保持标准动作。"),
    "hanging_knee_raise": ExerciseGuide(["双手正握单杠，手臂伸直悬挂。", "把肩膀往下拉，远离耳朵。", "不要晃动，把双膝抬到髋部高度，然后慢慢放下。", "做 5 次，踩回地面后休息，共 3 组。"], ["晃动身体，把膝盖甩上去。", "悬挂时肩膀耸到耳朵旁边。"], "悬挂之前先确认单杠很牢固，结束时踩回地面，不要直接跳下来。"),
    "high_knees": ExerciseGuide(["双脚与髋同宽，站直。", "原地跑，每次把膝盖抬到髋部高度。", "用力摆臂，用前脚掌轻轻着地。", "持续 20 秒，共 3 组。"], ["膝盖抬起时身体向后仰。", "用整个脚掌重重踩地。"], "如果喘不过气，就放慢，改成高抬膝的踏步。"),
    "hiit_workout": ExerciseGuide(["原地踏步和绕臂热身 3 分钟。", "做波比跳、登山者和深蹲跳，每个动作 45 秒。", "动作之间休息 15 秒，深呼吸。", "完成 4 轮，然后慢慢走路，直到呼吸平稳。"], ["为了做得更快，让动作变形。", "强度大的时候屏住呼吸。"], "按自己的节奏来，把 4 轮完整做完，比一开始冲得快更重要。"),
    "hip_flexor_stretch": ExerciseGuide(["单膝跪地，另一只脚平放在身体前面。", "骨盆稍微向内收，夹紧后腿那一侧的臀部。", "轻轻向前移，直到髋部前侧有拉伸感。", "慢慢呼吸，保持 30 秒，然后换边。"], ["拱起下背部，而不是收骨盆。", "前面的膝盖超过脚尖。"], "在膝盖下垫一条折好的毛巾，会更舒服。"),
    "inversion_hang": ExerciseGuide(["一定要有大人在旁边，并且使用稳固、检查过的器材，才能倒挂。", "把脚踝牢牢固定好，从稍微倾斜的角度开始，不要一下子完全倒过来。", "手臂放松，慢慢呼吸，最多 1 分钟。", "慢慢回到直立，先坐一会儿再站起来。", "如果感到头晕、头部有压迫感或任何疼痛，立刻停下来。"], ["前几次练习就完全倒挂。", "倒挂后很快站起来。"], "短时间、轻柔的练习就够了，没有必要挂得更久。"),
    "jump_squats": ExerciseGuide(["双脚与肩同宽，胸口挺起。", "向后坐成深蹲，直到大腿差不多与地面平行。", "双脚用力蹬地，笔直向上跳起，再轻轻落回深蹲姿势。", "跳 8 次后休息，再做，共 3 组。"], ["落地时膝盖向内塌。", "落地时双腿僵硬地伸直。"], "尽量安静地落地，当落地的声音变大时，就结束这一组。"),
    "jumping": ExerciseGuide(["双脚与髋同宽站立，双臂放松垂在身体两侧。", "弯曲膝盖，摆动双臂，笔直向上跳起。", "用前脚掌轻轻落地，膝盖微弯。", "跳 20 次，休息 30 秒，再做，共 3 组。"], ["双腿僵直，用脚跟落地。", "落地时膝盖向内塌。"], "落地安静代表控制得好，试着像猫一样落地。"),
    "knee_circles": ExerciseGuide(["双脚并拢站立，膝盖稍微弯曲。", "双手放在膝盖上。", "用膝盖朝一个方向慢慢画小圈，持续 15 秒。", "换方向，再朝另一个方向做 15 秒。"], ["画很大的圈，扭到膝盖。", "所有圈都朝同一个方向画。"], "可以当作跳跃或跑步之前的热身。"),
    "legs_up_wall": ExerciseGuide(["侧坐在墙边，一侧髋部贴着墙。", "躺下的同时，把双腿甩上墙。", "双臂放在身体两侧，让双腿放松地靠着墙。", "保持 3 分钟，慢慢呼吸。"], ["下背部离开地面。", "膝盖用力锁死，腿部紧绷。"], "如果腿后侧觉得紧，就把髋部稍微离墙远一点。"),
    "low_lunge_arch": ExerciseGuide(["一只脚向前迈一步，后面那条腿的膝盖放到地上。", "髋部向前滑，直到后腿髋部前侧有拉伸感。", "双臂向上伸，胸口抬起，轻轻向后拱。", "保持 20 秒，换腿，每侧做 2 组。"], ["前面的膝盖远远超过脚尖。", "只从下背部往后弯。"], "在后面的膝盖下垫一条折好的毛巾，后拱的幅度要小。"),
    "lunges": ExerciseGuide(["双脚与髋同宽，站直。", "向前迈一大步，往下蹲，直到两个膝盖都弯到大约 90 度。", "用前脚脚跟发力，退回起点。", "每条腿做 8 次，然后休息，共 3 组。"], ["前面的膝盖向内塌。", "胸口大幅度向前倾，压在前腿上。"], "先把步子迈小一点，或扶着椅子保持平衡，直到动作稳了再加大。"),
    "masai_jumps": ExerciseGuide(["站直，双臂放在身体两侧，或向上伸直。", "做小幅度有弹性的跳跃，整个过程身体保持直立。", "用前脚掌轻轻落地，膝盖微弯。", "持续 20 秒，共 3 组。"], ["用脚跟重重落地。", "累了以后身体向前塌。"], "如果膝盖或小腿前侧疼，就停下来，休息后再试。"),
    "morning_stretch": ExerciseGuide(["站直，慢慢转动脖子，每个方向转 5 圈。", "双臂举过头顶，十指交扣，向上伸展 30 秒。", "从髋部向前折，让双手向脚尖自然下垂。", "迈步成弓步，保持 30 秒，然后换腿。", "用鼻子慢慢呼吸，拉伸时不要弹震。"], ["弹震着往下压，而不是稳稳地停住。", "保持时屏住呼吸。"], "起床后先拉伸，再看手机，这个习惯会更容易养成。"),
    "mountain_pose": ExerciseGuide(["双脚并拢站立，体重平均放在两只脚上。", "双臂笔直举过头顶，掌心相对。", "踮起脚尖，从指尖向上伸展。", "保持 20 秒后慢慢放下，共 2 组。"], ["肋骨外翻，下背部拱起。", "耸肩，肩膀往耳朵靠。"], "眼睛盯着前方的一个点，如果站不稳，就把脚跟放在地上。"),
    "neck_stretches": ExerciseGuide(["坐直或站直，肩膀放松、下沉。", "耳朵慢慢向一侧肩膀倾斜，每侧保持 30 秒。", "下巴向胸口靠近，保持 30 秒。", "轻轻抬高视线 30 秒，头不要往后仰。"], ["用手用力拉头。", "肩膀向上抬去碰耳朵。"], "久坐学习之后做这些动作，可以释放紧绷。"),
    "overhead_press": ExerciseGuide(["站直，在肩膀高度握住轻哑铃或水瓶。", "核心收紧，双臂笔直向上推过头顶。", "推到手臂贴在耳朵两侧，然后慢慢放回肩膀。", "推的时候呼气，放下的时候吸气，每组做 10 次。"], ["推的时候下背部拱起。", "用的重量太重，控制不住。"], "先从徒手开始，等动作轻松了再加轻重量。"),
    "pelvic_shift": ExerciseGuide(["仰卧，膝盖弯曲，双脚平放在地上。", "收起尾骨，让脊柱从下往上，一节一节离开地面。", "在最高点停一下，然后慢慢放下，一节椎骨一节椎骨地落回地面。", "慢慢做 10 次后休息，共 2 组。"], ["髋部快速整块地推上去。", "在最高点时下背部拱起。"], "动作要慢，慢到能感觉到背部每一段碰到地面。"),
    "pilates_core": ExerciseGuide(["做前臂平板支撑 1 分钟，身体保持一条直线。", "仰卧做死虫式，对侧的手和腿慢慢放下。", "换成双手双膝着地的鸟狗式，伸出对侧的手和腿。", "最后做 1 分钟臀桥和 1 分钟抬腿。", "每次收紧核心时都要呼气。"], ["做平板支撑时髋部下沉。", "做死虫式时下背部离开地面，拱了起来。"], "慢而有控制比快更好，每一次标准的动作都在建立真正的力量。"),
    "pilates_roll_over": ExerciseGuide(["仰卧，双臂放在身体两侧，双腿笔直向上举。", "双臂压向地面，抬起髋部，把双腿翻到头顶。", "双腿在头后方与地面平行时就停下。", "慢慢滚回来，做 5 次后休息，共 2 组。"], ["借着惯性把双腿甩过去。", "压在脖子上，而不是压在肩膀上。"], "重量要放在肩膀上，绝对不要压在脖子上，想轻松一点可以弯曲膝盖。"),
    "plank": ExerciseGuide(["前臂放在地上，手肘在肩膀正下方。", "双脚向后退，让身体成一条直线。", "夹紧臀部，收紧肚脐，保持 30 秒。", "休息 30 秒，再做，共 3 组。"], ["髋部向地面下沉。", "髋部翘得太高。"], "越来越轻松时，每周加 5 秒。"),
    "pogo_jumps": ExerciseGuide(["站直，双脚与髋同宽，双手叉腰。", "用前脚掌弹跳，膝盖几乎伸直。", "每次着地的时间都要短而快，像跳跳杆一样。", "持续 20 秒，共 3 组。"], ["每次弹跳都把膝盖弯得很深。", "脚跟重重砸向地面。"], "在坚硬平坦的地面上跳，如果小腿前侧或脚踝疼，就停下来。"),
    "posture_check": ExerciseGuide(["设一个每小时的提醒，检查自己是怎么坐或站的。", "让耳朵在肩膀正上方，肩膀在髋部正上方。", "肩膀向后、向下转，胸口轻轻打开。", "想象有一根线把头顶向上拉，然后呼吸。"], ["矫枉过正，背部僵硬地拱起。", "低头看手机，头向前探。"], "把屏幕调到与视线同高，好体态就会变得自然而然。"),
    "pre_sleep_routine": ExerciseGuide(["睡前 30 分钟开始：调暗灯光，把屏幕收起来。", "看书或听舒缓的音乐 15 分钟。", "在床上或地上做 5 分钟轻柔的拉伸。", "吸气 4 秒，呼气 6 秒，做 10 轮。"], ["再多滑一分钟手机。", "每天晚上的就寝时间变来变去。"], "每晚同一时间、同样的步骤，会让你更容易入睡。"),
    "pull_ups": ExerciseGuide(["双手正握单杠，握距比肩膀稍宽。", "从手臂伸直的悬挂开始，把肩胛骨向下拉。", "向上拉，直到下巴超过单杠，然后慢慢放低身体。", "做 2 次，踩回地面后休息，共 3 组。"], ["踢腿、晃动身体，想借力过杠。", "快速掉下来，而不是有控制地慢慢放下。"], "可以把弹力带套在脚下，或跳到最高点再慢慢放下，并确认单杠很牢固。"),
    "puppy_pose": ExerciseGuide(["四肢着地，髋部在膝盖正上方。", "双手向前爬，髋部保持原地不动。", "让胸口和额头向地面沉。", "保持 20 秒后起身，共 2 组。"], ["髋部向后滑向脚跟。", "弯曲手肘，让手肘撑在地上。"], "如果肩膀的拉伸感太强，可以把额头放在靠垫上。"),
    "push_ups": ExerciseGuide(["双手放在地上，比肩膀稍宽。", "双脚向后退，让身体成一条直线。", "弯曲手肘，让胸口压向地面，然后撑起来。", "做 5 次后休息，共 3 组。"], ["髋部向地面下沉。", "手肘直直地向两侧张开。"], "想轻松一点，可以跪着做，或把双手放在长凳上。"),
    "scapular_pull": ExerciseGuide(["双手正握单杠，握距比肩膀稍宽。", "手臂伸直悬挂，让肩膀向耳朵靠近。", "把肩胛骨向下拉，让身体微微上提，手肘保持伸直。", "停 1 秒后放松，做 5 次，共 3 组。"], ["弯曲手肘，想拉得更高。", "摆腿来借力。"], "先确认单杠很牢固，如果完全悬挂太难，脚可以踩在箱子上。"),
    "scapular_retraction": ExerciseGuide(["坐直或站直，双臂放松垂在身体两侧。", "把肩胛骨向后、向下拉，像要把它们塞进后裤袋。", "夹紧保持一次缓慢的呼吸，然后放松。", "做 10 次后休息，共 2 组。"], ["夹的时候耸肩。", "肋骨向前顶，背部拱起。"], "整个过程中，下巴保持水平，脖子放松。"),
    "seated_forward_fold": ExerciseGuide(["坐在地上，双腿伸直，脚尖朝上。", "坐直，双臂举过头顶。", "从髋部向前折，伸手去够小腿或脚。", "保持 20 秒后坐直，共 2 组。"], ["为了摸到脚尖，让上背部弓起来。", "弹震着往下压，想拉得更深。"], "如果下背部弓起来，可以稍微弯一点膝盖，或者坐在折好的毛巾上。"),
    "shoulder_rolls": ExerciseGuide(["站直，双臂自然垂在身体两侧。", "双肩向前画大圈，做 15 次。", "再向后画 15 次，同时把肩胛骨夹紧。", "双手在背后交扣，打开胸口 20 秒。"], ["画很小、很匆忙的圈。", "耸肩的同时屏住呼吸。"], "在课间或学习的空档快速做一组，能让肩膀保持打开。"),
    "side_plank": ExerciseGuide(["侧卧，前臂撑在地上，手肘在肩膀正下方。", "双脚叠在一起，把髋部抬离地面。", "从头到脚跟，身体保持一条直线。", "保持 15 秒，换另一侧，每侧做 2 组。"], ["髋部向地面下掉。", "胸口向前朝地面转。"], "下面那个膝盖可以放在地上，会更轻松。"),
    "single_leg_calf_raise": ExerciseGuide(["前脚掌站在台阶边缘，用一只脚站稳，手扶着墙或栏杆。", "让脚跟慢慢降到台阶高度以下。", "尽量踮到最高，停 1 秒。", "每条腿做 8 次，然后休息，共 3 组。"], ["从最低点弹起来，而不是慢慢地动。", "弯曲膝盖来帮助小腿发力。"], "先从自己的体重开始，如果加哑铃或背包，要选一个够轻的重量，让每一次都能保持标准动作。"),
    "single_leg_hops": ExerciseGuide(["用一条腿站立，另一只脚向后抬起。", "原地做小幅度的跳，用前脚掌落地。", "保持髋部水平，站立腿的膝盖微弯。", "跳 8 次，换腿，每侧做 2 组。"], ["跳的那条腿，膝盖向内塌。", "跳得太高，失去平衡。"], "站在伸手能碰到的墙边，先跳低一点，直到平衡感稳定。"),
    "skipping_rope": ExerciseGuide(["在髋部高度握住把手，手肘贴近身体两侧。", "用手腕转动绳子，不要整条手臂一起转。", "跳的高度刚好让绳子能过去，用前脚掌落地。", "跳 5 分钟，休息 1 分钟，再做，共 3 组。"], ["跳得太高，很快就累了。", "用脚跟平脚落地。"], "绊到绳子是正常的，重新开始，继续保持节奏。"),
    "spinal_twist": ExerciseGuide(["仰卧，双臂向两侧打开。", "弯曲一边膝盖，让它越过身体向地面放下。", "双肩保持贴地，视线看向相反的一侧。", "保持 20 秒，换另一侧，每侧做 2 组。"], ["对侧的肩膀离开地面。", "用手硬把膝盖压下去。"], "如果膝盖碰不到地面，可以把它放在靠垫上。"),
    "sprint_intervals": ExerciseGuide(["先慢跑 5 分钟，再做腿部摆动来热身。", "全力冲刺 30 秒，用力摆臂。", "用走路或慢跑的方式恢复 90 秒。", "总共冲刺 3 次，然后走路 5 分钟来放松。"], ["没有热身就冲刺。", "身体后仰、步子迈太大，而不是向前推进。"], "选平坦、安全的地面，只有在状态好的时候才全力冲刺。"),
    "squats": ExerciseGuide(["双脚与肩同宽，脚尖稍微向外。", "髋部向后推，往下蹲，直到大腿与地面平行。", "胸口挺起，膝盖与脚尖方向一致。", "用脚跟发力站起来，起身时呼气。"], ["脚跟离开地面。", "蹲到最低点时背部弓起来。"], "前几组可以对着镜子做，检查动作是否标准。"),
    "standing_side_stretch": ExerciseGuide(["双脚与髋同宽，站直。", "双臂举过头顶，一只手握住另一只手的手腕。", "慢慢向一侧倾斜，双脚保持踩紧地面。", "保持 15 秒，换另一侧，每侧做 2 组。"], ["向前倾或扭转，而不是笔直地向侧面弯。", "髋部向外顶得太远。"], "想象自己站在两面墙中间，只能向侧面移动。"),
    "step_ups": ExerciseGuide(["站在台阶或牢固的矮长凳前面。", "把一整只脚踩在台阶上，向上撑起，直到站直。", "另一只脚慢慢放回地面。", "每条腿做 8 次，然后休息，共 3 组。"], ["用地上那只脚用力蹬地借力。", "快速掉下来，而不是有控制地慢慢放下。"], "用不会滑动也不会翻倒的台阶，先从矮的开始，再慢慢加高。"),
    "superman": ExerciseGuide(["俯卧，双臂向前伸直。", "把手臂和双腿稍微抬离地面。", "脖子保持伸长，看向地面，停 2 秒。", "慢慢放下，每组做 8 次，共 2 组。"], ["用力把胸口和双腿抬到最高。", "头向上抬，挤压脖子。"], "抬一点点就够了，如果下背部有被夹到的感觉，就抬得更低一点。"),
    "swimming_basketball": ExerciseGuide(["用轻松的游几圈或轻轻运球热身 5 分钟。", "用稳定的节奏游泳或打球，至少 30 分钟。", "每次划水、投篮或抢篮板，都要充分伸展。", "用 5 分钟轻松的活动和拉伸来放松。"], ["没有热身，一开始就全速。", "运动的时候忘记喝水。"], "找个朋友一起，运动有伴更容易坚持下去。"),
    "table_top": ExerciseGuide(["坐下，膝盖弯曲，双脚平放，双手撑在髋部后面的地上。", "手指朝向脚的方向，用手和脚一起撑起。", "抬起髋部，直到从膝盖到肩膀成一个平面。", "保持 15 秒后放下，共 2 组。"], ["髋部中间下沉。", "头向后仰，让脖子很吃力。"], "如果手腕觉得酸痛，可以把手指转向两侧。"),
    "thoracic_extension": ExerciseGuide(["坐在牢固的椅子上，椅背顶端刚好在肩胛骨下方。", "双手放在脑后，手肘向两侧打开。", "上背部慢慢靠着椅背向后仰，眼睛看向上方。", "回到起始位置，做 8 次后休息，共 2 组。"], ["从下背部弯曲，而不是从上背部。", "用手把头向前拉。"], "用不会滑动也不会翻倒的椅子，双脚平放在地上。"),
    "toe_touch": ExerciseGuide(["双脚与髋同宽，膝盖放松。", "从髋部向前折，让双手向脚尖伸去。", "保持不动 20 秒，慢慢呼吸。", "慢慢卷起身体，休息后再做一次。"], ["弹震着往下压，想够得更远。", "膝盖完全伸直锁死。"], "如果摸不到脚尖，到小腿就可以了，一样有效果。"),
    "tuck_jumps": ExerciseGuide(["双脚与髋同宽，站直。", "快速下蹲四分之一，然后尽量跳高。", "在最高点把双膝拉向胸口，再用弯曲的膝盖轻轻落地。", "跳 6 次，休息后再做，共 3 组。"], ["弯腰让胸口去碰膝盖，而不是把膝盖抬起来。", "双腿伸直，重重落地。"], "每次跳之间先稳住平衡，并确保周围有足够空间，地面不会打滑。"),
    "upward_salute": ExerciseGuide(["双脚并拢站立，双臂放在身体两侧。", "吸气，双臂向上举过头顶。", "肋骨保持收住，肩膀远离耳朵。", "保持 15 秒，慢慢呼吸，然后放下手臂。共 2 组。"], ["身体后仰，下背部拱起。", "肋骨向前顶出。"], "向上伸，不是向后仰，让身体叠在双脚正上方。"),
    "wall_angels": ExerciseGuide(["背靠着墙站立，双脚稍微放在身体前方。", "手臂贴在墙上，手肘弯曲，像球门柱一样。", "肋骨保持收住，手臂慢慢向上滑，再滑回来。", "每组慢慢做 8 次，共 2 组。"], ["肋骨外翻，下背部拱起。", "手臂离开墙面。"], "只滑到手臂还能贴着墙的高度，练习多了会越来越轻松。"),
    "wall_dog": ExerciseGuide(["面对墙壁站立，距离大约一条腿的长度。", "双手放在墙上，与髋同高。", "从髋部向后坐，直到手臂伸直、脊柱伸长。", "慢慢呼吸，保持 20 秒，共 2 组。"], ["上背部弓起来。", "弯曲手肘，整个人靠在墙上。"], "在书桌前不方便趴到地上时，这是很好的休息动作。"),
    "wall_sit": ExerciseGuide(["背靠着墙站立，双脚在身体前方一步远的位置。", "沿着墙往下滑，直到大腿与地面平行。", "膝盖保持在脚踝正上方，整个背部贴着墙。", "保持 20 秒后站起来，共 3 组。"], ["把手放在大腿上。", "膝盖向前超过脚尖。"], "如果膝盖不舒服，就坐高一点，变强以后再往下蹲得更低。"),
    "wall_stand": ExerciseGuide(["脚跟靠着墙站立，双脚与髋同宽。", "让臀部、肩胛骨和后脑勺都碰到墙。", "下巴稍微收一点，双臂放松垂在身体两侧。", "保持 5 分钟，用鼻子平静地呼吸。"], ["下背部远远地拱离墙面。", "下巴往上抬，而不是保持水平。"], "感受一下这种感觉，然后试着把它带进一天的生活中。"),
  },
  "zh_Hant": {
    "band_pull_apart": ExerciseGuide(["站直，雙手握住彈力帶放在身前，手臂伸直，與肩同高。", "夾緊肩胛骨，把彈力帶往兩側拉開。", "讓彈力帶碰到胸口，然後慢慢還原。", "做 12 下後休息，共 2 組。"], ["聳肩，肩膀往耳朵靠。", "彈力帶直接彈回去，而不是慢慢還原。"], "選一條夠輕的彈力帶，讓每一下都能維持標準動作，使用前先檢查有沒有破損。"),
    "bar_hanging": ExerciseGuide(["雙手正握單槓，握距與肩同寬。", "抬起雙腳，讓身體筆直、放鬆地懸吊。", "肩膀稍微用力，慢慢呼吸 30 秒。", "輕輕踩回地面，休息 30 到 60 秒，再做，共 3 組。"], ["懸吊時晃動身體或踢腿。", "直接從單槓上跳下來，而不是輕輕踩回地面。"], "先從短一點的時間開始，每週多加幾秒。"),
    "bird_dog": ExerciseGuide(["四足跪姿，雙手在肩膀正下方，膝蓋在髖部正下方。", "一隻手往前伸直，同時對側的腿往後伸直。", "保持髖部水平，停 2 秒，然後還原。", "做 8 下後換邊，每邊做 2 組。"], ["抬腿時下背部塌下去。", "為了把腿抬更高，讓髖部往外轉開。"], "想像下背部放著一杯水，不能灑出來。"),
    "bow_pose": ExerciseGuide(["趴下，彎曲膝蓋，讓腳跟靠近臀部。", "手往後伸，抓住雙腳腳踝。", "雙腳用力蹬向雙手，抬起胸口和大腿。", "維持 10 秒，慢慢放下，共 2 組。"], ["膝蓋分開得比髖部還寬。", "頭往後仰，讓頸部太用力。"], "只抬到舒服的高度，如果下背部會痛，就跳過這個動作。"),
    "broad_jumps": ExerciseGuide(["雙腳與髖同寬，腳尖在一條線後面。", "雙臂往後擺，彎曲膝蓋，髖部往後坐。", "雙臂往前擺，盡量跳遠，雙腳同時落地。", "落地後穩住 1 秒，走回起點，做 5 下，共 3 組。"], ["落地時身體往前或往後倒。", "落地時膝蓋完全伸直鎖死。"], "在不會打滑的地面上跳，先跳近一點，直到每次都能穩住落地。"),
    "burpees": ExerciseGuide(["站直，然後蹲下，雙手撐在地上。", "雙腳往後跳，呈一直線的棒式。", "雙腳跳回，靠近雙手。", "往上跳起，做 5 下後休息，共 3 組。"], ["做棒式時髖部下沉。", "跳起後雙腿伸直，重重落地。"], "想輕鬆一點，可以用走的方式把腳往後踩再收回，不要跳。動作變形時就放慢。"),
    "calf_pulses": ExerciseGuide(["站直，踮起腳尖，如果需要平衡，指尖可以扶著牆。", "小幅度地上下彈動，只動幾公分。", "整組動作中，腳跟都不要碰到地面。", "持續 20 秒，共 3 組。"], ["彈動之間腳跟碰到地面。", "動作幅度太大，不再是小幅彈動。"], "小腿有灼熱感是正常的，如果出現刺痛就停下來。"),
    "calf_raise": ExerciseGuide(["站直，站在牆邊，指尖碰著牆保持平衡。", "慢慢踮起腳，盡量踮到最高。", "在最高點停 1 秒，然後慢慢放下腳跟。", "每組做 15 下，共 3 組。"], ["快速彈動，而不是慢慢地動。", "在最高點時腳踝往外翻。"], "刷牙的時候做，很容易養成每天的習慣。"),
    "cat_cow": ExerciseGuide(["四足跪姿，手腕在肩膀正下方，膝蓋在髖部正下方。", "吸氣，肚子下沉，抬起胸口和視線（牛式）。", "吐氣，弓起背部，收下巴（貓式）。", "配合呼吸慢慢動，做 10 輪，共 2 組。"], ["動作比呼吸快。", "只動脖子，而不是帶動整條脊椎。"], "很適合當作早上起床後的第一個動作，或坐久之後用來重新放鬆。"),
    "chest_stretch": ExerciseGuide(["站在門框裡，一隻前臂貼在門框上，手肘與肩同高。", "同側的腳往前跨過門框。", "胸口往前靠，直到肩膀前側有伸展感。", "維持 20 秒，換邊，每邊做 2 組。"], ["為了靠得更前，讓下背部過度拱起。", "聳肩，肩膀往耳朵靠。"], "伸展要輕柔，如果肩膀有被夾到的感覺，就退回來一點。"),
    "childs_pose": ExerciseGuide(["跪在地上，雙腳大腳趾併攏，膝蓋分開。", "髖部往後，坐到腳跟上。", "雙手往前爬，額頭放在地上。", "慢慢呼吸 30 秒後起身，共 2 組。"], ["為了伸得更遠，髖部離腳跟太遠。", "憋氣，肩膀用力。"], "如果膝蓋覺得緊，可以在髖部和腳跟之間放一個抱枕。"),
    "chin_tucks": ExerciseGuide(["坐直或站直，眼睛看向正前方。", "把下巴筆直地往後收，像在做出雙下巴。", "維持 3 秒，然後放鬆。", "每組做 8 下，共 2 組。"], ["低頭點頭，而不是把頭往後收。", "收得太用力，讓脖子痠痛。"], "每次放下手機時，都做幾下。"),
    "cobra_stretch": ExerciseGuide(["趴下，雙手平放在肩膀正下方。", "用手撐地，慢慢抬起胸口，髖部保持貼地。", "手肘保持微彎，肩膀遠離耳朵。", "維持 15 秒，慢慢呼吸，然後有控制地放下。"], ["撐得太高，讓下背部有被夾到的感覺。", "聳肩，肩膀往耳朵靠。"], "只抬到舒服的高度，多練習後會慢慢抬得更深。"),
    "dead_bug": ExerciseGuide(["平躺，雙臂往上伸直，膝蓋彎曲，停在髖部上方。", "把下背部輕輕壓向地面。", "一隻手臂往頭頂後方放下，同時對側的腿往地面放下，然後還原。", "每邊做 8 下後休息，共 2 組。"], ["下背部離開地面，拱了起來。", "動作太急。"], "手臂和腿只放到背部還能維持貼地的位置。"),
    "dead_hang_active": ExerciseGuide(["雙手正握單槓，握距比肩膀稍寬。", "手臂伸直懸吊，然後把肩胛骨往下、往後拉。", "雙腿併攏，核心收緊，維持 20 秒。", "輕輕踩回地面，每組之間休息 40 秒。"], ["彎曲手肘，像在做引體向上。", "聳肩，肩膀往耳朵靠。"], "想像把單槓往遠處推，就能感覺到肩膀在用力。"),
    "deadlift_stretch": ExerciseGuide(["雙腳與髖同寬，膝蓋微彎站立。", "從髖部往前折，雙手沿著大腿往下滑。", "背部保持平直，往腳尖伸去，直到腿後肌有伸展感。", "夾緊臀部站起來，每組慢慢做 12 下。"], ["為了搆得更低，讓背部弓起來。", "膝蓋完全伸直鎖死。"], "動作要慢，控制比伸得多遠更重要。"),
    "downward_dog": ExerciseGuide(["四足跪姿，雙手在肩膀正下方。", "把髖部抬高，讓身體呈倒 V 字形。", "脊椎保持伸長，讓腳跟往地面沉。", "維持 20 秒後休息，共 2 組。"], ["為了讓腳跟踩下去，讓背部弓起來。", "聳肩，肩膀往耳朵靠。"], "如果背部弓起來，就稍微彎一點膝蓋。腳跟不一定要碰到地面。"),
    "dumbbell_deadlift": ExerciseGuide(["站直，雙手各拿一支啞鈴，放在大腿前面。", "膝蓋放鬆，背部保持平直，把髖部往後推。", "讓啞鈴沿著大腿下滑，到膝蓋稍微下方。", "夾緊臀部站起來，做 8 下，共 3 組。"], ["啞鈴往下時，背部弓起來。", "膝蓋彎得太多，變成了深蹲。"], "選一個夠輕的重量，讓每一下都能維持標準動作。"),
    "dumbbell_row": ExerciseGuide(["一隻手扶在長椅或椅子上，雙腳往後退。", "另一隻手拿著啞鈴，背部保持平直，手臂自然下垂。", "手肘貼近身體，把啞鈴拉向髖部，然後慢慢放下。", "每邊做 8 下後休息，共 3 組。"], ["扭轉身體，用甩的方式把啞鈴拉起來。", "聳肩，肩膀往耳朵靠。"], "選一個夠輕的重量，讓每一下都能維持標準動作。"),
    "evening_yoga": ExerciseGuide(["四足跪姿，做貓牛式 60 秒。", "往後坐成嬰兒式，手臂往前伸長，呼吸 60 秒。", "撐起成下犬式，腳跟往地面伸去。", "站起來，身體往前折，讓頭自然下垂。", "每個動作都吸氣數 4 拍，吐氣數 6 拍。"], ["在動作之間匆匆帶過，沒有停留。", "硬撐一個動作，直到感到疼痛。"], "做的時候把燈調暗，幫助身體慢慢放鬆下來。"),
    "farmer_carry": ExerciseGuide(["站在兩支啞鈴或兩個有重物的袋子中間。", "彎曲膝蓋，背部保持平直，把它們拿起來。", "小步走，肩膀往後，眼睛看向前方。", "走 20 秒，放下重物後休息，共 3 組。"], ["身體傾向一邊，或讓肩膀往前圓。", "拿起或放下重物時，背部弓起來。"], "選一個夠輕的重量，讓每一組都能維持標準動作，而且兩邊要一樣重。"),
    "glute_bridge": ExerciseGuide(["平躺，膝蓋彎曲，雙腳平放，與髖同寬。", "腳跟用力踩地，把髖部往天花板抬起。", "在最高點夾緊臀部 2 秒。", "慢慢放下，每組做 12 下，共 3 組。"], ["用腳尖施力，而不是用腳跟。", "在最高點時下背部過度拱起。"], "如果是臀部有感覺，而不是下背部，就代表你做對了。"),
    "goblet_squat": ExerciseGuide(["雙手把一支啞鈴或一個裝了重物的背包抱在胸前。", "雙腳與肩同寬，腳尖稍微朝外。", "在雙腳之間坐下去，胸口挺起，然後站起來。", "做 8 下後休息，共 3 組。"], ["膝蓋往內塌。", "背部弓起來，胸口掉下去。"], "選一個夠輕的重量，讓每一下都能維持標準動作。"),
    "hanging_knee_raise": ExerciseGuide(["雙手正握單槓，手臂伸直懸吊。", "把肩膀往下拉，遠離耳朵。", "不要晃動，把雙膝抬到髖部高度，然後慢慢放下。", "做 5 下，踩回地面後休息，共 3 組。"], ["晃動身體，把膝蓋甩上去。", "懸吊時肩膀聳到耳朵旁邊。"], "懸吊之前先確認單槓很牢固，結束時踩回地面，不要直接跳下來。"),
    "high_knees": ExerciseGuide(["雙腳與髖同寬，站直。", "原地跑，每次把膝蓋抬到髖部高度。", "用力擺臂，用前腳掌輕輕著地。", "持續 20 秒，共 3 組。"], ["膝蓋抬起時身體往後仰。", "用整個腳掌重重踩地。"], "如果喘不過氣，就放慢，改成高抬膝的踏步。"),
    "hiit_workout": ExerciseGuide(["原地踏步和繞臂暖身 3 分鐘。", "做波比跳、登山者和深蹲跳，每個動作 45 秒。", "動作之間休息 15 秒，深呼吸。", "完成 4 輪，然後慢慢走路，直到呼吸平穩。"], ["為了做得更快，讓動作變形。", "強度大的時候憋氣。"], "照自己的節奏來，把 4 輪完整做完，比一開始衝得快更重要。"),
    "hip_flexor_stretch": ExerciseGuide(["單膝跪地，另一隻腳平放在身體前面。", "骨盆稍微往內收，夾緊後腿那一側的臀部。", "輕輕往前移，直到髖部前側有伸展感。", "慢慢呼吸，維持 30 秒，然後換邊。"], ["拱起下背部，而不是收骨盆。", "前面的膝蓋超過腳尖。"], "在膝蓋下墊一條折好的毛巾，會更舒服。"),
    "inversion_hang": ExerciseGuide(["一定要有大人在旁邊，並且使用穩固、檢查過的器材，才能倒掛。", "把腳踝牢牢固定好，從稍微傾斜的角度開始，不要一下子完全倒過來。", "手臂放鬆，慢慢呼吸，最多 1 分鐘。", "慢慢回到直立，先坐一會兒再站起來。", "如果感到頭暈、頭部有壓迫感或任何疼痛，立刻停下來。"], ["前幾次練習就完全倒掛。", "倒掛後很快站起來。"], "短時間、輕柔的練習就夠了，沒有必要掛得更久。"),
    "jump_squats": ExerciseGuide(["雙腳與肩同寬，胸口挺起。", "往後坐成深蹲，直到大腿差不多與地面平行。", "雙腳用力蹬地，筆直往上跳起，再輕輕落回深蹲姿勢。", "跳 8 下後休息，再做，共 3 組。"], ["落地時膝蓋往內塌。", "落地時雙腿僵硬地伸直。"], "盡量安靜地落地，當落地的聲音變大時，就結束這一組。"),
    "jumping": ExerciseGuide(["雙腳與髖同寬站立，雙臂放鬆垂在身體兩側。", "彎曲膝蓋，擺動雙臂，筆直往上跳起。", "用前腳掌輕輕落地，膝蓋微彎。", "跳 20 下，休息 30 秒，再做，共 3 組。"], ["雙腿僵直，用腳跟落地。", "落地時膝蓋往內塌。"], "落地安靜代表控制得好，試著像貓一樣落地。"),
    "knee_circles": ExerciseGuide(["雙腳併攏站立，膝蓋稍微彎曲。", "雙手放在膝蓋上。", "用膝蓋朝一個方向慢慢畫小圈，持續 15 秒。", "換方向，再朝另一個方向做 15 秒。"], ["畫很大的圈，扭到膝蓋。", "所有圈都朝同一個方向畫。"], "可以當作跳躍或跑步之前的暖身。"),
    "legs_up_wall": ExerciseGuide(["側坐在牆邊，一側髖部貼著牆。", "躺下的同時，把雙腿甩上牆。", "雙臂放在身體兩側，讓雙腿放鬆地靠著牆。", "維持 3 分鐘，慢慢呼吸。"], ["下背部離開地面。", "膝蓋用力鎖死，腿部緊繃。"], "如果腿後側覺得緊，就把髖部稍微離牆遠一點。"),
    "low_lunge_arch": ExerciseGuide(["一隻腳往前跨一步，後面那條腿的膝蓋放到地上。", "髖部往前滑，直到後腿髖部前側有伸展感。", "雙臂往上伸，胸口抬起，輕輕往後拱。", "維持 20 秒，換腿，每邊做 2 組。"], ["前面的膝蓋遠遠超過腳尖。", "只從下背部往後彎。"], "在後面的膝蓋下墊一條折好的毛巾，後拱的幅度要小。"),
    "lunges": ExerciseGuide(["雙腳與髖同寬，站直。", "往前跨一大步，往下蹲，直到兩個膝蓋都彎到大約 90 度。", "用前腳腳跟施力，退回起點。", "每條腿做 8 下，然後休息，共 3 組。"], ["前面的膝蓋往內塌。", "胸口大幅度往前傾，壓在前腿上。"], "先把步子跨小一點，或扶著椅子保持平衡，直到動作穩了再加大。"),
    "masai_jumps": ExerciseGuide(["站直，雙臂放在身體兩側，或往上伸直。", "做小幅度有彈性的跳躍，整個過程身體保持直立。", "用前腳掌輕輕落地，膝蓋微彎。", "持續 20 秒，共 3 組。"], ["用腳跟重重落地。", "累了以後身體往前塌。"], "如果膝蓋或小腿前側會痛，就停下來，休息後再試。"),
    "morning_stretch": ExerciseGuide(["站直，慢慢轉動脖子，每個方向轉 5 圈。", "雙臂舉過頭頂，十指交扣，往上伸展 30 秒。", "從髖部往前折，讓雙手往腳尖自然下垂。", "跨步成弓箭步，維持 30 秒，然後換腿。", "用鼻子慢慢呼吸，伸展時不要彈震。"], ["彈震著往下壓，而不是穩穩地停住。", "維持姿勢時憋氣。"], "起床後先伸展，再看手機，這個習慣會更容易養成。"),
    "mountain_pose": ExerciseGuide(["雙腳併攏站立，體重平均放在兩隻腳上。", "雙臂筆直舉過頭頂，掌心相對。", "踮起腳尖，從指尖往上伸展。", "維持 20 秒後慢慢放下，共 2 組。"], ["肋骨外翻，下背部拱起。", "聳肩，肩膀往耳朵靠。"], "眼睛盯著前方的一個點，如果站不穩，就把腳跟放在地上。"),
    "neck_stretches": ExerciseGuide(["坐直或站直，肩膀放鬆、下沉。", "耳朵慢慢往一側肩膀傾斜，每邊維持 30 秒。", "下巴往胸口靠近，維持 30 秒。", "輕輕抬高視線 30 秒，頭不要往後仰。"], ["用手用力拉頭。", "肩膀往上抬去碰耳朵。"], "久坐讀書之後做這些動作，可以釋放緊繃。"),
    "overhead_press": ExerciseGuide(["站直，在肩膀高度握住輕啞鈴或水瓶。", "核心收緊，雙臂筆直往上推過頭頂。", "推到手臂貼在耳朵兩側，然後慢慢放回肩膀。", "推的時候吐氣，放下的時候吸氣，每組做 10 下。"], ["推的時候下背部拱起。", "用的重量太重，控制不住。"], "先從徒手開始，等動作輕鬆了再加輕重量。"),
    "pelvic_shift": ExerciseGuide(["平躺，膝蓋彎曲，雙腳平放在地上。", "收起尾骨，讓脊椎從下往上，一節一節離開地面。", "在最高點停一下，然後慢慢放下，一節脊椎一節脊椎地落回地面。", "慢慢做 10 下後休息，共 2 組。"], ["髖部快速整塊地推上去。", "在最高點時下背部拱起。"], "動作要慢，慢到能感覺到背部每一段碰到地面。"),
    "pilates_core": ExerciseGuide(["做前臂棒式 1 分鐘，身體保持一直線。", "平躺做死蟲式，對側的手和腿慢慢放下。", "換成四足跪姿的鳥狗式，伸出對側的手和腿。", "最後做 1 分鐘臀橋和 1 分鐘抬腿。", "每次收緊核心時都要吐氣。"], ["做棒式時髖部下沉。", "做死蟲式時下背部離開地面，拱了起來。"], "慢而有控制比快更好，每一下標準的動作都在建立真正的力量。"),
    "pilates_roll_over": ExerciseGuide(["平躺，雙臂放在身體兩側，雙腿筆直往上舉。", "雙臂壓向地面，抬起髖部，把雙腿翻到頭頂。", "雙腿在頭後方與地面平行時就停下。", "慢慢滾回來，做 5 下後休息，共 2 組。"], ["藉著慣性把雙腿甩過去。", "壓在脖子上，而不是壓在肩膀上。"], "重量要放在肩膀上，絕對不要壓在脖子上，想輕鬆一點可以彎曲膝蓋。"),
    "plank": ExerciseGuide(["前臂放在地上，手肘在肩膀正下方。", "雙腳往後退，讓身體呈一直線。", "夾緊臀部，收緊肚臍，維持 30 秒。", "休息 30 秒，再做，共 3 組。"], ["髖部往地面下沉。", "髖部翹得太高。"], "越來越輕鬆時，每週加 5 秒。"),
    "pogo_jumps": ExerciseGuide(["站直，雙腳與髖同寬，雙手叉腰。", "用前腳掌彈跳，膝蓋幾乎伸直。", "每次著地的時間都要短而快，像彈跳桿一樣。", "持續 20 秒，共 3 組。"], ["每次彈跳都把膝蓋彎得很深。", "腳跟重重砸向地面。"], "在堅硬平坦的地面上跳，如果小腿前側或腳踝會痛，就停下來。"),
    "posture_check": ExerciseGuide(["設一個每小時的提醒，檢查自己是怎麼坐或站的。", "讓耳朵在肩膀正上方，肩膀在髖部正上方。", "肩膀往後、往下轉，胸口輕輕打開。", "想像有一條線把頭頂往上拉，然後呼吸。"], ["矯枉過正，背部僵硬地拱起。", "低頭看手機，頭往前探。"], "把螢幕調到與視線同高，好體態就會變得自然而然。"),
    "pre_sleep_routine": ExerciseGuide(["睡前 30 分鐘開始：調暗燈光，把螢幕收起來。", "看書或聽舒緩的音樂 15 分鐘。", "在床上或地上做 5 分鐘輕柔的伸展。", "吸氣 4 秒，吐氣 6 秒，做 10 輪。"], ["再多滑一分鐘手機。", "每天晚上的就寢時間變來變去。"], "每晚同一時間、同樣的步驟，會讓你更容易入睡。"),
    "pull_ups": ExerciseGuide(["雙手正握單槓，握距比肩膀稍寬。", "從手臂伸直的懸吊開始，把肩胛骨往下拉。", "往上拉，直到下巴超過單槓，然後慢慢放低身體。", "做 2 下，踩回地面後休息，共 3 組。"], ["踢腿、晃動身體，想借力過槓。", "快速掉下來，而不是有控制地慢慢放下。"], "可以把彈力帶套在腳下，或跳到最高點再慢慢放下，並確認單槓很牢固。"),
    "puppy_pose": ExerciseGuide(["四足跪姿，髖部在膝蓋正上方。", "雙手往前爬，髖部保持原地不動。", "讓胸口和額頭往地面沉。", "維持 20 秒後起身，共 2 組。"], ["髖部往後滑向腳跟。", "彎曲手肘，讓手肘撐在地上。"], "如果肩膀的伸展感太強，可以把額頭放在抱枕上。"),
    "push_ups": ExerciseGuide(["雙手放在地上，比肩膀稍寬。", "雙腳往後退，讓身體呈一直線。", "彎曲手肘，讓胸口壓向地面，然後撐起來。", "做 5 下後休息，共 3 組。"], ["髖部往地面下沉。", "手肘直直地往兩側張開。"], "想輕鬆一點，可以跪著做，或把雙手放在長椅上。"),
    "scapular_pull": ExerciseGuide(["雙手正握單槓，握距比肩膀稍寬。", "手臂伸直懸吊，讓肩膀往耳朵靠近。", "把肩胛骨往下拉，讓身體微微上提，手肘保持伸直。", "停 1 秒後放鬆，做 5 下，共 3 組。"], ["彎曲手肘，想拉得更高。", "擺腿來借力。"], "先確認單槓很牢固，如果完全懸吊太難，腳可以踩在箱子上。"),
    "scapular_retraction": ExerciseGuide(["坐直或站直，雙臂放鬆垂在身體兩側。", "把肩胛骨往後、往下拉，像要把它們塞進後褲袋。", "夾緊維持一次緩慢的呼吸，然後放鬆。", "做 10 下後休息，共 2 組。"], ["夾的時候聳肩。", "肋骨往前頂，背部拱起。"], "整個過程中，下巴保持水平，脖子放鬆。"),
    "seated_forward_fold": ExerciseGuide(["坐在地上，雙腿伸直，腳尖朝上。", "坐直，雙臂舉過頭頂。", "從髖部往前折，伸手去搆小腿或腳。", "維持 20 秒後坐直，共 2 組。"], ["為了摸到腳尖，讓上背部弓起來。", "彈震著往下壓，想伸得更深。"], "如果下背部弓起來，可以稍微彎一點膝蓋，或者坐在折好的毛巾上。"),
    "shoulder_rolls": ExerciseGuide(["站直，雙臂自然垂在身體兩側。", "雙肩往前畫大圈，做 15 下。", "再往後畫 15 下，同時把肩胛骨夾緊。", "雙手在背後交扣，打開胸口 20 秒。"], ["畫很小、很匆忙的圈。", "聳肩的同時憋氣。"], "在下課或讀書的空檔快速做一組，能讓肩膀保持打開。"),
    "side_plank": ExerciseGuide(["側躺，前臂撐在地上，手肘在肩膀正下方。", "雙腳疊在一起，把髖部抬離地面。", "從頭到腳跟，身體保持一直線。", "維持 15 秒，換邊，每邊做 2 組。"], ["髖部往地面下掉。", "胸口往前朝地面轉。"], "下面那個膝蓋可以放在地上，會更輕鬆。"),
    "single_leg_calf_raise": ExerciseGuide(["前腳掌站在台階邊緣，用一隻腳站穩，手扶著牆或欄杆。", "讓腳跟慢慢降到台階高度以下。", "盡量踮到最高，停 1 秒。", "每條腿做 8 下，然後休息，共 3 組。"], ["從最低點彈起來，而不是慢慢地動。", "彎曲膝蓋來幫助小腿施力。"], "先從自己的體重開始，如果加啞鈴或背包，要選一個夠輕的重量，讓每一下都能維持標準動作。"),
    "single_leg_hops": ExerciseGuide(["用一條腿站立，另一隻腳往後抬起。", "原地做小幅度的跳，用前腳掌落地。", "保持髖部水平，站立腿的膝蓋微彎。", "跳 8 下，換腿，每邊做 2 組。"], ["跳的那條腿，膝蓋往內塌。", "跳得太高，失去平衡。"], "站在伸手能碰到的牆邊，先跳低一點，直到平衡感穩定。"),
    "skipping_rope": ExerciseGuide(["在髖部高度握住把手，手肘貼近身體兩側。", "用手腕轉動繩子，不要整條手臂一起轉。", "跳的高度剛好讓繩子能過去，用前腳掌落地。", "跳 5 分鐘，休息 1 分鐘，再做，共 3 組。"], ["跳得太高，很快就累了。", "用腳跟平腳落地。"], "絆到繩子是正常的，重新開始，繼續保持節奏。"),
    "spinal_twist": ExerciseGuide(["平躺，雙臂往兩側打開。", "彎曲一邊膝蓋，讓它越過身體往地面放下。", "雙肩保持貼地，視線看向相反的一側。", "維持 20 秒，換邊，每邊做 2 組。"], ["對側的肩膀離開地面。", "用手硬把膝蓋壓下去。"], "如果膝蓋碰不到地面，可以把它放在抱枕上。"),
    "sprint_intervals": ExerciseGuide(["先慢跑 5 分鐘，再做腿部擺動來暖身。", "全力衝刺 30 秒，用力擺臂。", "用走路或慢跑的方式恢復 90 秒。", "總共衝刺 3 次，然後走路 5 分鐘來放鬆。"], ["沒有暖身就衝刺。", "身體後仰、步子跨太大，而不是往前推進。"], "選平坦、安全的地面，只有在狀態好的時候才全力衝刺。"),
    "squats": ExerciseGuide(["雙腳與肩同寬，腳尖稍微朝外。", "髖部往後推，往下蹲，直到大腿與地面平行。", "胸口挺起，膝蓋與腳尖方向一致。", "用腳跟施力站起來，起身時吐氣。"], ["腳跟離開地面。", "蹲到最低點時背部弓起來。"], "前幾組可以對著鏡子做，檢查動作是否標準。"),
    "standing_side_stretch": ExerciseGuide(["雙腳與髖同寬，站直。", "雙臂舉過頭頂，一隻手握住另一隻手的手腕。", "慢慢往一側傾斜，雙腳保持踩緊地面。", "維持 15 秒，換邊，每邊做 2 組。"], ["往前傾或扭轉，而不是筆直地往側面彎。", "髖部往外頂得太遠。"], "想像自己站在兩面牆中間，只能往側面移動。"),
    "step_ups": ExerciseGuide(["站在台階或牢固的矮長椅前面。", "把一整隻腳踩在台階上，往上撐起，直到站直。", "另一隻腳慢慢放回地面。", "每條腿做 8 下，然後休息，共 3 組。"], ["用地上那隻腳用力蹬地借力。", "快速掉下來，而不是有控制地慢慢放下。"], "用不會滑動也不會翻倒的台階，先從矮的開始，再慢慢加高。"),
    "superman": ExerciseGuide(["趴下，雙臂往前伸直。", "把手臂和雙腿稍微抬離地面。", "脖子保持伸長，看向地面，停 2 秒。", "慢慢放下，每組做 8 下，共 2 組。"], ["用力把胸口和雙腿抬到最高。", "頭往上抬，擠壓脖子。"], "抬一點點就夠了，如果下背部有被夾到的感覺，就抬得更低一點。"),
    "swimming_basketball": ExerciseGuide(["用輕鬆的游幾圈或輕輕運球暖身 5 分鐘。", "用穩定的節奏游泳或打球，至少 30 分鐘。", "每次划水、投籃或搶籃板，都要充分伸展。", "用 5 分鐘輕鬆的活動和伸展來放鬆。"], ["沒有暖身，一開始就全速。", "運動的時候忘記喝水。"], "找個朋友一起，運動有伴更容易堅持下去。"),
    "table_top": ExerciseGuide(["坐下，膝蓋彎曲，雙腳平放，雙手撐在髖部後面的地上。", "手指朝向腳的方向，用手和腳一起撐起。", "抬起髖部，直到從膝蓋到肩膀呈一個平面。", "維持 15 秒後放下，共 2 組。"], ["髖部中間下沉。", "頭往後仰，讓脖子很吃力。"], "如果手腕覺得痠痛，可以把手指轉向兩側。"),
    "thoracic_extension": ExerciseGuide(["坐在牢固的椅子上，椅背頂端剛好在肩胛骨下方。", "雙手放在腦後，手肘往兩側打開。", "上背部慢慢靠著椅背往後仰，眼睛看向上方。", "回到起始位置，做 8 下後休息，共 2 組。"], ["從下背部彎曲，而不是從上背部。", "用手把頭往前拉。"], "用不會滑動也不會翻倒的椅子，雙腳平放在地上。"),
    "toe_touch": ExerciseGuide(["雙腳與髖同寬，膝蓋放鬆。", "從髖部往前折，讓雙手往腳尖伸去。", "保持不動 20 秒，慢慢呼吸。", "慢慢捲起身體，休息後再做一次。"], ["彈震著往下壓，想搆得更遠。", "膝蓋完全伸直鎖死。"], "如果摸不到腳尖，到小腿就可以了，一樣有效果。"),
    "tuck_jumps": ExerciseGuide(["雙腳與髖同寬，站直。", "快速下蹲四分之一，然後盡量跳高。", "在最高點把雙膝拉向胸口，再用彎曲的膝蓋輕輕落地。", "跳 6 下，休息後再做，共 3 組。"], ["彎腰讓胸口去碰膝蓋，而不是把膝蓋抬起來。", "雙腿伸直，重重落地。"], "每次跳之間先穩住平衡，並確保周圍有足夠空間，地面不會打滑。"),
    "upward_salute": ExerciseGuide(["雙腳併攏站立，雙臂放在身體兩側。", "吸氣，雙臂往上舉過頭頂。", "肋骨保持收住，肩膀遠離耳朵。", "維持 15 秒，慢慢呼吸，然後放下手臂。共 2 組。"], ["身體後仰，下背部拱起。", "肋骨往前頂出。"], "往上伸，不是往後仰，讓身體疊在雙腳正上方。"),
    "wall_angels": ExerciseGuide(["背靠著牆站立，雙腳稍微放在身體前方。", "手臂貼在牆上，手肘彎曲，像球門柱一樣。", "肋骨保持收住，手臂慢慢往上滑，再滑回來。", "每組慢慢做 8 下，共 2 組。"], ["肋骨外翻，下背部拱起。", "手臂離開牆面。"], "只滑到手臂還能貼著牆的高度，練習多了會越來越輕鬆。"),
    "wall_dog": ExerciseGuide(["面對牆壁站立，距離大約一條腿的長度。", "雙手放在牆上，與髖同高。", "從髖部往後坐，直到手臂伸直、脊椎伸長。", "慢慢呼吸，維持 20 秒，共 2 組。"], ["上背部弓起來。", "彎曲手肘，整個人靠在牆上。"], "在書桌前不方便趴到地上時，這是很好的休息動作。"),
    "wall_sit": ExerciseGuide(["背靠著牆站立，雙腳在身體前方一步遠的位置。", "沿著牆往下滑，直到大腿與地面平行。", "膝蓋保持在腳踝正上方，整個背部貼著牆。", "維持 20 秒後站起來，共 3 組。"], ["把手放在大腿上。", "膝蓋往前超過腳尖。"], "如果膝蓋不舒服，就坐高一點，變強以後再往下蹲得更低。"),
    "wall_stand": ExerciseGuide(["腳跟靠著牆站立，雙腳與髖同寬。", "讓臀部、肩胛骨和後腦勺都碰到牆。", "下巴稍微收一點，雙臂放鬆垂在身體兩側。", "維持 5 分鐘，用鼻子平靜地呼吸。"], ["下背部遠遠地拱離牆面。", "下巴往上抬，而不是保持水平。"], "感受一下這種感覺，然後試著把它帶進一天的生活中。"),
  },
  "th": {
    "band_pull_apart": ExerciseGuide(["ยืนตัวตรง ถือยางยืดไว้ด้านหน้า แขนเหยียดตรงระดับไหล่", "ดึงยางยืดออกจากกันโดยบีบสะบักเข้าหากัน", "ดึงให้ยางยืดแตะหน้าอก แล้วค่อย ๆ ปล่อยกลับ", "ทำ 12 ครั้งแล้วพัก รวม 2 เซ็ต"], ["ยกไหล่ขึ้นไปทางหู", "ปล่อยให้ยางยืดดีดกลับแทนที่จะค่อย ๆ ปล่อยกลับ"], "เลือกยางยืดที่เบาพอจะทำได้ครบทุกครั้งด้วยท่าที่ถูกต้อง และตรวจก่อนว่ายางไม่ฉีกขาด"),
    "bar_hanging": ExerciseGuide(["จับบาร์แบบคว่ำมือ มือห่างกันเท่าความกว้างไหล่", "ยกเท้าขึ้นแล้วปล่อยให้ตัวห้อยตรงและผ่อนคลาย", "เกร็งไหล่เล็กน้อยและหายใจช้า ๆ เป็นเวลา 30 วินาที", "ลงอย่างนุ่มนวล พัก 30 ถึง 60 วินาที แล้วทำซ้ำรวม 3 เซ็ต"], ["แกว่งตัวหรือเตะขาขณะห้อย", "กระโดดลงจากบาร์แทนที่จะก้าวลงอย่างนุ่มนวล"], "เริ่มจากค้างสั้น ๆ แล้วเพิ่มอีกไม่กี่วินาทีทุกสัปดาห์"),
    "bird_dog": ExerciseGuide(["เริ่มจากท่าคลาน มือวางใต้ไหล่ เข่าอยู่ใต้สะโพก", "เหยียดแขนข้างหนึ่งไปข้างหน้าและขาข้างตรงข้ามตรงไปข้างหลัง", "ค้างไว้สองวินาทีโดยให้สะโพกอยู่ระดับเดียวกัน แล้วกลับท่าเดิม", "ทำ 8 ครั้ง สลับข้าง รวม 2 เซ็ตต่อข้าง"], ["ปล่อยให้หลังส่วนล่างแอ่นลงตอนยกขา", "บิดสะโพกเปิดออกเพื่อยกขาให้สูงขึ้น"], "ลองนึกภาพว่ามีแก้วน้ำวางอยู่บนหลังส่วนล่างและห้ามหก"),
    "bow_pose": ExerciseGuide(["นอนคว่ำและงอเข่าให้ส้นเท้าเข้าใกล้สะโพก", "เอื้อมมือไปข้างหลังจับข้อเท้าทั้งสองข้าง", "ถีบเท้าเข้าหามือเพื่อยกอกและต้นขาขึ้น", "ค้างไว้ 10 วินาทีแล้วลดลงช้า ๆ รวม 2 เซ็ต"], ["ปล่อยให้เข่ากางกว้างกว่าสะโพก", "เงยหัวไปข้างหลังจนคอตึง"], "ยกเท่าที่สบายเท่านั้น และข้ามท่านี้ไปถ้าหลังส่วนล่างเจ็บ"),
    "broad_jumps": ExerciseGuide(["ยืนแยกเท้ากว้างเท่าสะโพก ปลายเท้าอยู่หลังเส้น", "แกว่งแขนไปข้างหลัง งอเข่าและดันสะโพกไปข้างหลัง", "แกว่งแขนไปข้างหน้า กระโดดให้ไกลที่สุดเท่าที่ทำได้ แล้วลงสองเท้าพร้อมกัน", "ลงให้นิ่งหนึ่งวินาที เดินกลับ แล้วกระโดด 5 ครั้ง รวม 3 เซ็ต"], ["ล้มไปข้างหน้าหรือข้างหลังตอนลงพื้น", "ลงพื้นโดยเข่าเหยียดล็อกตรง"], "กระโดดบนพื้นที่ไม่ลื่น และกระโดดสั้นลงจนกว่าจะลงได้นิ่งทุกครั้ง"),
    "burpees": ExerciseGuide(["ยืนตัวตรง แล้วย่อลงสควอตและวางมือบนพื้น", "กระโดดเท้าไปข้างหลังเป็นท่าแพลงก์ที่ตัวตรง", "กระโดดเท้าเข้ามาหามือ", "กระโดดขึ้นตรง ๆ ทำ 5 ครั้งแล้วพัก รวม 3 เซ็ต"], ["ปล่อยให้สะโพกหย่อนตอนอยู่ในท่าแพลงก์", "ลงพื้นแรง ๆ ด้วยขาเหยียดตรงหลังกระโดด"], "ก้าวเท้าไปข้างหลังและกลับมาแทนการกระโดดเพื่อให้ง่ายขึ้น และช้าลงถ้าท่าเริ่มเพี้ยน"),
    "calf_pulses": ExerciseGuide(["ยืนตัวตรงแล้วเขย่งปลายเท้า ใช้ปลายนิ้วแตะผนังถ้าต้องการช่วยทรงตัว", "เด้งขึ้นลงเป็นจังหวะเล็ก ๆ แค่ไม่กี่เซนติเมตร", "ให้ส้นเท้าลอยจากพื้นตลอดทั้งเซ็ต", "ทำต่อเนื่อง 20 วินาที รวม 3 เซ็ต"], ["ปล่อยให้ส้นเท้าแตะพื้นระหว่างจังหวะ", "เด้งใหญ่จนไม่ใช่จังหวะเล็ก ๆ อีกต่อไป"], "อาการแสบร้อนที่น่องเป็นเรื่องปกติ ถ้าปวดแปลบให้หยุด"),
    "calf_raise": ExerciseGuide(["ยืนตัวตรงข้างผนัง ใช้ปลายนิ้วแตะผนังเพื่อทรงตัว", "ค่อย ๆ เขย่งขึ้นบนปลายเท้าให้สูงที่สุดเท่าที่ทำได้", "ค้างไว้ 1 วินาทีข้างบน แล้วค่อย ๆ ลดส้นเท้าลง", "ทำ 15 ครั้งต่อเซ็ต รวม 3 เซ็ต"], ["เด้งเร็ว ๆ แทนที่จะเคลื่อนไหวช้า ๆ", "ปล่อยให้ข้อเท้าล้มออกด้านนอกตอนอยู่ข้างบน"], "ทำตอนแปรงฟันเพื่อสร้างนิสัยง่าย ๆ ในแต่ละวัน"),
    "cat_cow": ExerciseGuide(["เริ่มจากท่าคลาน ข้อมืออยู่ใต้ไหล่ เข่าอยู่ใต้สะโพก", "หายใจเข้า ปล่อยท้องลงและยกอกกับสายตาขึ้น (ท่าวัว)", "หายใจออก โค้งหลังและเก็บคาง (ท่าแมว)", "เคลื่อนไหวช้า ๆ ตามลมหายใจ 10 รอบ รวม 2 เซ็ต"], ["เคลื่อนไหวเร็วกว่าลมหายใจ", "ขยับแค่คอแทนที่จะขยับกระดูกสันหลังทั้งแนว"], "เหมาะเป็นท่าแรกตอนเช้า หรือใช้รีเซ็ตตัวเองหลังนั่งนาน ๆ"),
    "chest_stretch": ExerciseGuide(["ยืนที่ประตู วางแขนท่อนล่างข้างหนึ่งบนวงกบ ข้อศอกอยู่ระดับไหล่", "ก้าวเท้าข้างเดียวกันไปข้างหน้าผ่านประตู", "โน้มอกไปข้างหน้าจนรู้สึกตึงที่ด้านหน้าของไหล่", "ค้างไว้ 20 วินาที สลับข้าง รวม 2 เซ็ตต่อข้าง"], ["แอ่นหลังส่วนล่างเพื่อโน้มตัวให้ไกลขึ้น", "ยกไหล่ขึ้นไปทางหู"], "ยืดเบา ๆ และผ่อนลงถ้ารู้สึกจี๊ดที่ไหล่"),
    "childs_pose": ExerciseGuide(["คุกเข่าบนพื้น นิ้วหัวแม่เท้าชิดกัน เข่าแยกห่างกัน", "ถอยสะโพกลงนั่งบนส้นเท้า", "เดินมือไปข้างหน้าแล้ววางหน้าผากบนพื้น", "หายใจช้า ๆ 30 วินาทีแล้วลุกขึ้น รวม 2 เซ็ต"], ["ยกสะโพกออกห่างจากส้นเท้ามากเพื่อให้เอื้อมได้ไกลขึ้น", "กลั้นหายใจและเกร็งไหล่"], "วางหมอนไว้ระหว่างสะโพกกับส้นเท้าถ้าเข่ารู้สึกตึง"),
    "chin_tucks": ExerciseGuide(["นั่งหรือยืนตัวตรงและมองตรงไปข้างหน้า", "เลื่อนคางตรง ๆ ไปข้างหลัง เหมือนทำให้เกิดคางสองชั้น", "ค้างไว้ 3 วินาทีแล้วผ่อนคลาย", "ทำ 8 ครั้งต่อเซ็ต รวม 2 เซ็ต"], ["พยักหน้าก้มลงแทนที่จะเลื่อนคางไปข้างหลัง", "ดันแรงจนคอเจ็บ"], "ทำสักสองสามครั้งทุกครั้งที่วางโทรศัพท์"),
    "cobra_stretch": ExerciseGuide(["นอนคว่ำ วางฝ่ามือราบใต้ไหล่", "ดันพื้นออกและค่อย ๆ ยกอกขึ้น สะโพกยังติดพื้น", "งอข้อศอกเล็กน้อยและให้ไหล่ห่างจากหู", "ค้างไว้ 15 วินาทีพร้อมหายใจช้า ๆ แล้วลดตัวลงอย่างควบคุม"], ["ดันตัวสูงจนหลังส่วนล่างรู้สึกจี๊ด", "ยกไหล่ขึ้นไปทางหู"], "ยกเท่าที่สบายเท่านั้น เมื่อฝึกบ่อยขึ้นก็จะยืดได้ลึกขึ้น"),
