    "single_leg_calf_raise": ExerciseGuide(["ยืนที่ขอบขั้นบันไดด้วยปลายเท้าข้างเดียว และจับผนังหรือราว", "ค่อย ๆ ลดส้นเท้าให้ต่ำกว่าระดับขั้นบันได", "เขย่งขึ้นบนปลายเท้าให้สูงที่สุดเท่าที่ทำได้ แล้วค้างหนึ่งวินาที", "ทำข้างละ 8 ครั้งแล้วพัก รวม 3 เซ็ต"], ["เด้งตัวขึ้นจากด้านล่างแทนที่จะเคลื่อนไหวช้า ๆ", "งอเข่าเพื่อช่วยน่อง"], "เริ่มด้วยน้ำหนักตัว และถ้าเพิ่มดัมเบลหรือเป้ ให้เลือกน้ำหนักที่เบาพอจะทำได้ครบทุกครั้งด้วยท่าที่ถูกต้อง"),
    "single_leg_hops": ExerciseGuide(["ยืนขาข้างเดียว อีกข้างยกเท้าไปข้างหลัง", "กระโดดเล็ก ๆ อยู่กับที่ ลงบนปลายเท้า", "ให้สะโพกอยู่ระดับเดียวกัน และงอเข่าข้างที่ยืนเล็กน้อย", "กระโดด 8 ครั้ง สลับขา รวม 2 เซ็ตต่อข้าง"], ["ปล่อยให้เข่าข้างที่กระโดดล้มเข้าด้านใน", "กระโดดสูงจนเสียการทรงตัว"], "อยู่ใกล้ผนังที่แตะได้ และกระโดดให้ต่ำไว้จนกว่าการทรงตัวจะมั่นคง"),
    "skipping_rope": ExerciseGuide(["ถือด้ามจับที่ระดับสะโพก ข้อศอกชิดข้างลำตัว", "หมุนเชือกด้วยข้อมือ ไม่ใช่ทั้งแขน", "กระโดดสูงพอให้เชือกผ่านไปได้ ลงบนปลายเท้า", "กระโดดเชือก 5 นาที พัก 1 นาที แล้วทำซ้ำรวม 3 เซ็ต"], ["กระโดดสูงเกินไปจนเหนื่อยเร็ว", "ลงพื้นด้วยเท้าราบบนส้นเท้า"], "สะดุดเป็นเรื่องปกติ แค่เริ่มใหม่และรักษาจังหวะต่อไป"),
    "spinal_twist": ExerciseGuide(["นอนหงาย กางแขนออกไปด้านข้าง", "งอเข่าข้างหนึ่งแล้วพาข้ามลำตัวลงหาพื้น", "ให้ไหล่ทั้งสองข้างติดพื้น และมองไปอีกด้านหนึ่ง", "ค้างไว้ 20 วินาที สลับข้าง รวม 2 เซ็ตต่อข้าง"], ["ปล่อยให้ไหล่ฝั่งตรงข้ามลอยจากพื้น", "ใช้มือกดเข่าให้ลงพื้น"], "วางเข่าบนหมอนถ้าเข่าไม่ถึงพื้น"),
    "sprint_intervals": ExerciseGuide(["วอร์มอัปด้วยการจ็อกเบา ๆ 5 นาทีและแกว่งขา", "วิ่งสปรินต์เต็มแรง 30 วินาที พร้อมแกว่งแขน", "เดินหรือจ็อกช้า ๆ 90 วินาทีเพื่อพักฟื้น", "ทำซ้ำรวม 3 ครั้ง แล้วคูลดาวน์ด้วยการเดิน 5 นาที"], ["วิ่งสปรินต์โดยไม่วอร์มอัปก่อน", "เอนไปข้างหลังและก้าวยาวเกินไป แทนที่จะพุ่งไปข้างหน้า"], "เลือกพื้นที่เรียบและปลอดภัย และวิ่งเต็มแรงเฉพาะตอนที่รู้สึกสดชื่น"),
    "squats": ExerciseGuide(["ยืนแยกเท้ากว้างเท่าไหล่ ปลายเท้าบานออกเล็กน้อย", "ดันสะโพกไปข้างหลังและลดตัวลงจนต้นขาขนานกับพื้น", "ยกอกขึ้นและให้เข่าอยู่แนวเดียวกับปลายเท้า", "ดันที่ส้นเท้าเพื่อยืนขึ้น หายใจออกตอนขึ้น"], ["ยกส้นเท้าลอยจากพื้น", "ก้มหลังโค้งตอนอยู่ข้างล่าง"], "ทำเซ็ตแรก ๆ หน้ากระจกเพื่อเช็กท่าของตัวเอง"),
    "standing_side_stretch": ExerciseGuide(["ยืนตัวตรง แยกเท้ากว้างเท่าสะโพก", "เหยียดแขนทั้งสองเหนือศีรษะและจับข้อมือข้างหนึ่งด้วยมืออีกข้าง", "เอนตัวไปด้านใดด้านหนึ่งช้า ๆ และกดเท้าทั้งสองลงพื้น", "ค้างไว้ 15 วินาที สลับข้าง รวม 2 เซ็ตต่อข้าง"], ["โน้มไปข้างหน้าหรือบิดตัวแทนที่จะเอนไปด้านข้างตรง ๆ", "ดันสะโพกออกด้านข้างมาก"], "ลองนึกว่ายืนอยู่ระหว่างผนังสองด้าน จึงขยับได้แค่ไปด้านข้าง"),
    "step_ups": ExerciseGuide(["ยืนหน้าขั้นบันไดหรือม้านั่งเตี้ยที่แข็งแรง", "วางเท้าข้างหนึ่งทั้งเท้าบนขั้นและดันตัวขึ้นจนยืนตรง", "ค่อย ๆ ลดเท้าอีกข้างลงมาที่พื้น", "ทำข้างละ 8 ครั้งแล้วพัก รวม 3 เซ็ต"], ["ดันตัวแรง ๆ ด้วยเท้าที่อยู่บนพื้น", "ปล่อยตัวลงเร็วแทนที่จะค่อย ๆ ลดอย่างควบคุม"], "ใช้ขั้นที่ไม่ลื่นไถลหรือเอียงล้ม และเริ่มจากขั้นต่ำก่อนค่อยเพิ่มความสูง"),
    "superman": ExerciseGuide(["นอนคว่ำ เหยียดแขนไปข้างหน้า", "ยกแขนและขาขึ้นจากพื้นเล็กน้อย", "ให้คอยาว มองพื้น และค้างไว้ 2 วินาที", "ลดลงช้า ๆ ทำ 8 ครั้งต่อเซ็ต รวม 2 เซ็ต"], ["ฝืนยกอกและขาให้สูงที่สุดเท่าที่ทำได้", "เงยหน้าขึ้นจนคอเกร็ง"], "ยกนิดเดียวก็พอ ถ้าหลังส่วนล่างรู้สึกจี๊ด ให้ยกน้อยลง"),
    "swimming_basketball": ExerciseGuide(["วอร์มอัป 5 นาทีด้วยการว่ายเบา ๆ หรือเลี้ยงบอลเบา ๆ", "ว่ายน้ำหรือเล่นอย่างน้อย 30 นาทีด้วยจังหวะสม่ำเสมอ", "เหยียดตัวให้สุดในทุกจังหวะการว่าย การยิง หรือการแย่งรีบาวด์", "คูลดาวน์ด้วยการเคลื่อนไหวเบา ๆ และการยืดเหยียด 5 นาที"], ["ข้ามการวอร์มอัปและเริ่มด้วยความเร็วเต็มที่", "ลืมดื่มน้ำระหว่างเล่น"], "ชวนเพื่อนไปด้วย กีฬาที่เล่นเป็นกลุ่มทำต่อเนื่องได้ง่ายกว่า"),
    "table_top": ExerciseGuide(["นั่งงอเข่า เท้าวางราบ และวางมือบนพื้นด้านหลังสะโพก", "ชี้นิ้วไปทางเท้าและกดลงที่มือกับเท้า", "ยกสะโพกขึ้นจนลำตัวเรียบตั้งแต่เข่าถึงไหล่", "ค้างไว้ 15 วินาทีแล้วลดลง รวม 2 เซ็ต"], ["ปล่อยให้สะโพกหย่อนตรงกลาง", "เงยหัวไปข้างหลังจนคอตึง"], "หันนิ้วออกไปด้านข้างถ้าข้อมือรู้สึกเจ็บ"),
    "thoracic_extension": ExerciseGuide(["นั่งบนเก้าอี้ที่แข็งแรงโดยให้ขอบบนของพนักพิงอยู่ใต้สะบักพอดี", "วางมือไว้หลังศีรษะและกางข้อศอกให้กว้าง", "เอนหลังส่วนบนพาดพนักเก้าอี้ช้า ๆ และมองขึ้น", "กลับขึ้นมา ทำ 8 ครั้งแล้วพัก รวม 2 เซ็ต"], ["งอตัวจากหลังส่วนล่างแทนหลังส่วนบน", "ใช้มือดึงหัวไปข้างหน้า"], "ใช้เก้าอี้ที่ไม่ไถลหรือเอียงล้ม และวางเท้าราบกับพื้น"),
    "toe_touch": ExerciseGuide(["ยืนแยกเท้ากว้างเท่าสะโพก ผ่อนเข่า", "พับตัวไปข้างหน้าจากสะโพกและปล่อยมือเอื้อมไปทางปลายเท้า", "ค้างนิ่ง ๆ 20 วินาทีและหายใจช้า ๆ", "ม้วนตัวขึ้นช้า ๆ พัก แล้วทำซ้ำอีกหนึ่งครั้ง"], ["เด้งตัวเพื่อเอื้อมให้ไกลขึ้น", "เหยียดเข่าตรงจนล็อก"], "ถ้าแตะปลายเท้าไม่ถึง ให้หยุดที่หน้าแข้ง ก็ยังได้ผลอยู่"),
    "tuck_jumps": ExerciseGuide(["ยืนตัวตรง แยกเท้ากว้างเท่าสะโพก", "ย่อลงเร็ว ๆ ประมาณหนึ่งในสี่สควอต แล้วกระโดดให้สูงที่สุดเท่าที่ทำได้", "ดึงเข่าทั้งสองเข้าหาอกข้างบน แล้วลงนุ่ม ๆ ด้วยเข่าที่งอ", "กระโดด 6 ครั้ง พัก แล้วทำซ้ำรวม 3 เซ็ต"], ["ก้มอกลงหาเข่าแทนที่จะยกเข่าขึ้น", "ลงพื้นแรง ๆ ด้วยขาเหยียดตรง"], "ตั้งการทรงตัวใหม่ระหว่างการกระโดด และมั่นใจว่ามีที่โล่งและพื้นไม่ลื่น"),
    "upward_salute": ExerciseGuide(["ยืนชิดเท้า แขนอยู่ข้างลำตัว", "หายใจเข้าและเหยียดแขนทั้งสองขึ้นเหนือศีรษะ", "ให้ซี่โครงลงและไหล่ห่างจากหู", "ค้างไว้ 15 วินาทีพร้อมหายใจช้า ๆ แล้วลดแขนลง รวม 2 เซ็ต"], ["เอนไปข้างหลังและแอ่นหลังส่วนล่าง", "ปล่อยให้ซี่โครงดันไปข้างหน้า"], "เอื้อมขึ้นไม่ใช่ไปข้างหลัง ให้ลำตัวซ้อนตรงเหนือเท้า"),
    "wall_angels": ExerciseGuide(["ยืนพิงหลังกับผนัง เท้าอยู่ข้างหน้าเล็กน้อย", "วางแขนบนผนังโดยงอข้อศอก เหมือนเสาประตูฟุตบอล", "ให้ซี่โครงลงและค่อย ๆ เลื่อนแขนขึ้น แล้วเลื่อนกลับลง", "ทำช้า ๆ 8 ครั้งต่อเซ็ต รวม 2 เซ็ต"], ["ปล่อยให้ซี่โครงบานและหลังส่วนล่างแอ่น", "ปล่อยให้แขนลอยจากผนัง"], "ขึ้นสูงแค่ที่แขนยังแนบผนังได้ จะง่ายขึ้นเมื่อฝึกบ่อย ๆ"),
    "wall_dog": ExerciseGuide(["ยืนหันหน้าเข้าผนัง ห่างประมาณหนึ่งช่วงขา", "วางมือบนผนังที่ระดับสะโพก", "พับตัวถอยจากสะโพกจนแขนเหยียดตรงและกระดูกสันหลังยาว", "ค้างไว้ 20 วินาทีพร้อมหายใจช้า ๆ รวม 2 เซ็ต"], ["ก้มหลังส่วนบนโค้ง", "งอข้อศอกและเอนพิงผนัง"], "เป็นการพักที่ดีที่โต๊ะทำงานเมื่อลงไปนอนพื้นไม่ได้"),
    "wall_sit": ExerciseGuide(["ยืนพิงหลังกับผนัง เท้าอยู่ข้างหน้าหนึ่งก้าว", "ไถลตัวลงจนต้นขาขนานกับพื้น", "ให้เข่าอยู่เหนือข้อเท้าและหลังทั้งแผ่นแนบผนัง", "ค้างไว้ 20 วินาทีแล้วยืนขึ้น รวม 3 เซ็ต"], ["วางมือไว้บนต้นขา", "ปล่อยให้เข่าเลยปลายเท้าไปข้างหน้า"], "นั่งให้สูงขึ้นเล็กน้อยถ้าเข่าไม่ไหว และลงให้ต่ำขึ้นเมื่อแข็งแรงขึ้น"),
    "wall_stand": ExerciseGuide(["ยืนให้ส้นเท้าแนบผนัง เท้าแยกกว้างเท่าสะโพก", "ให้ก้น สะบัก และท้ายทอยแตะผนัง", "เก็บคางเล็กน้อยและผ่อนแขนไว้ข้างลำตัว", "ค้างไว้ 5 นาที หายใจเข้าออกทางจมูกอย่างสงบ"], ["แอ่นหลังส่วนล่างห่างจากผนังมาก", "เงยคางขึ้นแทนที่จะให้อยู่ระดับเดียวกัน"], "สังเกตความรู้สึกนี้ แล้วลองนำไปใช้ตลอดวัน"),
  },
  "vi": {
    "band_pull_apart": ExerciseGuide(["Đứng thẳng, cầm dây kháng lực trước mặt, hai tay thẳng ngang vai.", "Kéo dây ra hai bên bằng cách ép hai bả vai lại gần nhau.", "Chạm dây vào ngực, rồi từ từ trả về.", "Tập 12 lần rồi nghỉ, tổng cộng 2 hiệp."], ["Nhún vai lên gần tai.", "Để dây bật mạnh trở lại thay vì từ từ trả về."], "Chọn dây đủ nhẹ để hoàn thành mọi lần với tư thế đúng, và kiểm tra xem dây có bị rách không."),
    "bar_hanging": ExerciseGuide(["Nắm xà bằng hai tay úp, rộng bằng vai.", "Nhấc chân lên và để cơ thể buông thẳng, thả lỏng.", "Giữ vai hơi gồng nhẹ và thở chậm trong 30 giây.", "Xuống nhẹ nhàng, nghỉ 30 đến 60 giây rồi lặp lại, tổng cộng 3 hiệp."], ["Đung đưa hoặc đá chân khi đang treo.", "Buông tay rơi khỏi xà thay vì bước xuống nhẹ nhàng."], "Bắt đầu với thời gian treo ngắn và mỗi tuần thêm vài giây."),
    "bird_dog": ExerciseGuide(["Bắt đầu ở tư thế bò bốn chân, tay dưới vai, gối dưới hông.", "Duỗi một tay ra trước và chân đối diện thẳng ra sau.", "Giữ hai giây, hông ngay ngắn, rồi trở về.", "Tập 8 lần, đổi bên, mỗi bên 2 hiệp."], ["Để lưng dưới võng xuống khi nhấc chân.", "Xoay mở hông để nâng chân cao hơn."], "Hãy tưởng tượng có một ly nước đặt trên lưng dưới và không được để đổ."),
    "bow_pose": ExerciseGuide(["Nằm sấp và gập gối để gót chân đưa về phía hông.", "Với tay ra sau nắm lấy cả hai mắt cá chân.", "Đá bàn chân vào tay để nâng ngực và đùi lên.", "Giữ 10 giây rồi hạ xuống từ từ, tổng cộng 2 hiệp."], ["Để hai gối mở rộng hơn hông.", "Ngửa đầu ra sau làm căng cổ."], "Chỉ nâng lên mức thấy thoải mái, và bỏ qua động tác này nếu lưng dưới bị đau."),
    "broad_jumps": ExerciseGuide(["Đứng hai chân rộng bằng hông, mũi chân sát sau một vạch kẻ.", "Vung tay ra sau, gập gối và đẩy hông ra sau.", "Vung tay ra trước, bật xa hết mức và tiếp đất bằng cả hai chân.", "Giữ vững tư thế tiếp đất một giây, đi bộ về và bật 5 lần, tổng cộng 3 hiệp."], ["Ngã về trước hoặc về sau khi tiếp đất.", "Tiếp đất với đầu gối khóa thẳng."], "Bật trên mặt sàn không trơn, và bật ngắn hơn cho đến khi bạn giữ vững được mọi lần tiếp đất."),
    "burpees": ExerciseGuide(["Đứng thẳng, rồi hạ người squat và đặt hai tay xuống sàn.", "Bật hai chân ra sau về tư thế plank thẳng.", "Bật hai chân thu về phía hai tay.", "Bật thẳng lên cao, tập 5 lần rồi nghỉ, tổng cộng 3 hiệp."], ["Để hông võng xuống khi plank.", "Tiếp đất mạnh với hai chân thẳng sau cú bật."], "Bước chân ra sau rồi thu vào thay vì bật để nhẹ hơn, và chậm lại nếu tư thế bắt đầu sai."),
    "calf_pulses": ExerciseGuide(["Đứng thẳng và kiễng lên bằng mũi chân, chạm đầu ngón tay vào tường nếu cần giữ thăng bằng.", "Nhún lên xuống bằng những nhịp nhỏ, chỉ vài centimet.", "Giữ gót chân cách sàn trong suốt cả hiệp.", "Tiếp tục trong 20 giây, tổng cộng 3 hiệp."], ["Để gót chân chạm sàn giữa các nhịp.", "Nhún biên độ quá lớn đến mức không còn là nhịp nhún nhỏ."], "Bắp chân nóng rát là bình thường. Đau nhói thì dừng lại."),
    "calf_raise": ExerciseGuide(["Đứng thẳng cạnh tường, chạm đầu ngón tay vào tường để giữ thăng bằng.", "Từ từ kiễng lên bằng phần bàn chân trước, cao hết mức có thể.", "Giữ 1 giây ở trên cao, rồi từ từ hạ gót xuống.", "Tập 15 lần mỗi hiệp, tổng cộng 3 hiệp."], ["Nhún nhanh thay vì di chuyển chậm rãi.", "Để cổ chân lật ra ngoài ở phía trên."], "Hãy tập trong lúc đánh răng để dễ thành thói quen hằng ngày."),
    "cat_cow": ExerciseGuide(["Bắt đầu ở tư thế bò bốn chân, cổ tay dưới vai, gối dưới hông.", "Hít vào, hạ bụng xuống và ngẩng ngực, mắt nhìn lên (tư thế bò).", "Thở ra, cong lưng lên và hạ cằm (tư thế mèo).", "Di chuyển chậm theo nhịp thở trong 10 vòng, 2 hiệp."], ["Di chuyển nhanh hơn nhịp thở.", "Chỉ cử động cổ thay vì cả cột sống."], "Rất hợp làm động tác đầu tiên buổi sáng hoặc để lấy lại cảm giác thoải mái sau khi ngồi lâu."),
    "chest_stretch": ExerciseGuide(["Đứng trong khung cửa và đặt một cẳng tay lên khung, khuỷu tay ngang vai.", "Bước chân cùng bên về phía trước qua khung cửa.", "Nghiêng ngực về trước cho đến khi thấy căng phía trước vai.", "Giữ 20 giây, đổi bên, mỗi bên 2 hiệp."], ["Ưỡn lưng dưới để nghiêng sâu hơn.", "Nhún vai lên gần tai."], "Giãn nhẹ nhàng, và giảm lực nếu thấy nhói ở vai."),
    "childs_pose": ExerciseGuide(["Quỳ trên sàn, hai ngón chân cái chạm nhau, hai gối mở rộng.", "Ngồi lùi hông xuống gót chân.", "Đưa hai tay về phía trước và đặt trán xuống sàn.", "Thở chậm trong 30 giây rồi ngồi dậy, tổng cộng 2 hiệp."], ["Nhấc hông cách xa gót chân để với xa hơn.", "Nín thở và gồng vai."], "Kê một chiếc gối giữa hông và gót chân nếu đầu gối thấy căng."),
    "chin_tucks": ExerciseGuide(["Ngồi hoặc đứng thẳng và nhìn thẳng về phía trước.", "Đưa cằm thẳng ra sau, như thể đang tạo cằm hai ngấn.", "Giữ 3 giây rồi thả lỏng.", "Tập 8 lần mỗi hiệp, tổng cộng 2 hiệp."], ["Gật đầu xuống thay vì đưa cằm ra sau.", "Đẩy mạnh đến mức đau cổ."], "Làm vài lần mỗi khi bạn đặt điện thoại xuống."),
    "cobra_stretch": ExerciseGuide(["Nằm sấp, hai bàn tay đặt phẳng dưới vai.", "Đẩy sàn ra xa và từ từ nâng ngực lên, hông vẫn giữ sát sàn.", "Giữ khuỷu tay hơi gập và vai tránh xa tai.", "Giữ 15 giây, thở chậm, rồi hạ xuống có kiểm soát."], ["Đẩy lên quá cao đến mức lưng dưới bị nhói.", "Nhún vai lên sát tai."], "Chỉ nâng lên mức thấy thoải mái; tập dần sẽ sâu hơn."),
    "dead_bug": ExerciseGuide(["Nằm ngửa, hai tay thẳng lên trên và hai gối gập phía trên hông.", "Nhẹ nhàng ép lưng dưới xuống sàn.", "Hạ một tay qua đầu và chân đối diện xuống gần sàn, rồi trở về.", "Tập 8 lần mỗi bên rồi nghỉ, tổng cộng 2 hiệp."], ["Để lưng dưới ưỡn khỏi sàn.", "Làm vội vàng cho xong các lần."], "Chỉ hạ tay và chân đến mức lưng vẫn giữ phẳng trên sàn."),
    "dead_hang_active": ExerciseGuide(["Nắm xà bằng hai tay úp, rộng hơn vai một chút.", "Treo người với tay thẳng, rồi kéo hai bả vai xuống và về phía sau.", "Giữ hai chân khép, cơ lõi siết chặt và giữ 20 giây.", "Xuống nhẹ nhàng và nghỉ 40 giây giữa các hiệp."], ["Gập khuỷu tay như khi kéo xà.", "Nhún vai lên sát tai."], "Hãy nghĩ đến việc đẩy xà ra xa để cảm nhận vai đang làm việc."),
    "deadlift_stretch": ExerciseGuide(["Đứng hai chân rộng bằng hông, gối hơi chùng.", "Gập người từ khớp hông và trượt hai tay xuống dọc đùi.", "Giữ lưng phẳng và với về phía mũi chân cho đến khi cơ đùi sau căng giãn.", "Siết cơ mông để đứng thẳng lên, 12 lần chậm mỗi hiệp."], ["Cong lưng để với xuống thấp hơn.", "Khóa gối thẳng hoàn toàn."], "Di chuyển chậm; kiểm soát quan trọng hơn việc với xa đến đâu."),
    "downward_dog": ExerciseGuide(["Bắt đầu ở tư thế bò bốn chân, tay dưới vai.", "Nâng hông thật cao để cơ thể tạo thành hình chữ V ngược.", "Giữ cột sống dài và để gót chân hạ dần về phía sàn.", "Giữ 20 giây rồi nghỉ, tổng cộng 2 hiệp."], ["Cong lưng để ép gót chân xuống.", "Nhún vai lên sát tai."], "Gập gối một chút nếu lưng bị cong. Gót chân không cần chạm sàn."),
    "dumbbell_deadlift": ExerciseGuide(["Đứng thẳng, mỗi tay cầm một tạ đơn trước đùi.", "Chùng gối nhẹ và đẩy hông ra sau với lưng phẳng.", "Trượt tạ xuống dọc đùi đến ngay dưới gối.", "Siết cơ mông để đứng lên, tập 8 lần, tổng cộng 3 hiệp."], ["Cong lưng khi hạ tạ xuống.", "Biến động tác thành squat vì gập gối quá nhiều."], "Chọn mức tạ đủ nhẹ để hoàn thành mọi lần với tư thế đúng."),
    "dumbbell_row": ExerciseGuide(["Đặt một tay lên ghế băng hoặc ghế và bước hai chân ra sau.", "Cầm tạ đơn ở tay còn lại, lưng phẳng và tay buông thõng xuống.", "Kéo tạ về phía hông, khuỷu tay sát người, rồi từ từ hạ xuống.", "Tập 8 lần mỗi bên rồi nghỉ, tổng cộng 3 hiệp."], ["Xoay người để vung tạ lên.", "Nhún vai lên gần tai."], "Chọn mức tạ đủ nhẹ để hoàn thành mọi lần với tư thế đúng."),
    "evening_yoga": ExerciseGuide(["Bắt đầu ở tư thế bò bốn chân và chuyển động nhịp nhàng giữa Mèo và Bò trong 60 giây.", "Ngồi lùi về tư thế em bé, tay duỗi dài, và thở trong 60 giây.", "Chống người lên tư thế chó cúi mặt, gót chân với về phía sàn.", "Đứng dậy và gập người về trước, để đầu buông thõng nặng.", "Hít vào đếm 4 và thở ra đếm 6 ở mỗi tư thế."], ["Chuyển vội giữa các tư thế thay vì giữ lại.", "Cố ép tư thế đến mức đau."], "Giảm độ sáng đèn khi tập để cơ thể dễ thư giãn hơn."),
    "farmer_carry": ExerciseGuide(["Đứng giữa hai tạ đơn hoặc hai túi có đồ nặng.", "Gập gối, giữ lưng phẳng và nhấc chúng lên.", "Đi bước nhỏ, vai ra sau và mắt nhìn thẳng.", "Đi 20 giây, đặt tạ xuống và nghỉ, tổng cộng 3 hiệp."], ["Nghiêng về một bên hoặc để vai khom về trước.", "Cong lưng khi nhấc hoặc đặt tạ xuống."], "Chọn mức tạ đủ nhẹ để hoàn thành mọi hiệp với tư thế đúng, và giữ hai bên đều nhau."),
    "glute_bridge": ExerciseGuide(["Nằm ngửa, gối gập, bàn chân đặt phẳng trên sàn rộng bằng hông.", "Đạp qua gót chân và nâng hông lên phía trần nhà.", "Siết cơ mông ở trên cao trong 2 giây.", "Hạ xuống từ từ, 12 lần mỗi hiệp, tổng cộng 3 hiệp."], ["Đạp bằng mũi chân thay vì gót chân.", "Ưỡn lưng dưới quá mức ở phía trên."], "Nếu bạn cảm nhận ở cơ mông chứ không phải lưng dưới, bạn đang làm đúng."),
    "goblet_squat": ExerciseGuide(["Ôm một tạ đơn hoặc ba lô nặng sát ngực bằng cả hai tay.", "Đứng hai chân rộng bằng vai, mũi chân hơi xoay ra ngoài.", "Ngồi xuống giữa hai gót chân, ngực ưỡn lên, rồi đứng dậy.", "Tập 8 lần rồi nghỉ, tổng cộng 3 hiệp."], ["Để hai gối cụp vào trong.", "Cong lưng và để ngực chúi xuống."], "Chọn mức tạ đủ nhẹ để hoàn thành mọi lần với tư thế đúng."),
    "hanging_knee_raise": ExerciseGuide(["Nắm xà bằng hai tay úp và treo người với tay thẳng.", "Kéo vai xuống, tránh xa tai.", "Nâng hai gối đến ngang hông mà không đung đưa, rồi từ từ hạ xuống.", "Tập 5 lần, xuống khỏi xà và nghỉ, tổng cộng 3 hiệp."], ["Đung đưa người để hất gối lên.", "Treo người với vai nhún sát tai."], "Kiểm tra xà có chắc chắn không trước khi treo, và bước xuống thay vì buông rơi."),
    "high_knees": ExerciseGuide(["Đứng thẳng, hai chân rộng bằng hông.", "Chạy tại chỗ và nâng từng gối lên ngang hông.", "Vung tay mạnh và giữ nhẹ nhàng trên phần bàn chân trước.", "Tiếp tục trong 20 giây, tổng cộng 3 hiệp."], ["Ngả người ra sau khi gối nâng lên.", "Dậm chân bằng cả bàn chân xuống sàn."], "Giảm tốc thành bước đi nâng cao gối nếu bạn bị hụt hơi."),
    "hiit_workout": ExerciseGuide(["Khởi động 3 phút bằng đi bộ tại chỗ và xoay tay.", "Tập burpee, mountain climber và squat nhảy, mỗi động tác 45 giây.", "Nghỉ 15 giây giữa các động tác và hít thở sâu.", "Hoàn thành 4 vòng, rồi đi bộ chậm cho đến khi nhịp thở ổn định."], ["Để tư thế sai đi chỉ vì muốn nhanh hơn.", "Nín thở trong các quãng cường độ cao."], "Tập theo nhịp của bạn; hoàn thành đủ 4 vòng quan trọng hơn là khởi đầu thật nhanh."),
    "hip_flexor_stretch": ExerciseGuide(["Quỳ một gối, bàn chân kia đặt phẳng phía trước.", "Cuộn nhẹ xương chậu về phía trước và siết cơ mông của chân sau.", "Từ từ dịch người về trước cho đến khi thấy căng ở phía trước hông.", "Giữ 30 giây, thở chậm, rồi đổi bên."], ["Ưỡn lưng dưới thay vì cuộn xương chậu.", "Để gối trước vượt quá mũi chân."], "Lót một chiếc khăn gấp dưới đầu gối cho dễ chịu hơn."),
    "inversion_hang": ExerciseGuide(["Chỉ treo ngược khi có người lớn giám sát và dùng thiết bị chắc chắn đã kiểm tra.", "Khóa chặt mắt cá chân và bắt đầu ở độ nghiêng nhẹ, không lộn ngược hoàn toàn.", "Thả lỏng tay và thở chậm tối đa 1 phút.", "Từ từ trở lại tư thế thẳng và ngồi nghỉ một lát trước khi đứng dậy.", "Dừng ngay nếu bạn thấy chóng mặt, nặng đầu hoặc đau ở bất kỳ chỗ nào."], ["Lộn ngược hoàn toàn ngay từ những buổi đầu.", "Đứng dậy nhanh ngay sau khi treo ngược."], "Các buổi ngắn và nhẹ nhàng là đủ; không cần treo lâu hơn."),
    "jump_squats": ExerciseGuide(["Đứng hai chân rộng bằng vai, ngực ưỡn lên.", "Ngồi lùi xuống squat cho đến khi đùi gần song song với sàn.", "Đạp mạnh qua bàn chân, bật thẳng lên và tiếp đất nhẹ nhàng trở lại tư thế squat.", "Bật 8 lần, nghỉ rồi lặp lại, tổng cộng 3 hiệp."], ["Để hai gối cụp vào trong khi tiếp đất.", "Tiếp đất với hai chân cứng và thẳng."], "Tiếp đất êm nhất có thể, và dừng hiệp tập khi tiếp đất bắt đầu nặng tiếng."),
    "jumping": ExerciseGuide(["Đứng hai chân rộng bằng hông, hai tay thả lỏng hai bên người.", "Gập gối, vung tay và bật thẳng lên.", "Tiếp đất nhẹ nhàng bằng phần bàn chân trước, gối hơi chùng.", "Bật 20 lần, nghỉ 30 giây rồi lặp lại, tổng cộng 3 hiệp."], ["Tiếp đất bằng gót với chân cứng đơ.", "Để hai gối cụp vào trong khi tiếp đất."], "Tiếp đất êm nghĩa là bạn kiểm soát tốt, hãy thử tiếp đất như một chú mèo."),
    "knee_circles": ExerciseGuide(["Đứng hai chân khép, gối hơi chùng.", "Đặt hai tay lên đầu gối.", "Xoay gối thành những vòng nhỏ, chậm trong 15 giây theo một hướng.", "Đổi hướng và xoay 15 giây theo chiều ngược lại."], ["Xoay vòng lớn làm xoắn đầu gối.", "Chỉ xoay theo một hướng."], "Dùng làm bài khởi động trước khi nhảy hoặc chạy."),
    "legs_up_wall": ExerciseGuide(["Ngồi nghiêng cạnh tường, một bên hông chạm tường.", "Vung chân lên tường khi bạn nằm ngửa xuống sàn.", "Để hai tay thả hai bên người và thư giãn chân dựa vào tường.", "Giữ yên 3 phút, thở chậm."], ["Nhấc lưng dưới khỏi sàn.", "Khóa chặt gối và gồng chân."], "Dịch hông ra xa tường một chút nếu mặt sau chân thấy căng."),
    "low_lunge_arch": ExerciseGuide(["Bước một chân lên trước và hạ gối sau xuống sàn.", "Trượt hông về trước cho đến khi thấy căng ở phía trước hông của chân sau.", "Vươn hai tay lên và nâng ngực thành một đường cong nhẹ.", "Giữ 20 giây, đổi chân, mỗi bên 2 hiệp."], ["Để gối trước đi quá xa mũi chân.", "Chỉ uốn cong từ lưng dưới."], "Lót một chiếc khăn gấp dưới gối sau, và giữ độ cong nhỏ."),
    "lunges": ExerciseGuide(["Đứng thẳng, hai chân rộng bằng hông.", "Bước một bước dài về trước và hạ người cho đến khi cả hai gối gập khoảng 90 độ.", "Đạp qua gót chân trước để bước về vị trí ban đầu.", "Tập 8 lần mỗi chân rồi nghỉ, tổng cộng 3 hiệp."], ["Để gối trước cụp vào trong.", "Nghiêng ngực quá xa về trước qua chân trước."], "Bước ngắn hơn hoặc vịn vào ghế để giữ thăng bằng cho đến khi động tác vững."),
    "masai_jumps": ExerciseGuide(["Đứng thẳng, hai tay thả hai bên hoặc vươn lên.", "Bật nhẹ những bước nhỏ, nảy và giữ thân người thẳng suốt thời gian đó.", "Tiếp đất nhẹ nhàng bằng phần bàn chân trước, gối hơi chùng.", "Tiếp tục trong 20 giây, tổng cộng 3 hiệp."], ["Tiếp đất mạnh bằng gót chân.", "Khom người về trước khi mệt."], "Dừng lại nếu đầu gối hoặc ống chân bị đau, và nghỉ rồi hãy thử lại."),
    "morning_stretch": ExerciseGuide(["Đứng thẳng và xoay cổ chậm rãi, 5 vòng mỗi hướng.", "Vươn hai tay lên cao, đan các ngón tay vào nhau và kéo giãn lên trên 30 giây.", "Gập người từ hông và để hai tay buông thõng về phía mũi chân.", "Bước vào tư thế lunge, giữ 30 giây rồi đổi chân.", "Thở chậm bằng mũi và đừng bao giờ nhún để giãn sâu hơn."], ["Nhún để giãn sâu hơn thay vì giữ yên.", "Nín thở khi giữ tư thế."], "Hãy giãn cơ trước khi kiểm tra điện thoại, thói quen sẽ bền hơn."),
    "mountain_pose": ExerciseGuide(["Đứng hai chân khép, trọng lượng dồn đều lên hai chân.", "Vươn hai tay thẳng lên cao, hai lòng bàn tay hướng vào nhau.", "Kiễng lên bằng mũi chân và vươn dài qua các đầu ngón tay.", "Giữ 20 giây và hạ xuống từ từ, tổng cộng 2 hiệp."], ["Bung xương sườn và ưỡn lưng dưới.", "Nhún vai lên sát tai."], "Nhìn cố định vào một điểm phía trước, hoặc giữ gót chân chạm sàn nếu bạn bị chao đảo."),
    "neck_stretches": ExerciseGuide(["Ngồi hoặc đứng thẳng, vai thả lỏng và hạ thấp.", "Từ từ nghiêng tai về phía vai và giữ 30 giây mỗi bên.", "Hạ cằm về phía ngực và giữ 30 giây.", "Nhẹ nhàng ngẩng mắt lên trong 30 giây mà không ngửa đầu ra sau."], ["Dùng tay kéo mạnh đầu.", "Nhún vai lên để chạm tai."], "Hãy tập sau những buổi học dài để xả căng thẳng."),
    "overhead_press": ExerciseGuide(["Đứng thẳng, cầm tạ nhẹ hoặc chai nước ngang vai.", "Siết cơ lõi và đẩy hai tay thẳng lên trên đầu.", "Kết thúc với hai tay sát tai, rồi từ từ hạ về vai.", "Thở ra khi đẩy lên, hít vào khi hạ xuống, 10 lần mỗi hiệp."], ["Ưỡn lưng dưới khi đẩy.", "Dùng tạ quá nặng để kiểm soát."], "Bắt đầu với trọng lượng cơ thể và thêm tạ nhẹ khi tư thế đã thấy dễ."),
    "pelvic_shift": ExerciseGuide(["Nằm ngửa, gối gập và bàn chân đặt phẳng trên sàn.", "Cuộn xương cụt và bóc cột sống khỏi sàn từ dưới lên.", "Dừng lại ở trên cao, rồi hạ xuống từ từ, từng đốt sống một.", "Tập 10 lần chậm rồi nghỉ, tổng cộng 2 hiệp."], ["Đẩy hông lên nhanh thành một khối.", "Ưỡn lưng dưới ở phía trên."], "Di chuyển đủ chậm để cảm nhận từng phần lưng chạm xuống sàn."),
    "pilates_core": ExerciseGuide(["Giữ plank cẳng tay 1 phút, cơ thể thành một đường thẳng.", "Nằm ngửa tập dead bug, hạ tay và chân đối diện thật chậm.", "Chuyển sang bird dog ở tư thế bò bốn chân, duỗi tay và chân đối diện.", "Kết thúc với 1 phút cầu mông và 1 phút nâng chân.", "Thở ra mỗi khi siết cơ lõi."], ["Để hông võng xuống trong lúc plank.", "Ưỡn lưng dưới khỏi sàn trong lúc tập dead bug."], "Chậm và có kiểm soát tốt hơn nhanh; mỗi lần tập chuẩn đều tạo ra sức mạnh thật sự."),
    "pilates_roll_over": ExerciseGuide(["Nằm ngửa, hai tay dọc hai bên người và hai chân thẳng lên trên.", "Ép hai tay xuống sàn và nhấc hông để cuộn hai chân qua đầu.", "Dừng lại khi hai chân song song với sàn phía sau đầu.", "Cuộn xuống từ từ, tập 5 lần rồi nghỉ, tổng cộng 2 hiệp."], ["Vung chân qua đầu bằng đà.", "Cuộn lên cổ thay vì lên vai."], "Dồn trọng lượng lên vai chứ không bao giờ lên cổ, và gập gối để dễ hơn."),
    "plank": ExerciseGuide(["Đặt cẳng tay xuống sàn, khuỷu tay dưới vai.", "Bước hai chân ra sau để cơ thể tạo thành một đường thẳng.", "Siết cơ mông, hóp rốn vào và giữ 30 giây.", "Nghỉ 30 giây rồi lặp lại, tổng cộng 3 hiệp."], ["Để hông võng xuống sàn.", "Nhô hông lên quá cao."], "Thêm 5 giây mỗi tuần khi thấy dễ hơn."),
    "pogo_jumps": ExerciseGuide(["Đứng thẳng, hai chân rộng bằng hông, hai tay chống hông.", "Nảy lên bằng phần bàn chân trước với gối gần như thẳng.", "Mỗi lần chạm đất thật ngắn và nhanh, như cây nhảy pogo.", "Tiếp tục trong 20 giây, tổng cộng 3 hiệp."], ["Gập sâu gối ở mỗi lần nảy.", "Để gót chân đập mạnh xuống sàn."], "Nhảy trên mặt phẳng, chắc chắn và dừng lại nếu ống chân hoặc cổ chân bị đau."),
    "posture_check": ExerciseGuide(["Đặt nhắc nhở mỗi giờ để kiểm tra tư thế ngồi hoặc đứng của bạn.", "Xếp tai thẳng trên vai, vai thẳng trên hông.", "Xoay vai ra sau và hạ xuống, ngực mở nhẹ.", "Tưởng tượng có sợi dây kéo đỉnh đầu lên cao, rồi hít thở."], ["Chỉnh quá mức, khiến lưng cứng và ưỡn.", "Cúi nhìn điện thoại với đầu chúi về trước."], "Nâng màn hình ngang tầm mắt và tư thế tốt sẽ thành tự nhiên."),
    "pre_sleep_routine": ExerciseGuide(["Bắt đầu trước giờ ngủ 30 phút: giảm độ sáng đèn và cất màn hình đi.", "Đọc sách hoặc nghe nhạc nhẹ nhàng trong 15 phút.", "Giãn cơ nhẹ nhàng 5 phút trên giường hoặc trên sàn.", "Hít vào 4 giây và thở ra 6 giây, 10 vòng."], ["Lướt điện thoại thêm một phút nữa.", "Thay đổi giờ đi ngủ quá nhiều giữa các đêm."], "Cùng một giờ, cùng các bước mỗi đêm giúp bạn dễ ngủ hơn."),
    "pull_ups": ExerciseGuide(["Nắm xà bằng hai tay úp, rộng hơn vai một chút.", "Bắt đầu từ tư thế treo tay thẳng và kéo hai bả vai xuống.", "Kéo cho đến khi cằm vượt qua xà, rồi hạ người xuống từ từ.", "Tập 2 lần, xuống khỏi xà và nghỉ, tổng cộng 3 hiệp."], ["Đá chân và đung đưa để vượt qua xà.", "Buông người rơi nhanh thay vì hạ xuống có kiểm soát."], "Luồn dây kháng lực dưới chân hoặc nhảy lên vị trí trên cùng rồi hạ xuống chậm, và kiểm tra xà có chắc chắn không."),
    "puppy_pose": ExerciseGuide(["Bắt đầu ở tư thế bò bốn chân, hông ngay trên đầu gối.", "Đi hai tay về trước và giữ nguyên vị trí hông.", "Để ngực và trán hạ dần xuống sàn.", "Giữ 20 giây rồi quay lại, tổng cộng 2 hiệp."], ["Để hông trượt về phía gót chân.", "Gập khuỷu tay và đặt chúng xuống sàn."], "Tựa trán lên một chiếc gối nếu cảm giác căng ở vai quá mạnh."),
    "push_ups": ExerciseGuide(["Đặt hai tay xuống sàn, rộng hơn vai một chút.", "Bước hai chân ra sau để cơ thể tạo thành một đường thẳng.", "Gập khuỷu tay để hạ ngực xuống sàn, rồi đẩy người lên.", "Tập 5 lần rồi nghỉ, tổng cộng 3 hiệp."], ["Để hông võng xuống sàn.", "Mở khuỷu tay thẳng ra hai bên."], "Quỳ gối hoặc đặt tay lên ghế băng để dễ hơn."),
    "scapular_pull": ExerciseGuide(["Nắm xà bằng hai tay úp, rộng hơn vai một chút.", "Treo người với tay thẳng và để vai nhô lên gần tai.", "Kéo hai bả vai xuống để cơ thể nhích lên một chút, khuỷu tay thẳng.", "Giữ một giây rồi thả ra, tập 5 lần, tổng cộng 3 hiệp."], ["Gập khuỷu tay để kéo cao hơn.", "Đung đưa chân để lấy đà."], "Kiểm tra xà có chắc chắn không, và đặt chân lên bục nếu treo hoàn toàn quá khó."),
    "scapular_retraction": ExerciseGuide(["Ngồi hoặc đứng thẳng, hai tay thả lỏng hai bên người.", "Kéo hai bả vai ra sau và xuống dưới, như thể nhét chúng vào túi quần sau.", "Giữ ép trong một hơi thở chậm, rồi thả ra.", "Tập 10 lần rồi nghỉ, tổng cộng 2 hiệp."], ["Nhún vai lên khi ép.", "Đẩy xương sườn ra trước và ưỡn lưng."], "Giữ cằm ngang và cổ thả lỏng suốt thời gian tập."),
    "seated_forward_fold": ExerciseGuide(["Ngồi trên sàn, hai chân duỗi thẳng, mũi chân hướng lên.", "Ngồi thẳng lưng và vươn hai tay lên cao.", "Gập người về trước từ khớp hông và với tới cẳng chân hoặc bàn chân.", "Giữ 20 giây rồi ngồi thẳng lại, tổng cộng 2 hiệp."], ["Cong lưng trên để với tới mũi chân.", "Nhún để giãn sâu hơn."], "Gập nhẹ gối hoặc ngồi lên khăn gấp nếu lưng dưới bị cong."),
    "shoulder_rolls": ExerciseGuide(["Đứng thẳng, hai tay buông lỏng hai bên người.", "Xoay vai ra trước thành những vòng lớn 15 lần.", "Xoay vai ra sau 15 lần, ép hai bả vai lại gần nhau.", "Đan hai tay ra sau lưng và mở ngực trong 20 giây."], ["Xoay những vòng nhỏ xíu, vội vàng.", "Nhún vai trong lúc nín thở."], "Một hiệp nhanh giữa các tiết học hoặc buổi học bài giúp vai luôn mở."),
    "side_plank": ExerciseGuide(["Nằm nghiêng, cẳng tay đặt trên sàn, khuỷu tay dưới vai.", "Chồng hai bàn chân lên nhau và nâng hông khỏi sàn.", "Giữ cơ thể thành một đường thẳng từ đầu đến gót chân.", "Giữ 15 giây, đổi bên, mỗi bên 2 hiệp."], ["Để hông hạ xuống sàn.", "Xoay ngực chúi về trước xuống sàn."], "Giữ đầu gối dưới chạm sàn để dễ hơn."),
    "single_leg_calf_raise": ExerciseGuide(["Đứng trên mép bậc thang bằng phần bàn chân trước của một chân và vịn vào tường hoặc lan can.", "Từ từ hạ gót chân xuống thấp hơn mặt bậc.", "Kiễng lên cao hết mức trên mũi chân và dừng một giây.", "Tập 8 lần mỗi chân rồi nghỉ, tổng cộng 3 hiệp."], ["Nảy lên từ vị trí thấp thay vì di chuyển chậm.", "Gập gối để cơ bắp chân đỡ phải làm."], "Bắt đầu với trọng lượng cơ thể, và nếu cầm thêm tạ đơn hoặc ba lô, hãy chọn mức đủ nhẹ để hoàn thành mọi lần với tư thế đúng."),
    "single_leg_hops": ExerciseGuide(["Đứng trên một chân, chân kia nhấc ra sau.", "Nhảy nhỏ tại chỗ, tiếp đất bằng phần bàn chân trước.", "Giữ hông ngang và gối chân trụ hơi chùng.", "Nhảy 8 lần, đổi chân, mỗi bên 2 hiệp."], ["Để gối của chân nhảy cụp vào trong.", "Nhảy cao đến mức mất thăng bằng."], "Đứng gần một bức tường để có thể chạm vào, và nhảy thấp cho đến khi thăng bằng vững."),
    "skipping_rope": ExerciseGuide(["Cầm tay cầm ngang hông, khuỷu tay sát hai bên người.", "Quay dây bằng cổ tay, không phải cả cánh tay.", "Nhảy vừa đủ cao để dây lướt qua, tiếp đất bằng phần bàn chân trước.", "Nhảy dây 5 phút, nghỉ 1 phút rồi lặp lại, tổng cộng 3 hiệp."], ["Nhảy quá cao khiến nhanh mệt.", "Tiếp đất cả bàn chân bằng gót."], "Vướng dây là chuyện bình thường; cứ bắt đầu lại và giữ nhịp."),
    "spinal_twist": ExerciseGuide(["Nằm ngửa, hai tay dang ra hai bên.", "Gập một gối và đưa nó chéo qua người xuống phía sàn.", "Giữ cả hai vai chạm sàn và nhìn sang bên đối diện.", "Giữ 20 giây, đổi bên, mỗi bên 2 hiệp."], ["Để vai bên đối diện nhấc khỏi sàn.", "Dùng tay ép gối xuống."], "Đặt đầu gối lên một chiếc gối nếu nó không chạm tới sàn."),
    "sprint_intervals": ExerciseGuide(["Khởi động 5 phút bằng chạy bộ nhẹ và vung chân.", "Chạy nước rút hết sức trong 30 giây, vung tay mạnh.", "Đi bộ hoặc chạy chậm 90 giây để hồi sức.", "Lặp lại cho đủ 3 lần nước rút, rồi thả lỏng bằng 5 phút đi bộ."], ["Chạy nước rút mà không khởi động trước.", "Ngả người ra sau và sải bước quá dài thay vì đẩy người về phía trước."], "Chọn mặt phẳng, an toàn và chỉ chạy hết sức khi bạn thấy khỏe."),
    "squats": ExerciseGuide(["Đứng hai chân rộng bằng vai, mũi chân xoay nhẹ ra ngoài.", "Đẩy hông ra sau và hạ người cho đến khi đùi song song với sàn.", "Giữ ngực thẳng và gối cùng hướng với mũi chân.", "Đạp qua gót chân để đứng lên, thở ra khi đi lên."], ["Nhấc gót chân khỏi sàn.", "Cong lưng ở phía dưới."], "Hãy tập những hiệp đầu trước gương để kiểm tra tư thế."),
    "standing_side_stretch": ExerciseGuide(["Đứng thẳng, hai chân rộng bằng hông.", "Vươn hai tay lên cao và dùng một tay nắm cổ tay kia.", "Từ từ nghiêng sang một bên, hai bàn chân ép chặt xuống sàn.", "Giữ 15 giây, đổi bên, mỗi bên 2 hiệp."], ["Nghiêng về trước hoặc xoay người thay vì nghiêng thẳng sang bên.", "Đẩy hông ra xa sang một bên."], "Hãy tưởng tượng bạn đang đứng giữa hai bức tường nên chỉ có thể di chuyển sang bên."),
    "step_ups": ExerciseGuide(["Đứng trước một bậc thang hoặc ghế băng thấp chắc chắn.", "Đặt cả bàn chân của một chân lên bậc và đẩy người lên cho đến khi đứng thẳng.", "Từ từ hạ chân còn lại xuống sàn.", "Tập 8 lần mỗi chân rồi nghỉ, tổng cộng 3 hiệp."], ["Đạp mạnh bằng chân đang đặt trên sàn.", "Buông người rơi nhanh thay vì hạ xuống có kiểm soát."], "Dùng bậc không trượt và không lật, và bắt đầu từ bậc thấp trước khi lên cao hơn."),
    "superman": ExerciseGuide(["Nằm sấp, hai tay vươn về phía trước.", "Nâng tay và chân lên khỏi sàn một chút.", "Giữ cổ dài, nhìn xuống sàn và giữ 2 giây.", "Hạ xuống từ từ, 8 lần mỗi hiệp, tổng cộng 2 hiệp."], ["Gắng nâng ngực và chân lên cao hết mức.", "Ngẩng đầu lên khiến cổ bị chèn ép."], "Nâng một chút là đủ. Nếu lưng dưới bị nhói, hãy nâng thấp hơn."),
    "swimming_basketball": ExerciseGuide(["Khởi động 5 phút bằng bơi nhẹ vài lượt hoặc rê bóng nhẹ.", "Bơi hoặc chơi ít nhất 30 phút với nhịp đều.", "Vươn hết tầm ở mỗi nhịp bơi, cú ném hoặc lần bắt bóng bật bảng.", "Thả lỏng bằng 5 phút vận động nhẹ và giãn cơ."], ["Bỏ qua khởi động và bắt đầu với tốc độ tối đa.", "Quên uống nước khi đang chơi."], "Rủ một người bạn; thể thao dễ duy trì hơn khi có người cùng chơi."),
    "table_top": ExerciseGuide(["Ngồi gối gập, bàn chân đặt phẳng và hai tay chống sàn sau hông.", "Hướng các ngón tay về phía bàn chân rồi ép xuống bằng tay và chân.", "Nâng hông cho đến khi cơ thể phẳng từ gối đến vai.", "Giữ 15 giây rồi hạ xuống, tổng cộng 2 hiệp."], ["Để hông võng xuống ở giữa.", "Ngửa đầu ra sau làm căng cổ."], "Xoay các ngón tay ra hai bên nếu cổ tay thấy đau."),
    "thoracic_extension": ExerciseGuide(["Ngồi trên ghế chắc chắn sao cho mép trên lưng ghế ngay dưới bả vai.", "Đặt hai tay sau đầu và giữ khuỷu tay mở rộng.", "Từ từ ngả lưng trên qua lưng ghế và nhìn lên.", "Trở lại, tập 8 lần rồi nghỉ, tổng cộng 2 hiệp."], ["Uốn từ lưng dưới thay vì lưng trên.", "Dùng tay kéo đầu về phía trước."], "Dùng ghế không lăn và không lật, và giữ bàn chân đặt phẳng trên sàn."),
